    var panel = $("bs-panel");
    if (!panel) return;
    var boxSel = opts.boxSel || ".bs-set-box";
    var colsClass = opts.colsClass || "bs-masonry-cols";
    var colClass = opts.colClass || "bs-masonry-col";
    var boxes = Array.prototype.slice.call(host.querySelectorAll(boxSel)).filter(function (b) {
      return !b.hidden;
    });
    if (!boxes.length) return;
    var w = host.clientWidth || panel.clientWidth || 0;
    var colsN = typeof opts.colsFn === "function"
      ? opts.colsFn(w)
      : (w < 340 ? 1 : (w < 560 ? 2 : 3));
    var wrap = host.querySelector("." + colsClass);
    var existingCols = wrap ? wrap.querySelectorAll("." + colClass) : [];
    var attr = opts.attr || "";
    var sameCols = !!(wrap && existingCols.length === colsN &&
      (!attr || String(panel.getAttribute(attr) || "") === String(colsN)));
    var orphan = false;
    if (sameCols && !opts.force) {
      orphan = boxes.some(function (b) {
        return !(b.parentNode && b.parentNode.classList && b.parentNode.classList.contains(colClass));
      });
      if (!orphan) {
        if (attr) panel.setAttribute(attr, String(colsN));
        return;
      }
    }
    if (attr) panel.setAttribute(attr, String(colsN));
    if (!wrap) {
      wrap = document.createElement("div");
      wrap.className = colsClass;
    }
    /* Pull boxes out of old columns before rebuilding. */
    boxes.forEach(function (box) { host.appendChild(box); });
    while (wrap.firstChild) wrap.removeChild(wrap.firstChild);
    if (!wrap.parentNode) host.insertBefore(wrap, host.firstChild);
    else host.insertBefore(wrap, host.firstChild);
