    /* Simple mode soft-hides advanced Explore extras without changing ticks. */
    if (uxFeelOn("simpleMode") && UX_SIMPLE_SOFT_OFF.indexOf(id) >= 0) return false;
    if (uxFeelActiveRole() === "listen" && UX_SIMPLE_SOFT_OFF.indexOf(id) >= 0) return false;
    return true;
