  function normalizeBoxHelpKey(s) {
    return String(s || "")
      .replace(/&amp;/gi, "&")
      .replace(/<[^>]+>/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
  }

  function boxHelpTitleOf(box) {
    if (!box) return "Section";
    var t = box.querySelector(".bs-set-box-title, .bs-extra-box-tab, .bs-ex-box-title, .bs-ex-box-h");
    if (t) {
      var clone = t.cloneNode(true);
      Array.prototype.forEach.call(clone.querySelectorAll(
        ".bs-ex-box-sub, .bs-set-box-count, .bs-box-help, .bs-ex-box-chev, .bs-set-box-chev"
      ), function (n) {
        if (n.parentNode) n.parentNode.removeChild(n);
      });
      var txt = String(clone.textContent || "").replace(/\s+/g, " ").trim();
      if (txt) return txt;
    }
    if (box.matches && box.matches("details.bs-tab-opts")) {
      var sum = box.querySelector("summary");
      if (sum) {
        var s = String(sum.textContent || "").replace(/\?/g, "").replace(/\s+/g, " ").trim();
        if (s) return s;
      }
    }
    return "Section";
  }

  function collectBoxHelpItems(box) {
    var items = [];
    var seen = {};
    if (!box) return items;
    var nodes = box.querySelectorAll("label, button, summary, th, [data-tip], [title]");
    Array.prototype.forEach.call(nodes, function (el) {
      if (!el || el.classList.contains("bs-box-help") ||
          el.classList.contains("bs-set-box-toggle") ||
          el.classList.contains("bs-ex-box-toggle")) return;
      if (el.closest && el.closest(".bs-box-help-pop, #bs-box-help-pop, #bs-shade-menu, #bs-tab-menu, #bs-float-tip, #bs-bm-edit-pop, #bs-bd-edit-pop")) return;
      var tip = tipTextOf(el);
      if (!tip || tip.length < 12) return;
      if (/^about this section/i.test(tip) || /^show or hide/i.test(tip)) return;
      var label = "";
      if (el.tagName === "LABEL") {
        var lab = el.cloneNode(true);
        Array.prototype.forEach.call(lab.querySelectorAll("input, select, textarea, button"), function (n) {
          if (n.parentNode) n.parentNode.removeChild(n);
        });
        label = String(lab.textContent || "").replace(/\s+/g, " ").trim();
      } else if (el.tagName === "BUTTON") {
        label = String(el.textContent || "").replace(/\s+/g, " ").trim();
      } else if (el.tagName === "TH") {
        label = String(el.textContent || "").replace(/\s+/g, " ").trim();
      }
      if (!label || label === "?" || label.length > 48) {
        label = tip.slice(0, 36).replace(/\s+\S*$/, "") + (tip.length > 36 ? "…" : "");
      }
      var key = label.toLowerCase() + "|" + tip;
      if (seen[key]) return;
      seen[key] = true;
      items.push({ label: label, tip: tip });
    });
    return items.slice(0, 24);
  }

  function ensureBoxHelpPopup() {
    var pop = $("bs-box-help-pop");
    if (pop) return pop;
    pop = document.createElement("div");
    pop.id = "bs-box-help-pop";
    pop.hidden = true;
    pop.setAttribute("role", "dialog");
    pop.setAttribute("aria-modal", "false");
    pop.innerHTML =
      '<div class="bs-box-help-pop-h">' +
      '<span class="bs-box-help-pop-title"></span>' +
      '<button type="button" class="bs-box-help-close" title="Close" aria-label="Close">×</button>' +
      "</div>" +
      '<p class="bs-box-help-pop-intro"></p>' +
      '<ul class="bs-box-help-pop-list"></ul>';
    document.body.appendChild(pop);
    pop.addEventListener("click", function (ev) {
      ev.stopPropagation();
      if (ev.target && ev.target.closest && ev.target.closest(".bs-box-help-close")) {
        closeBoxHelpPopup();
      }
    });
    if (!ensureBoxHelpPopup._doc) {
      ensureBoxHelpPopup._doc = true;
      document.addEventListener("click", function (ev) {
        var popEl = $("bs-box-help-pop");
        if (!popEl || popEl.hidden) return;
        if (ev.target && ev.target.closest &&
            (ev.target.closest("#bs-box-help-pop") || ev.target.closest(".bs-box-help"))) return;
        closeBoxHelpPopup();
      });
      document.addEventListener("keydown", function (ev) {
        if (ev.key === "Escape") closeBoxHelpPopup();
      });
    }
    return pop;
  }

  function closeBoxHelpPopup() {
    var pop = $("bs-box-help-pop");
    if (!pop) return;
    pop.hidden = true;
    pop.classList.remove("bs-box-help-pop-on");
  }

  function openBoxHelpPopup(anchor, box) {
    if (!box) return;
    hideFloatTip();
    try { closeBtnShadeMenu(); } catch (eSh) {}
    try { stripNativeTitles(box); } catch (eSt) {}
    var pop = ensureBoxHelpPopup();
    var title = boxHelpTitleOf(box);
    var intro = box.getAttribute("data-box-help") ||
      BOX_HELP_INTRO[normalizeBoxHelpKey(title)] ||
      ("Controls in “" + title + "”. Hover any control for a short tip; this list gathers those tips in one place.");
    var items = collectBoxHelpItems(box);
    pop.querySelector(".bs-box-help-pop-title").textContent = title;
    var introEl = pop.querySelector(".bs-box-help-pop-intro");
    introEl.textContent = intro;
    introEl.hidden = !intro;
    var list = pop.querySelector(".bs-box-help-pop-list");
    if (!items.length) {
      list.innerHTML = '<li class="bs-box-help-empty">No extra control tips in this box yet — use Help tab for the full guide.</li>';
    } else {
      list.innerHTML = items.map(function (it) {
        return "<li><strong>" + escapeHtml(it.label) + "</strong> — " + escapeHtml(it.tip) + "</li>";
      }).join("");
    }
    pop.hidden = false;
    pop.classList.add("bs-box-help-pop-on");
    pop.setAttribute("data-for", String(box.id || title));
    pop.style.left = "0px";
    pop.style.top = "0px";
    var r = (anchor || box).getBoundingClientRect();
    var w = pop.offsetWidth || 320;
    var h = pop.offsetHeight || 220;
    var left = Math.min(Math.max(8, r.left), window.innerWidth - w - 8);
    var top = r.bottom + 6;
    if (top + h > window.innerHeight - 8) top = Math.max(8, r.top - h - 6);
    pop.style.left = left + "px";
    pop.style.top = top + "px";
  }

  function injectBoxHelpButtons(root) {
    root = root || $("bs-panel");
    if (!root) return;
    var headers = root.querySelectorAll(
      ".bs-set-box > .bs-set-box-h, .bs-extra-box > .bs-set-box-h, .bs-ex-box > .bs-ex-box-h, details.bs-tab-opts > summary"
    );
    Array.prototype.forEach.call(headers, function (h) {
      if (h.querySelector(".bs-box-help")) return;
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "bs-box-help";
      btn.setAttribute("aria-label", "About this section");
      btn.setAttribute("data-tip", "About this section — click for a short guide.");
      btn.textContent = "?";
      h.appendChild(btn);
    });
  }

  function bindBoxHelp(root) {
    root = root || $("bs-panel");
    if (!root) return;
    injectBoxHelpButtons(root);
    if (root._bs_box_help_bound) return;
    root._bs_box_help_bound = true;
    root.addEventListener("click", function (ev) {
      var btn = ev.target && ev.target.closest && ev.target.closest(".bs-box-help");
      if (!btn || !root.contains(btn)) return;
      ev.preventDefault();
      ev.stopPropagation();
      if (typeof ev.stopImmediatePropagation === "function") ev.stopImmediatePropagation();
      var box = btn.closest(".bs-set-box, .bs-ex-box, details.bs-tab-opts");
      if (!box) return;
      var pop = $("bs-box-help-pop");
      if (pop && !pop.hidden && pop.getAttribute("data-for") === String(box.id || boxHelpTitleOf(box))) {
        closeBoxHelpPopup();
        return;
      }
      openBoxHelpPopup(btn, box);
    }, true);
  }

  function extrasPrimaryTab(where) {
    var w = String(where || "Other");
    var primary = w.split(/\s*\/\s*/)[0].trim();
    return primary || "Other";
  }

  function extrasTabOrder() {
    return ["Explore", "Bands", "Range", "Peaks", "Bookmarks", "Audio", "Settings", "Global", "Other"];
  }

  function extrasSettingsHtml() {
    var extrasBody =
      '<div class="bs-row">' +
      '<button type="button" class="bs-tiny bs-primary" id="bs-extras-all" title="Turn on every extra except Public / shared receiver mode (that extra greys out Factory reset).">Add all extras</button>' +
      '<button type="button" class="bs-tiny bs-btn-clear" id="bs-extras-none" title="Turn every extra off.">Clear extras</button>' +
      "</div>" +
      '<div class="bs-extras-grid" id="bs-extras">' + extrasGridInnerHtml(!!(S.uxFeel && S.uxFeel.extrasByJob)) + "</div>" +
      '<div class="bs-row" data-extra="publicMode">' +
      '<span class="bs-hint">Public mode: alone-only on, Own radio off, Factory reset hidden.</span>' +
      "</div>";
    return '<div id="bs-extras-wrap" class="bs-min-hide">' +
      settingsBoxHtml("Extras", extrasBody, {
        id: "bs-extras-section",
        wide: true,
        sub: "Optional add-ons. Grouped by tab normally — or by job when UX feel → Extras by job is on.",
        count: EXTRAS_DEFS.length
      }) +
      "</div>";
  }

  function extrasItemHtml(e) {
    var multi = String(e.where).indexOf("/") >= 0;
    return '<label class="bs-extra-item" title="' + escapeHtml(e.tip) + '">' +
      '<input type="checkbox" class="bs-extra-tog" id="bs-extra-' + e.id + '" data-extra-id="' + e.id + '">' +
      '<span class="bs-extra-item-body">' +
      '<span class="bs-extra-item-label">' + escapeHtml(e.label) + "</span>" +
      (multi ? '<span class="bs-extra-item-also">also ' + escapeHtml(String(e.where).replace(/^[^/]+\s*\/\s*/, "")) + "</span>" : "") +
      '<span class="bs-extra-item-tip">' + escapeHtml(e.tip) + "</span>" +
      "</span></label>";
  }

  function extrasGridInnerHtml(byJob) {
    if (byJob) {
      var used = {};
      var boxes = EXTRAS_JOB_GROUPS.map(function (g) {
        var items = [];
        g.ids.forEach(function (id) {
          var e = null;
          EXTRAS_DEFS.forEach(function (def) { if (def.id === id) e = def; });
          if (!e) return;
          used[id] = true;
          items.push(extrasItemHtml(e));
        });
        if (!items.length) return "";
        return '<section class="bs-set-box bs-extra-box" data-extra-tab="' + escapeHtml(g.label) + '" data-extra-job="' + escapeHtml(g.id) + '">' +
          '<header class="bs-set-box-h bs-extra-box-h">' +
          '<span class="bs-set-box-title bs-extra-box-tab">' + escapeHtml(g.label) + "</span>" +
          '<span class="bs-set-box-count bs-extra-box-count">' + items.length + "</span>" +
          boxHelpBtnHtml() +
          "</header>" +
          '<div class="bs-set-box-body bs-extra-box-body">' + items.join("") + "</div>" +
          "</section>";
      }).filter(Boolean);
      var other = EXTRAS_DEFS.filter(function (e) { return !used[e.id]; }).map(extrasItemHtml);
      if (other.length) {
        boxes.push(
          '<section class="bs-set-box bs-extra-box" data-extra-tab="Other" data-extra-job="other">' +
          '<header class="bs-set-box-h bs-extra-box-h">' +
          '<span class="bs-set-box-title bs-extra-box-tab">Other</span>' +
          '<span class="bs-set-box-count bs-extra-box-count">' + other.length + "</span>" +
          boxHelpBtnHtml() +
          "</header>" +
          '<div class="bs-set-box-body bs-extra-box-body">' + other.join("") + "</div>" +
          "</section>"
        );
      }
      return boxes.join("");
    }
    var order = extrasTabOrder();
    var groups = {};
    order.forEach(function (t) { groups[t] = []; });
    EXTRAS_DEFS.forEach(function (e) {
      var tab = extrasPrimaryTab(e.where);
      if (!groups[tab]) groups[tab] = [];
      groups[tab].push(e);
    });
    return order.filter(function (t) { return groups[t] && groups[t].length; }).map(function (tab) {
      var items = groups[tab].map(extrasItemHtml).join("");
      return '<section class="bs-set-box bs-extra-box" data-extra-tab="' + escapeHtml(tab) + '">' +
        '<header class="bs-set-box-h bs-extra-box-h">' +
        '<span class="bs-set-box-title bs-extra-box-tab">' + escapeHtml(tab) + "</span>" +
        '<span class="bs-set-box-count bs-extra-box-count">' + groups[tab].length + "</span>" +
        boxHelpBtnHtml() +
        "</header>" +
        '<div class="bs-set-box-body bs-extra-box-body">' + items + "</div>" +
        "</section>";
    }).join("");
  }

  function applyExtrasUi() {
    Array.prototype.forEach.call(panelQsa("#bs-panel [data-extra]"), function (el) {
      var id = el.getAttribute("data-extra");
      if (!id) return;
      /* Never hide public-allowlist ticks — those use data-pub-extra. */
      if (el.classList && el.classList.contains("bs-pub-extra")) return;
      var on = extraOn(id);
      /* Range extras: gone when off (Settings → Extras). Explore/Settings keep greyed boxes. */
      var hideWhenOff = id.indexOf("range") === 0 ||
        (el.classList && el.classList.contains("bs-range-extra-row")) ||
        !!(el.closest && el.closest("#bs-tab-range") && id.indexOf("range") === 0);
      if (hideWhenOff) {
        el.hidden = !on;
        el.classList.remove("bs-extra-off");
        if (!on) el.setAttribute("aria-disabled", "true");
        else el.removeAttribute("aria-disabled");
        return;
      }
      /* Grey out when off — keep layout so Settings / Explore do not jump. */
      el.hidden = false;
      el.classList.toggle("bs-extra-off", !on);
      if (!on) el.setAttribute("aria-disabled", "true");
      else el.removeAttribute("aria-disabled");
    });
    /* Limits box: hide the whole section when both Repeat and Hop-cap extras are off. */
    try {
      var lim = $("bs-range-limits-box");
      if (lim) {
        var limKids = lim.querySelectorAll("[data-extra]");
        var limAny = false;
        Array.prototype.forEach.call(limKids, function (k) {
          if (!k.hidden) limAny = true;
        });
        lim.hidden = !limAny;
      }
      var extrasRow = $("bs-range-extras-row");
      if (extrasRow) {
        var rowAny = false;
        Array.prototype.forEach.call(extrasRow.children, function (k) {
          if (!k || k.hidden) return;
          if (k.classList && (k.classList.contains("bs-set-box") || k.classList.contains("bs-range-extra-box"))) {
            rowAny = true;
          }
        });
        extrasRow.hidden = !rowAny;
      }
    } catch (eLim) {}
    try { syncBandEditAdvancedUi(); } catch (eAdv) {}
    /* If the active Bands / Bookmarks sub-tab was turned off by an Extra, fall back to list. */
    try {
      var bdOn = document.querySelector("#bs-tab-bands .bs-bd-sub.bs-bd-sub-on");
      if (bdOn && (bdOn.hidden || bdOn.classList.contains("bs-extra-off")) && typeof setBandsSubTab === "function") {
        setBandsSubTab("list", { skipSave: true });
      }
    } catch (eBd) {}
    try {
      var bmOn = document.querySelector("#bs-tab-bookmarks .bs-bm-sub.bs-bm-sub-on");
      if (bmOn && (bmOn.hidden || bmOn.classList.contains("bs-extra-off")) && typeof setBookmarkSubTab === "function") {
        setBookmarkSubTab("list", { skipSave: true });
      }
    } catch (eBm) {}
    applyPublicModeExtra();
    /* Keep Panel startup Auto-click visible and synced — it is not a data-extra target. */
    try {
      if ($("bs-autostart-owrx")) {
        $("bs-autostart-owrx").checked = !!(S.autoStartOwrx || (S.extras && S.extras.autoStartOwrx));
        var lab = $("bs-autostart-owrx").closest && $("bs-autostart-owrx").closest("label");
        if (lab) lab.hidden = false;
        $("bs-autostart-owrx").hidden = false;
      }
      var exAs = $("bs-extra-autoStartOwrx");
      if (exAs) {
        exAs.hidden = false;
        var exLab = exAs.closest && exAs.closest("label");
        if (exLab) exLab.hidden = false;
      }
    } catch (eAs) {}
    if (typeof bindExclusiveTabOpts === "function") bindExclusiveTabOpts();
    if (typeof renderSessionLogPane === "function") renderSessionLogPane();
    if (typeof renderWatchlistPane === "function") renderWatchlistPane();
    if (typeof updateSpectrumHistoryUi === "function") updateSpectrumHistoryUi();
    if (extraOn("occHeatmap")) {
      if (S.peaksView === "heatmap") setPeaksView("heatmap");
      else setPeaksView("list");
    } else if ($("bs-hitwrap")) {
      $("bs-hitwrap").hidden = false;
      if ($("bs-occ-heat")) $("bs-occ-heat").hidden = true;
    }
    try {
      if (typeof packExploreMasonry === "function") packExploreMasonry();
      if (typeof fitExplorePack === "function") fitExplorePack();
      /* Do not packSettingsMasonry / packExtrasMasonry here — ticking extras must not reshuffle Settings. */
    } catch (eEx) {}
  }

  function applyPublicModeExtra() {
    var on = extraOn("publicMode") || !ownerOverrideAllowed();
    if (on) {
      S.aloneOnly = true;
      S.ownRadio = false;
      syncAloneUi(true);
      syncOwnRadioUi(false);
      applyOwnerLock();
      enforcePublicExtrasState();
    }
    var clientsOk = true;
    try { clientsOk = !!(caps() && caps().clients); } catch (e) { clientsOk = true; }
    ["bs-band-alone", "bs-range-alone"].forEach(function (id) {
      var el = $(id);
      if (!el) return;
      var lab = el.parentElement;
      if (on) {
        el.disabled = true;
        el.checked = true;
        if (lab) {
          if (!lab.getAttribute("data-tip-alone") && lab.getAttribute("title")) {
            lab.setAttribute("data-tip-alone", lab.getAttribute("title"));
          }
          lab.title = !ownerOverrideAllowed()
            ? "Locked on for this public (--public) install."
            : "Locked on while Public / shared receiver mode extra is enabled (Settings → Extras).";
          if (lab.classList) lab.classList.add("bs-off");
        }
      } else {
        if (lab && lab.getAttribute("data-tip-alone")) {
          lab.title = lab.getAttribute("data-tip-alone");
          lab.removeAttribute("data-tip-alone");
        }
        if (clientsOk) {
          el.disabled = false;
          if (lab && lab.classList) lab.classList.remove("bs-off");
        }
      }
    });
    var frs = [$("bs-factory-reset"), $("bs-factory-reset-2")];
    frs.forEach(function (fr) {
      if (!fr) return;
      fr.hidden = false;
      fr.disabled = on || !publicAllowsFeature("factoryReset");
    });
    var pubNote = $("bs-factory-public");
    if (pubNote) {
      pubNote.hidden = !on;
      pubNote.textContent = !ownerOverrideAllowed()
        ? "This install is public (./install.sh --public) — Factory reset and Own radio stay locked. Visitor allowlist is below."
        : "Public / shared receiver extra is on — Factory reset is disabled. Choose visitor options under Public visitor allowlist.";
    }
    applyPublicPolicyUi();
  }

  function setControlPublicGate(el, allowed, whyDenied) {
    if (!el) return;
    var deny = isPublicReceiver() && !allowed;
    if (deny) {
      el.disabled = true;
      if (el.title && !el.getAttribute("data-tip-pub")) {
        el.setAttribute("data-tip-pub", el.title);
      }
      el.title = whyDenied || "Not allowed for visitors on this public receiver (Settings → Public visitor allowlist).";
      if (el.classList) el.classList.add("bs-off");
    } else {
      if (el.getAttribute("data-tip-pub")) {
        el.title = el.getAttribute("data-tip-pub");
        el.removeAttribute("data-tip-pub");
      }
      if (el.classList) el.classList.remove("bs-off");
      /* Leave disabled state to applyCaps / other locks when not public-gated. */
      if (!isPublicReceiver() && el.getAttribute("data-pub-was") === "1") {
        el.removeAttribute("data-pub-was");
      }
    }
    if (deny) el.setAttribute("data-pub-was", "1");
  }

  function applyPublicPolicyUi() {
    var wrap = $("bs-public-policy");
    var canEdit = canEditPublicPolicy();
    if (wrap) {
      /* Guests cannot edit — hide the whole allowlist so they cannot poke at it. */
      wrap.hidden = !canEdit;
      wrap.classList.toggle("bs-public-policy-locked", !canEdit);
    }
    var note = $("bs-public-policy-note");
    if (note) {
      if (!isOwrxAdmin()) {
        note.textContent = "Log in to OpenWebRX Settings (admin) to edit the visitor allowlist. Public on/off is in Settings → General.";
      } else if (!ownerOverrideAllowed()) {
        note.textContent = "This install is baked --public. Prefer stock Settings → General for on/off; allowlist may still be baked via TOOLBOX_PUBLIC_POLICY.";
      } else if (serverPublicMode === true) {
        note.textContent = "Public mode is ON in OpenWebRX Settings → General (applies to all visitors). Edit the allowlist below.";
      } else if (serverPublicMode === false) {
        note.textContent = "Public mode is OFF in OpenWebRX Settings → General. Allowlist is unused until you enable it there.";
      } else if (extraOn("publicMode")) {
        note.textContent = "Waiting for server setting… Local public tick is a temporary fallback. Use Settings → General → Toolbox public mode for all visitors.";
      } else {
        note.textContent = "Switch public mode in OpenWebRX Settings → General (admin password). This allowlist applies when that switch is on.";
      }
    }
    fillPublicPolicyForm();
    gatePublicActions();
    fillExtrasForm();
    applyHiddenTabs();
    try { updatePublicExploreLimitHint(); } catch (eLim) {}
  }

  function gatePublicActions() {
    var pub = isPublicReceiver();
    function clearPubGate(el) {
      if (!el || el.getAttribute("data-pub-was") !== "1") return;
      el.removeAttribute("data-pub-was");
      if (el.getAttribute("data-tip-pub")) {
        el.title = el.getAttribute("data-tip-pub");
        el.removeAttribute("data-tip-pub");
      }
      if (el.classList) el.classList.remove("bs-off");
    }
    function gate(id, feat, label) {
      var el = $(id);
      if (!el) return;
      if (!pub) {
        clearPubGate(el);
        return;
      }
      setControlPublicGate(el, publicAllowsFeature(feat),
        (label || feat) + " is not allowed for visitors (Settings → Public visitor allowlist).");
    }
    gate("bs-start", "scanBands", "Scan bands");
    gate("bs-fresh", "scanBands", "Fresh scan");
    gate("bs-range-start-btn", "scanRange", "Range scan");
    gate("bs-range-fresh", "scanRange", "Range fresh");
    gate("bs-listen-top", "scanBookmarks", "Scan bookmarks");
    gate("bs-record", "record", "Record busy");
    gate("bs-record-list", "record", "Record busy");
    gate("bs-aud-rec-now", "record", "Record now");
    gate("bs-aud-rec-stop", "record", "Stop record");
    gate("bs-dec-rec", "record", "Record now");
    gate("bs-ex-rec", "record", "Explore REC");
    gate("bs-peaks-jump", "exploreTune", "Jump loud");
    gate("bs-skip-add-tune", "clearData", "Always skip current");
    gate("bs-skip-lock-tune", "clearData", "Lockout current");
    gate("bs-clear-lockouts", "clearData", "Clear lockouts");
    gate("bs-ex-toggle", "exploreTune", "Explore hop");
    gate("bs-ex-go", "exploreTune", "Explore Go");
    gate("bs-ex-prev", "exploreTune", "Explore profile");
    gate("bs-ex-next", "exploreTune", "Explore profile");
    gate("bs-clearhits", "clearData", "Clear peaks");
    gate("bs-bm-clearlocal", "clearData", "Clear blue bookmarks");
    gate("bs-bm-clearauto", "clearData", "Clear auto bookmarks");
    gate("bs-bm-clearall", "clearData", "Clear all bookmarks");
    gate("bs-bm-clearload", "clearData", "Clear load bookmarks");
    gate("bs-bm-save", "importExport", "Save bookmarks");
    gate("bs-bm-load", "importExport", "Load saved bookmarks");
    gate("bs-bm-loaduser", "importExport", "Load user bookmarks");
    gate("bs-bm-edit-del", "clearData", "Delete bookmark");
    gate("bs-bd-edit-delete", "clearData", "Delete SDR profile");
    gate("bs-clearskip-tab", "clearData", "Clear always-skip");
    gate("bs-export-csv", "importExport", "Export");
    gate("bs-export-json", "importExport", "Export");
    gate("bs-import-csv", "importExport", "Import");
    gate("bs-import-json", "importExport", "Import");
    gate("bs-export-settings", "importExport", "Export settings");
    gate("bs-import-settings", "importExport", "Import settings");
    gate("bs-save-user-defaults", "importExport", "Save as my defaults");
    gate("bs-clear-user-defaults", "importExport", "Clear my defaults");
    gate("bs-bm-file", "importExport", "Load bookmarks file");
    gate("bs-save-layout", "changeLayout", "Save layout");
    gate("bs-reset-layout", "changeLayout", "Restore layout");
    gate("bs-default-layout", "changeLayout", "Waterfall default");
    gate("bs-reset-ex-layout", "changeLayout", "Reset Explore layout");
    gate("bs-side-dock-set", "changeLayout", "Side dock");
    gate("bs-side-pct", "changeLayout", "Side size");
    gate("bs-side-pct-range", "changeLayout", "Side size");
    gate("bs-hide-stock-rx", "changeLayout", "Hide stock receiver");
    gate("bs-side-dock", "changeLayout", "Side dock");
    gate("bs-side-pct-reset", "changeLayout", "Side size reset");

    /* Extras toggles */
    var canChange = !pub || publicAllowsFeature("changeExtras");
    EXTRAS_DEFS.forEach(function (e) {
      var el = $("bs-extra-" + e.id);
      if (!el) return;
      if (e.id === "publicMode") {
        var serverOwns = serverPublicMode != null;
        el.disabled = !canEditPublicPolicy() || serverOwns;
        if (serverOwns) {
          el.checked = !!serverPublicMode;
          el.title = "Controlled in OpenWebRX Settings → General → Toolbox: public / shared receiver mode (admin).";
        }
        var row = el.closest && el.closest("[data-extra='publicMode']");
        if (row) {
          /* Keep visible for admins so they see the pointer to stock Settings; hide from guests. */
          row.hidden = !canEditPublicPolicy();
        }
        return;
      }
      var allowed = publicAllowsExtra(e.id);
      if (pub) {
        el.disabled = !canChange || !allowed;
        if (!allowed) el.checked = false;
      } else {
        el.disabled = false;
      }
    });
    var extrasAll = $("bs-extras-all");
    var extrasNone = $("bs-extras-none");
    if (extrasAll) extrasAll.disabled = pub && !canChange;
    if (extrasNone) extrasNone.disabled = pub && !canChange;
    if (!pub && !gatePublicActions._restoring) {
      gatePublicActions._restoring = true;
      applyCaps._skipGate = true;
      try { applyCaps(); } catch (eCaps) {}
      applyCaps._skipGate = false;
      gatePublicActions._restoring = false;
    }
  }

  function publicPolicyMiniBox(title, bodyHtml, count) {
    return '<section class="bs-set-box bs-pub-mini">' +
      '<header class="bs-set-box-h">' +
      '<span class="bs-set-box-title">' + title + "</span>" +
      (count != null ? '<span class="bs-set-box-count">' + count + "</span>" : "") +
      boxHelpBtnHtml() +
      "</header>" +
      '<div class="bs-set-box-body">' + bodyHtml + "</div>" +
      "</section>";
  }

  function publicPolicySettingsHtml() {
    var tabLabs = {
      bands: "Bands", range: "Range", explore: "Explore", analyzer: "Analyzer",
      peaks: "Peaks", bookmarks: "Bookmarks", audio: "Audio", skip: "Skip",
      settings: "Settings", help: "Help"
    };
    var tabsHtml = TAB_IDS.map(function (id) {
      var locked = (id === "settings" || id === "help");
      var tip = locked
        ? "Always available."
        : ("Allow visitors to open the " + (tabLabs[id] || id) + " tab.");
      return '<label class="bs-chk" title="' + escapeHtml(tip) + '">' +
        '<input type="checkbox" class="bs-pub-tab" data-tab="' + id + '"' +
        (locked ? " checked disabled" : "") + "> " + (tabLabs[id] || id) + "</label>";
    }).join("");

    var featGroups = [
      { title: "Scans", ids: ["scanBands", "scanRange", "scanBookmarks"] },
      { title: "Listen &amp; tune", ids: ["record", "exploreTune"] },
      { title: "Clear &amp; files", ids: ["clearData", "importExport"] },
      { title: "Panel", ids: ["changeExtras", "changeLayout"] }
    ];
    var featById = {};
    PUBLIC_FEATURE_DEFS.forEach(function (f) { featById[f.id] = f; });
    var featBoxes = featGroups.map(function (g) {
      var items = g.ids.map(function (id) {
        var f = featById[id];
        if (!f) return "";
        return '<label class="bs-chk" title="' + escapeHtml(f.tip) + '">' +
          '<input type="checkbox" class="bs-pub-feat" data-feat="' + f.id + '"> ' +
          escapeHtml(f.label) + "</label>";
      }).join("");
      return publicPolicyMiniBox(g.title, '<div class="bs-row bs-chk-grid">' + items + "</div>", g.ids.length);
    }).join("");

    var order = extrasTabOrder();
    var groups = {};
    order.forEach(function (t) { groups[t] = []; });
    EXTRAS_DEFS.filter(function (e) { return e.id !== "publicMode"; }).forEach(function (e) {
      var tab = extrasPrimaryTab(e.where);
      if (!groups[tab]) groups[tab] = [];
      groups[tab].push(e);
    });
    var extrasBoxes = order.filter(function (t) { return groups[t] && groups[t].length; }).map(function (tab) {
      var items = groups[tab].map(function (e) {
        return '<label class="bs-chk" title="' + escapeHtml(e.tip) + '">' +
          '<input type="checkbox" class="bs-pub-extra" data-pub-extra="' + e.id + '"> ' +
          escapeHtml(e.label) + "</label>";
      }).join("");
      return publicPolicyMiniBox("Extras · " + tab,
        '<div class="bs-row bs-chk-grid">' + items + "</div>", groups[tab].length);
    }).join("");

    return settingsBoxHtml("Public visitor allowlist",
      '<p class="bs-hint" id="bs-public-policy-note">Used when Public / shared mode is on, or on ./install.sh --public installs.</p>' +
      '<div class="bs-row">' +
      '<button type="button" class="bs-tiny bs-btn-util" id="bs-pub-allow-all" title="Allow every tab, feature, and extra (still no Own radio / Factory reset while public).">Allow all</button>' +
      '<button type="button" class="bs-tiny bs-btn-util" id="bs-pub-allow-safe" title="Safe defaults: common tabs, scans on, clear/import/extras off.">Safe defaults</button>' +
      '<button type="button" class="bs-tiny bs-btn-export" id="bs-pub-copy-policy" title="Copy a TOOLBOX_PUBLIC_POLICY snippet to paste into toolbox.js on the radio host (for all visitors).">Copy policy for install</button>' +
      "</div>" +
      '<div class="bs-pub-policy-grid" id="bs-pub-policy-grid">' +
      publicPolicyMiniBox("Tabs", '<div class="bs-row bs-chk-grid" id="bs-pub-tabs">' + tabsHtml + "</div>", TAB_IDS.length) +
      publicPolicyMiniBox("Explore MHz limit",
        '<p class="bs-hint">When public, guests may only Explore inside this window (Go, wheel, drag, profile hop). Leave blank for no limit.</p>' +
        '<div class="bs-row">' +
        '<label title="Lowest MHz visitors may Explore to. Blank = no lower limit.">Min MHz <input type="number" id="bs-pub-explore-min" min="0.01" max="6000" step="0.001" style="width:6.5em" placeholder="e.g. 1"></label>' +
        '<label title="Highest MHz visitors may Explore to. Blank = no upper limit.">Max MHz <input type="number" id="bs-pub-explore-max" min="0.01" max="6000" step="0.001" style="width:6.5em" placeholder="e.g. 30"></label>' +
        "</div>",
        2) +
      publicPolicyMiniBox("Explore bands",
        '<p class="bs-hint">When public, guests may only hop these SDR profiles. Tick <b>All bands</b> (or leave none) for no band restriction.</p>' +
        '<div class="bs-row">' +
        '<label class="bs-chk" title="Allow every SDR profile for Explore."><input type="checkbox" id="bs-pub-explore-allbands"> All bands</label>' +
        '<button type="button" class="bs-tiny bs-btn-preset" id="bs-pub-explore-bands-ticked" title="Copy the bands currently ticked on the Bands tab.">From Bands ticks</button>' +
        '<button type="button" class="bs-tiny bs-btn-preset" id="bs-pub-explore-bands-current" title="Allow only the current OpenWebRX profile.">Current</button>' +
        "</div>" +
        '<div class="bs-chk-grid bs-pub-explore-bands" id="bs-pub-explore-bands"></div>',
        0) +
      featBoxes +
      extrasBoxes +
      "</div>",
      { id: "bs-public-policy", wide: true, cls: "bs-min-hide",
        sub: "Little boxes for tabs, features, Explore limits/bands, and which extras guests may use — they snap together below." });
  }

  function fillPublicPolicyForm() {
    var pol = effectivePublicPolicy();
    var canEdit = canEditPublicPolicy();
    Array.prototype.forEach.call(document.querySelectorAll("#bs-public-policy .bs-pub-tab"), function (inp) {
      var id = inp.getAttribute("data-tab");
      if (id === "settings" || id === "help") {
        inp.checked = true;
        inp.disabled = true;
        return;
      }
      inp.checked = (pol.tabs || []).indexOf(id) >= 0;
      inp.disabled = !canEdit;
    });
    Array.prototype.forEach.call(document.querySelectorAll("#bs-public-policy .bs-pub-feat"), function (inp) {
      var id = inp.getAttribute("data-feat");
      inp.checked = !!(pol.features && pol.features[id]);
      inp.disabled = !canEdit;
    });
    Array.prototype.forEach.call(document.querySelectorAll("#bs-public-policy .bs-pub-extra"), function (inp) {
      var id = inp.getAttribute("data-pub-extra") || inp.getAttribute("data-extra");
      inp.checked = (pol.extras || []).indexOf(id) >= 0;
      inp.disabled = !canEdit;
    });
    var minEl = $("bs-pub-explore-min");
    var maxEl = $("bs-pub-explore-max");
    if (minEl) {
      minEl.value = pol.exploreMinMhz != null ? String(pol.exploreMinMhz) : "";
      minEl.disabled = !canEdit;
    }
    if (maxEl) {
      maxEl.value = pol.exploreMaxMhz != null ? String(pol.exploreMaxMhz) : "";
      maxEl.disabled = !canEdit;
    }
    fillPublicExploreBandsForm(pol, canEdit);
    ["bs-pub-allow-all", "bs-pub-allow-safe", "bs-pub-explore-bands-ticked", "bs-pub-explore-bands-current"].forEach(function (id) {
      if ($(id)) $(id).disabled = !canEdit;
    });
    updatePublicExploreLimitHint();
  }

  function publicExploreBandsSelectedFromForm() {
    var allCb = $("bs-pub-explore-allbands");
    if (allCb && allCb.checked) return [];
    var out = [];
    Array.prototype.forEach.call(document.querySelectorAll("#bs-pub-explore-bands input.bs-pub-explore-band"), function (inp) {
      if (inp.checked && inp.value) out.push(inp.value);
    });
    return out;
  }

  function fillPublicExploreBandsForm(pol, canEdit) {
    var box = $("bs-pub-explore-bands");
    if (!box) return;
    pol = pol || effectivePublicPolicy();
    if (canEdit == null) canEdit = canEditPublicPolicy();
    var prev = Array.isArray(pol.exploreBands) ? pol.exploreBands.slice() : [];
    var useAll = !prev.length;
    var allCb = $("bs-pub-explore-allbands");
    if (allCb) {
      allCb.checked = useAll;
      allCb.disabled = !canEdit;
    }
    var list = typeof profiles === "function" ? profiles() : [];
    if (!list.length) {
      box.innerHTML = '<p class="bs-empty">No profiles yet — wait for the radio to connect.</p>';
      return;
    }
    var set = {};
    prev.forEach(function (v) { set[String(v)] = true; });
    box.innerHTML = "";
    list.forEach(function (p) {
      var lab = document.createElement("label");
      lab.className = "bs-chk";
      lab.title = "Allow guests to Explore this SDR profile when public.";
      var cb = document.createElement("input");
      cb.type = "checkbox";
      cb.className = "bs-pub-explore-band";
      cb.value = p.value;
      cb.checked = !useAll && !!set[p.value];
      cb.disabled = !canEdit || useAll;
      var id = document.createElement("span");
      id.className = "bs-id";
      id.textContent = p.id || "";
      var name = document.createElement("span");
      name.textContent = p.label || p.value;
      lab.appendChild(cb);
      if (p.id) lab.appendChild(id);
      lab.appendChild(name);
      box.appendChild(lab);
    });
  }

  function applyPublicExploreBandsPreset(kind) {
    if (!canEditPublicPolicy()) return;
    var chosen = [];
    if (kind === "current") {
      var cur = typeof currentProfileValue === "function" ? currentProfileValue() : "";
      if (!cur) {
        var sel = $("openwebrx-sdr-profiles-listbox");
        cur = sel && sel.value ? sel.value : "";
      }
      if (cur) chosen = [cur];
    } else if (kind === "ticked") {
      chosen = typeof selectedValues === "function" ? selectedValues() : [];
      if (!chosen.length && S.selected && S.selected.length) chosen = S.selected.slice();
    }
    var pol = effectivePublicPolicy();
    S.publicPolicy = sanitizePublicPolicy({
      tabs: pol.tabs,
      features: pol.features,
      extras: pol.extras,
      exploreMinMhz: pol.exploreMinMhz,
      exploreMaxMhz: pol.exploreMaxMhz,
      exploreBands: chosen
    });
    fillPublicPolicyForm();
    saveSettings();
    applyPublicPolicyUi();
    setStatus(chosen.length
      ? ("Public Explore bands: " + chosen.length + " allowed.")
      : "Public Explore bands: all bands allowed.");
  }

  function updatePublicExploreLimitHint() {
    var lab = publicExploreLimitLabel();
    var tip = $("bs-ex-pub-limit");
    if (tip) {
      if (lab) {
        tip.hidden = false;
        tip.textContent = "Public Explore limit: " + lab;
      } else {
        tip.hidden = true;
        tip.textContent = "";
      }
    }
  }

  function readPublicPolicyFromForm() {
    if (!canEditPublicPolicy()) return;
    if (!$("bs-public-policy")) return;
    var tabs = [];
    Array.prototype.forEach.call(document.querySelectorAll("#bs-public-policy .bs-pub-tab"), function (inp) {
      var id = inp.getAttribute("data-tab");
      if (inp.checked || id === "settings" || id === "help") tabs.push(id);
    });
    var features = {};
    Array.prototype.forEach.call(document.querySelectorAll("#bs-public-policy .bs-pub-feat"), function (inp) {
      features[inp.getAttribute("data-feat")] = !!inp.checked;
    });
    var extras = [];
    Array.prototype.forEach.call(document.querySelectorAll("#bs-public-policy .bs-pub-extra"), function (inp) {
      if (inp.checked) extras.push(inp.getAttribute("data-pub-extra") || inp.getAttribute("data-extra"));
    });
    var minEl = $("bs-pub-explore-min");
    var maxEl = $("bs-pub-explore-max");
    S.publicPolicy = sanitizePublicPolicy({
      tabs: tabs,
      features: features,
      extras: extras,
      exploreMinMhz: minEl ? minEl.value : null,
      exploreMaxMhz: maxEl ? maxEl.value : null,
      exploreBands: publicExploreBandsSelectedFromForm()
    });
  }

  function setPublicPolicyPreset(kind) {
    if (!canEditPublicPolicy()) return;
    var keepMin = S.publicPolicy && S.publicPolicy.exploreMinMhz;
    var keepMax = S.publicPolicy && S.publicPolicy.exploreMaxMhz;
    var keepBands = S.publicPolicy && Array.isArray(S.publicPolicy.exploreBands)
      ? S.publicPolicy.exploreBands.slice()
      : [];
    if (kind === "all") {
      var all = publicPolicyDefaults();
      all.tabs = TAB_IDS.slice();
      PUBLIC_FEATURE_DEFS.forEach(function (f) { all.features[f.id] = true; });
      all.extras = allExtrasIds(false);
      all.exploreMinMhz = keepMin;
      all.exploreMaxMhz = keepMax;
      all.exploreBands = keepBands;
      S.publicPolicy = sanitizePublicPolicy(all);
    } else {
      var safe = publicPolicyDefaults();
      /* Restrictive: common tabs/features, no visitor extras. */
      safe.extras = [];
      safe.exploreMinMhz = keepMin;
      safe.exploreMaxMhz = keepMax;
      safe.exploreBands = keepBands;
      S.publicPolicy = sanitizePublicPolicy(safe);
    }
    fillPublicPolicyForm();
    saveSettings();
    applyPublicPolicyUi();
    applyExtrasUi();
    setStatus(kind === "all" ? "Public allowlist: everything allowed (except Own radio / Factory reset while public)." : "Public allowlist: safe defaults.");
  }

  function copyPublicPolicySnippet() {
    var pol = effectivePublicPolicy();
    var text = "var TOOLBOX_PUBLIC_POLICY = " + JSON.stringify(pol, null, 2) + ";\n";
    function ok() { setStatus("Public policy snippet copied — paste into toolbox.js on the radio host, then hard-refresh."); }
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(ok).catch(function () {
          window.prompt("Copy this into toolbox.js:", text);
        });
        return;
      }
    } catch (e) {}
    window.prompt("Copy this into toolbox.js:", text);
  }

  var freqNotesMap = {};
  var sessionLog = [];
  var surveySnapPeaks = null;
  var spectrumHist = [];
  var spectrumHistIdx = -1;

  function loadFreqNotes() {
    try {
      var o = JSON.parse(window.localStorage.getItem(LS_FREQ_NOTES) || "{}");
      freqNotesMap = (o && typeof o === "object") ? o : {};
    } catch (e) { freqNotesMap = {}; }
  }
  function saveFreqNotes() {
    try { window.localStorage.setItem(LS_FREQ_NOTES, JSON.stringify(freqNotesMap)); } catch (e) {}
  }
  function noteForFreq(freq) {
    var k = String(Math.round(Number(freq) || 0));
    return freqNotesMap[k] || "";
  }
  function setNoteForFreq(freq, text) {
    var k = String(Math.round(Number(freq) || 0));
    text = String(text || "").trim().slice(0, 120);
    if (!text) delete freqNotesMap[k];
    else freqNotesMap[k] = text;
    saveFreqNotes();
  }

  function loadSessionLog() {
    try {
      var o = JSON.parse(window.localStorage.getItem(LS_SESSION_LOG) || "[]");
      sessionLog = Array.isArray(o) ? o.slice(-200) : [];
    } catch (e) { sessionLog = []; }
  }
  function saveSessionLog() {
    try { window.localStorage.setItem(LS_SESSION_LOG, JSON.stringify(sessionLog.slice(-200))); } catch (e) {}
  }
  function pushSessionLog(row) {
    if (!extraOn("sessionLog")) return;
    sessionLog.push(row);
    if (sessionLog.length > 200) sessionLog = sessionLog.slice(-200);
    saveSessionLog();
    renderSessionLogPane();
  }
  function clearSessionLog() {
    sessionLog = [];
    saveSessionLog();
    renderSessionLogPane();
    setStatus("Session log cleared.");
  }
  function exportSessionLogCsv() {
    if (!sessionLog.length) {
      setStatus("Session log is empty.");
      return;
    }
    var lines = ["when,freq_mhz,name,busy,clip,db"];
    sessionLog.forEach(function (r) {
      lines.push([
        new Date(r.at || 0).toISOString(),
        ((r.freq || 0) / 1e6).toFixed(3),
        JSON.stringify(String(r.name || "")),
        r.busy ? "yes" : "no",
        r.clip ? "yes" : "no",
        r.db != null ? Math.round(r.db) : ""
      ].join(","));
    });
    downloadFile("toolbox-session-log.csv", lines.join("\n"), "text/csv");
    setStatus("Exported " + sessionLog.length + " session log row(s).");
  }
  function renderSessionLogPane() {
    var host = $("bs-session-log");
    if (!host) return;
    if (!extraOn("sessionLog")) {
      host.innerHTML = "";
      return;
    }
    if (!sessionLog.length) {
      host.innerHTML = '<p class="bs-empty">No hops logged yet. Run Scan bookmarks with Session log on.</p>';
      return;
    }
    var rows = sessionLog.slice().reverse().slice(0, 80).map(function (r) {
      return '<div class="bs-skip-row">' +
        '<span class="bs-hint">' + escapeHtml(new Date(r.at || 0).toLocaleTimeString()) + "</span>" +
        '<button type="button" class="bs-tune" data-log-tune="' + (r.freq || 0) + '">' + fmtMhz(r.freq) + "</button>" +
        '<span class="bs-bm-name">' + escapeHtml(r.name || "") + "</span>" +
        '<span class="bs-hint">' + (r.busy ? "busy" : "quiet") + (r.clip ? " · clip" : "") +
        (r.db != null ? " · " + Math.round(r.db) + " dB" : "") + "</span></div>";
    }).join("");
    host.innerHTML = rows;
  }

  function renderWatchlistPane() {
    var ta = $("bs-watchlist-freqs");
    if (ta && extraOn("watchlist") && document.activeElement !== ta) {
      ta.value = S.alertFreqs || "";
    }
  }

  function loadSurveySnap() {
    try {
      var o = JSON.parse(window.localStorage.getItem(LS_SURVEY_SNAP) || "null");
      surveySnapPeaks = (o && Array.isArray(o.freqs)) ? o : null;
    } catch (e) { surveySnapPeaks = null; }
  }
  function saveSurveySnapNow() {
    var freqs = hits.filter(function (h) { return !isSpur(h); }).map(function (h) { return Math.round(h.freq); });
    surveySnapPeaks = { when: Date.now(), freqs: freqs };
    try { window.localStorage.setItem(LS_SURVEY_SNAP, JSON.stringify(surveySnapPeaks)); } catch (e) {}
    setStatus("Survey snapshot saved (" + freqs.length + " peaks). New peaks vs this snap show as changed.");
    renderHits();
  }
  function peakChangedVsSnap(h) {
    if (!surveySnapPeaks || !surveySnapPeaks.freqs || !surveySnapPeaks.freqs.length) return false;
    var f = Math.round(h.freq);
    for (var i = 0; i < surveySnapPeaks.freqs.length; i++) {
      if (Math.abs(surveySnapPeaks.freqs[i] - f) < 2500) return false;
    }
    return true;
  }

  function loadSpectrumHist() {
    try {
      var o = JSON.parse(window.localStorage.getItem(LS_SPEC_HIST) || "[]");
      spectrumHist = Array.isArray(o) ? o.slice(-8) : [];
      spectrumHistIdx = spectrumHist.length ? spectrumHist.length - 1 : -1;
    } catch (e) { spectrumHist = []; spectrumHistIdx = -1; }
  }
  function pushSpectrumHist(entry) {
    if (!extraOn("spectrumHistory") || !entry) return;
    spectrumHist.push(entry);
    if (spectrumHist.length > 8) spectrumHist = spectrumHist.slice(-8);
    spectrumHistIdx = spectrumHist.length - 1;
    try { window.localStorage.setItem(LS_SPEC_HIST, JSON.stringify(spectrumHist)); } catch (e) {}
    updateSpectrumHistoryUi();
  }
  function updateSpectrumHistoryUi() {
    var lab = $("bs-spec-hist-lab");
    if (!lab) return;
    if (!extraOn("spectrumHistory") || !spectrumHist.length) {
      lab.textContent = "";
      return;
    }
    lab.textContent = (spectrumHistIdx + 1) + "/" + spectrumHist.length;
  }
  function showSpectrumHist(delta) {
    if (!spectrumHist.length) return;
    spectrumHistIdx = Math.max(0, Math.min(spectrumHist.length - 1, spectrumHistIdx + delta));
    var e = spectrumHist[spectrumHistIdx];
    if (!e || !e.payload) return;
    try {
      if (typeof applyRangeSpectrumPayload === "function") applyRangeSpectrumPayload(e.payload);
      else if (typeof restoreRangeSpectrum === "function") {
        /* fall through to stored LS restore path by writing then reload */
        window.localStorage.setItem(LS_RANGE_SPECTRUM, JSON.stringify(e.payload));
        if (typeof loadRangeSpectrum === "function") loadRangeSpectrum();
      }
    } catch (err) {}
    updateSpectrumHistoryUi();
    setStatus("Range spectrum history " + (spectrumHistIdx + 1) + "/" + spectrumHist.length);
  }


  function loadOccHeat() {
    try {
      var o = JSON.parse(window.localStorage.getItem(LS_OCC_HEAT) || "[]");
      occHeatLog = Array.isArray(o) ? o.slice(-4000) : [];
    } catch (e) { occHeatLog = []; }
  }
  function saveOccHeat() {
    try { window.localStorage.setItem(LS_OCC_HEAT, JSON.stringify(occHeatLog.slice(-4000))); } catch (e) {}
  }
  function bandKeyFromProfile(pid, label) {
    var s = String(pid || label || "").toLowerCase();
    var m = s.match(/(80m|40m|30m|20m|17m|15m|12m|10m|6m|4m|2m|70c|air|fm|marine|pmr|cb|mw|lf|hf)/);
    if (m) return m[1];
    var dig = s.match(/(ft8|ft4|wspr|jt65|jt9|fst4|q65|msk144)/);
    if (dig) return dig[1];
    var head = (String(pid || "other").split("_")[0] || "other").replace(/[^a-z0-9]/gi, "");
    return (head || "other").slice(0, 10);
  }
  function isDigiProfile(pid, label) {
    var s = String(pid || "") + " " + String(label || "");
    return /(ft8|ft4|wspr|jt65|jt9|fst4|q65|msk144|digi|js8|psk|rtty|olivia)/i.test(s);
  }
  function countDigiSpotsOnPage() {
    var n = 0;
    try {
      var roots = document.querySelectorAll(
        ".openwebrx-digi-message, .openwebrx-message-content, #openwebrx-panel-digi-modes, " +
        ".openwebrx-panel-digimodes, .message-panel, .wsjt-panel, [class*='digi']"
      );
      for (var i = 0; i < roots.length; i++) {
        var t = roots[i].innerText || "";
        var lines = t.split(/\n+/);
        for (var j = 0; j < lines.length; j++) {
          if (/[A-Z0-9]{1,2}[0-9][A-Z0-9]{1,3}/.test(lines[j]) && lines[j].length < 120) n++;
        }
      }
    } catch (e) {}
    return n;
  }
  function recordOccupancy(pid, label, peakN, digiN) {
    if (!extraOn("occHeatmap") && !extraOn("digiSurvey")) return;
    var now = new Date();
    var score = Math.max(0, Number(peakN) || 0) + Math.max(0, Number(digiN) || 0) * 3;
    if (score <= 0 && !(Number(peakN) > 0)) return;
    occHeatLog.push({
      t: now.getTime(),
      day: now.toISOString().slice(0, 10),
      hour: now.getHours(),
      band: bandKeyFromProfile(pid, label),
      peaks: Math.max(0, Number(peakN) || 0),
      digi: Math.max(0, Number(digiN) || 0),
      score: score
    });
    if (occHeatLog.length > 4000) occHeatLog = occHeatLog.slice(-4000);
    saveOccHeat();
  }
  function clearOccHeat() {
    occHeatLog = [];
    saveOccHeat();
    renderOccHeatmap();
    setStatus("Occupancy heatmap cleared.");
  }
  function occHeatMatrix(daysBack) {
    daysBack = Math.max(1, Math.min(30, Number(daysBack) || 7));
    var cut = Date.now() - daysBack * 86400000;
    var bands = {};
    var cells = {};
    occHeatLog.forEach(function (r) {
      if (!r || (r.t && r.t < cut)) return;
      var b = r.band || "other";
      var h = Number(r.hour);
      if (!(h >= 0 && h <= 23)) return;
      bands[b] = true;
      var k = b + "|" + h;
      cells[k] = (cells[k] || 0) + (Number(r.score) || Number(r.peaks) || 0);
    });
    var bandList = Object.keys(bands).sort();
    return { bands: bandList, cells: cells };
  }
  function renderOccHeatmap() {
    var host = $("bs-occ-heat");
    if (!host) return;
    if (!extraOn("occHeatmap") || S.peaksView !== "heatmap") {
      host.hidden = true;
      return;
    }
    host.hidden = false;
    var days = Number(($("bs-occ-days") && $("bs-occ-days").value) || S.occDays || 7);
    S.occDays = days;
    var mat = occHeatMatrix(days);
    if (!mat.bands.length) {
      host.innerHTML = '<p class="bs-empty">No occupancy yet. Run Scan bands with <b>Band × hour heatmap</b> (and/or Digi survey) enabled under Settings → Extras.</p>';
      return;
    }
    var max = 1;
    Object.keys(mat.cells).forEach(function (k) { if (mat.cells[k] > max) max = mat.cells[k]; });
    var html = '<table class="bs-heat-table"><thead><tr><th>Band</th>';
    for (var h = 0; h < 24; h++) html += "<th>" + h + "</th>";
    html += "</tr></thead><tbody>";
    mat.bands.forEach(function (b) {
      html += "<tr><th>" + escapeHtml(b) + "</th>";
      for (var hr = 0; hr < 24; hr++) {
        var v = mat.cells[b + "|" + hr] || 0;
        var a = v ? Math.min(0.92, 0.12 + 0.8 * (v / max)) : 0;
        html += '<td title="' + escapeHtml(b) + " @ " + hr + ":00 · score " + v +
          '" style="background:rgba(249,115,22,' + a + ')">' + (v ? "" : "") + "</td>";
      }
      html += "</tr>";
    });
    html += "</tbody></table>";
    host.innerHTML = html;
  }
  function setPeaksView(mode) {
    S.peaksView = mode === "heatmap" ? "heatmap" : "list";
    saveSettings();
    var listOn = S.peaksView === "list";
    if ($("bs-hitwrap")) $("bs-hitwrap").hidden = !listOn;
    if ($("bs-peaks-view-list")) $("bs-peaks-view-list").classList.toggle("bs-on", listOn);
    if ($("bs-peaks-view-heat")) $("bs-peaks-view-heat").classList.toggle("bs-on", !listOn);
    if (listOn) renderHits();
    else renderOccHeatmap();
  }
  function applyDigiModeIfNeeded(pid, label) {
    if (!extraOn("digiSurvey") || !S.digiForceOn) return;
    var mod = String(S.digiForceMode || "ft8").trim();
    if (!mod) return;
    if (!isDigiProfile(pid, label) && !/ft8|ft4|wspr|jt/i.test(mod)) {
      /* still allow force when user asked */
    }
    try {
      if (window.UI && typeof UI.setModulation === "function") UI.setModulation(mod, "");
    } catch (e) {}
  }
  function digiDwellForProfile(pid, label, baseDwell) {
    var d = Number(baseDwell) || 2.5;
    if (!extraOn("digiSurvey") || !S.digiLongDwell) return d;
    if (!isDigiProfile(pid, label)) return d;
    return Math.max(d, Math.min(180, Number(S.digiDwellSec) || 90));
  }
  function markBookmarksScannable(onlyAuto) {
    if (typeof BookmarkLocalStorage !== "function" && !(window.bookmarks && bookmarks.localBookmarks)) {
      setStatus("Local bookmarks API missing — cannot mark scannable.");
      return 0;
    }
    var store = (window.bookmarks && bookmarks.localBookmarks) || new BookmarkLocalStorage();
    var list = store.getBookmarks() || [];
    var n = 0;
    list.forEach(function (b) {
      if (onlyAuto && !b.auto && !/^\[auto\]/i.test(b.name || "")) return;
      if (!b.scannable) { b.scannable = true; n++; }
      else b.scannable = true;
    });
    store.setBookmarks(list);
    if (window.bookmarks && typeof bookmarks.loadLocalBookmarks === "function") {
      try { bookmarks.loadLocalBookmarks(); } catch (e) {}
    }
    return n;
  }
  function startExternalScanner() {
    var started = false;
    try {
      if (window.fs_scanner_state && !fs_scanner_state.running && typeof fs_start_scanner === "function") {
        fs_start_scanner();
        started = true;
      }
    } catch (e) {}
    if (!started) {
      try {
        if (window.UI && typeof UI.toggleScanner === "function") {
          UI.toggleScanner(true);
          started = true;
        }
      } catch (e2) {}
    }
    return started;
  }
  function sendToScannerAction() {
    if (!extraOn("sendToScanner")) return;
    var n = markBookmarksScannable(false);
    var ok = startExternalScanner();
    setStatus((ok ? "Scanner started" : "Could not start scanner (is the OpenWebRX+ scanner available?)") +
      " · scannable bookmarks updated (" + n + " newly marked).");
    toast(ok ? "Sent to scanner" : "Marked scannable — start the scanner from the receiver SQ controls");
  }
  function shareSurveyReport() {
    if (!extraOn("shareReport")) return;
    var top = sortedHits().filter(function (h) { return !isSpur(h); }).slice(0, 18);
    var w = 720;
    var h = 420 + (extraOn("occHeatmap") ? 160 : 0);
    var c = document.createElement("canvas");
    c.width = w;
    c.height = h;
    var ctx = c.getContext("2d");
    ctx.fillStyle = "#0f172a";
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = "#f8fafc";
    ctx.font = "bold 20px sans-serif";
    ctx.fillText("OpenWebRX Toolbox", 24, 36);
    ctx.font = "13px sans-serif";
    ctx.fillStyle = "#94a3b8";
    ctx.fillText(new Date().toLocaleString() + " · " + hits.length + " peaks stored · top " + top.length, 24, 58);
    ctx.fillStyle = "#e2e8f0";
    ctx.font = "12px monospace";
    var y = 84;
    top.forEach(function (hit, i) {
      var line = (i + 1) + ". " + fmtMhz(hit.freq) + "  seen " + hit.seen + "×  " +
        Math.round(hit.maxDb || 0) + " dB  " + (hit.name || hit.label || hit.pid || "");
      ctx.fillText(line.slice(0, 88), 24, y);
      y += 16;
    });
    if (extraOn("occHeatmap") && occHeatLog.length) {
      y += 10;
      ctx.fillStyle = "#fb923c";
      ctx.font = "bold 13px sans-serif";
      ctx.fillText("Occupancy (last surveys) — darker = busier hour", 24, y);
      y += 12;
      var mat = occHeatMatrix(Number(S.occDays) || 7);
      var cellW = Math.floor((w - 100) / 24);
      var cellH = 12;
      mat.bands.slice(0, 8).forEach(function (b, bi) {
        var max = 1;
        for (var hr = 0; hr < 24; hr++) max = Math.max(max, mat.cells[b + "|" + hr] || 0);
        ctx.fillStyle = "#cbd5e1";
        ctx.font = "10px sans-serif";
        ctx.fillText(b, 24, y + bi * (cellH + 4) + 10);
        for (var hr2 = 0; hr2 < 24; hr2++) {
          var v = mat.cells[b + "|" + hr2] || 0;
          var a = v ? Math.min(0.95, 0.15 + 0.8 * (v / max)) : 0.06;
          ctx.fillStyle = "rgba(249,115,22," + a + ")";
          ctx.fillRect(90 + hr2 * cellW, y + bi * (cellH + 4), cellW - 1, cellH);
        }
      });
    }
    try {
      c.toBlob(function (blob) {
        if (!blob) {
          setStatus("Share report failed (canvas).");
          return;
        }
        var a = document.createElement("a");
        a.href = URL.createObjectURL(blob);
        a.download = "toolbox-report-" + Date.now() + ".png";
        a.click();
        setTimeout(function () { try { URL.revokeObjectURL(a.href); } catch (e) {} }, 2000);
        setStatus("Survey report PNG downloaded.");
      }, "image/png");
    } catch (err) {
      setStatus(friendlyError(err, "Share report"));
    }
  }


  function copyTuneText(freq, mode) {
    var mhz = fmtMhzNum(freq);
    var text = mhz + " MHz" + (mode ? (" " + mode) : "");
    function ok() { setStatus("Copied: " + text); }
    function fail() { try { prompt("Copy:", text); } catch (e) {} }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(ok).catch(fail);
    } else fail();
  }

  function addNamedBookmarkFromPeak(freq) {
    var hit = null;
    for (var i = 0; i < hits.length; i++) {
      if (Math.abs(hits[i].freq - freq) < 2500) { hit = hits[i]; break; }
    }
    if (!hit) {
      setStatus("Peak not found.");
      return;
    }
    var name = window.prompt("Bookmark name:", hit.name || existingName(hit.freq) || fmtMhz(hit.freq));
    if (name == null) return;
    name = String(name).trim();
    if (!name) return;
    hit.name = name;
    hit.auto = false;
    var r = addBookmark(hit);
    if (r && !r.already) {
      /* force non-auto name */
      try {
        var store = (window.bookmarks && bookmarks.localBookmarks) || new BookmarkLocalStorage();
        var list = store.getBookmarks() || [];
        for (var j = 0; j < list.length; j++) {
          if (Math.abs(list[j].frequency - hit.freq) < 2500) {
            list[j].name = name;
            list[j].auto = false;
            store.setBookmarks(list);
            if (window.bookmarks && typeof bookmarks.loadLocalBookmarks === "function") bookmarks.loadLocalBookmarks();
            break;
          }
        }
      } catch (e) {}
    }
    refreshBookmarks();
    setStatus("Saved named bookmark: " + name);
  }

  function nearbyTrafficHint(freq) {
    if (!extraOn("nearbyTraffic")) return "";
    try {
      if (window.Planes && typeof Planes.getPlanes === "function") {
        var planes = Planes.getPlanes() || [];
        if (planes.length) return '<span class="bs-hint" title="Aircraft data present on page">✈' + planes.length + "</span> ";
      }
    } catch (e) {}
    try {
      if (document.getElementById("openwebrx-map") || document.querySelector(".aircraft, .adsb, #aircraft")) {
        return '<span class="bs-hint" title="Map/traffic UI detected on page">map</span> ';
      }
    } catch (e2) {}
    return "";
  }

  function sortListenItemsExtra(items) {
    var order = S.listenScanOrder || "priority";
    if (!extraOn("scanOrder") || order === "priority") return sortListenPriority(items);
    var copy = (items || []).slice();
    if (order === "freq") copy.sort(function (a, b) { return (a.freq || a.frequency || 0) - (b.freq || b.frequency || 0); });
    else if (order === "name") copy.sort(function (a, b) {
      return String(a.name || "").localeCompare(String(b.name || ""));
    });
    else if (order === "random") {
      for (var i = copy.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var tmp = copy[i]; copy[i] = copy[j]; copy[j] = tmp;
      }
    }
    return copy;
  }

  function bindExtrasKeyboard() {
    if (bindExtrasKeyboard._on) return;
    bindExtrasKeyboard._on = true;
    window.addEventListener("keydown", function (ev) {
      if (!extraOn("keyboard")) return;
      if (!$("bs-panel") || $("bs-panel").hidden) return;
      var tag = (ev.target && ev.target.tagName) || "";
      if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || (ev.target && ev.target.isContentEditable)) return;
      var k = (ev.key || "").toLowerCase();
      if (k === "s") {
        ev.preventDefault();
        if ($("bs-stop") && !$("bs-stop").hidden) $("bs-stop").click();
        else if ($("bs-stop-bm") && !$("bs-stop-bm").hidden) $("bs-stop-bm").click();
      }
      else if (k === "b") { ev.preventDefault(); if ($("bs-listen-top")) $("bs-listen-top").click(); }
      else if (k === "h") { ev.preventDefault(); if ($("bs-hold")) $("bs-hold").click(); }
      else if (k === "k" || ev.key === "ArrowRight") {
        ev.preventDefault();
        if ($("bs-skip")) $("bs-skip").click();
      } else if (ev.key === "ArrowLeft") {
        ev.preventDefault();
        if (listenScanRunning) {
          listenCmd = "prev";
          setStatus("Previous bookmark…");
        }
      }
    });
  }

  function tryTranscribeClip(id, opts) {
    opts = opts || {};
    if (!opts.force && !extraOn("speechToText")) return;
    var Rec = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!Rec) {
      setStatus("Speech recognition not available in this browser (try Chrome).");
      return;
    }
    var clip = null;
    for (var i = 0; i < audioClips.length; i++) if (audioClips[i].id === id) clip = audioClips[i];
    if (!clip || !clip.url) return;
    playAudioClip(id);
    var rec = new Rec();
    rec.lang = "en-US";
    rec.interimResults = false;
    rec.onresult = function (ev) {
      var text = "";
      for (var i = 0; i < ev.results.length; i++) text += ev.results[i][0].transcript + " ";
      text = text.trim();
      clip.transcript = text;
      persistAudioClip(clip);
      setStatus("Transcript: " + text.slice(0, 120));
      renderAudioClips();
      renderDecodeQueue();
    };
    rec.onerror = function () { setStatus("Transcribe failed or mic/permission issue."); };
    try { rec.start(); } catch (e) { setStatus("Could not start speech recognition."); }
  }

  function sanitizeLayoutSettings(d) {
    var layoutDefaults = {
      panelW: 0, panelH: 0, splitPct: 62, leftSplitPct: 58,
      rightSplit1: 28, rightSplit2: 52, rightSplit3: 76
    };
    Object.keys(layoutDefaults).forEach(function (k) {
      var v = Number(d[k]);
      if (!isFinite(v)) d[k] = layoutDefaults[k];
    });
    if (typeof d.panelLeft !== "number" || !isFinite(d.panelLeft)) d.panelLeft = null;
    if (typeof d.panelTop !== "number" || !isFinite(d.panelTop)) d.panelTop = null;
    if (!Array.isArray(d.hiddenTabs)) d.hiddenTabs = [];
    d.hiddenTabs = d.hiddenTabs.filter(function (id) {
      if (!id || id === "settings") return false;
      if (!TAB_IDS || !TAB_IDS.length) return id !== "freq";
      return TAB_IDS.indexOf(id) >= 0;
    });
    /* Analyzer tab is experimental — default off for new + existing installs. */
    if (!d.analyzerTabMigrated) {
      if (d.hiddenTabs.indexOf("analyzer") < 0) d.hiddenTabs.push("analyzer");
      d.analyzerTabMigrated = true;
    }
    /* Explore is the default startup tab (leftmost). One-time migrate from older "last"/Bands default. */
    if (!d.exploreDefaultTabMigrated) {
      if (!d.defaultTab || d.defaultTab === "last" || d.defaultTab === "bands") {
        d.defaultTab = "explore";
      }
      d.exploreDefaultTabMigrated = true;
    }
    if (typeof d.defaultTab !== "string" || (TAB_IDS.indexOf(d.defaultTab) < 0 && d.defaultTab !== "last")) {
      d.defaultTab = "explore";
    }
    /* Decode used to be its own tab (off by default); now lives under Audio. */
    if (!d.decodeIntoAudioMigrated) {
      d.hiddenTabs = (d.hiddenTabs || []).filter(function (id) { return id !== "decode"; });
      if (d.defaultTab === "decode") d.defaultTab = "audio";
      d.decodeIntoAudioMigrated = true;
      d.decodeTabMigrated = true;
    } else if (!d.decodeTabMigrated) {
      d.decodeTabMigrated = true;
    }
    /* Drop removed Freq tab from saved hidden lists */
    d.hiddenTabs = d.hiddenTabs.filter(function (id) { return id !== "freq"; });
    delete d.freqTabMigrated;
    if (typeof d.hideToolbar !== "boolean") d.hideToolbar = false;
    if (typeof d.hideStockReceiver !== "boolean") d.hideStockReceiver = false;
    if (typeof d.muteOnTabHide !== "boolean") d.muteOnTabHide = true;
    if (typeof d.btnColoursOff !== "boolean") d.btnColoursOff = false;
    if (typeof d.btnShadeHoverHint !== "boolean") d.btnShadeHoverHint = true;
    /* v338+: stock look — no button colours; colours stay off until the user opts in. */
    if (!d._btnNoColoursV338) {
      d.btnColoursOff = true;
      d.btnShades = {};
      d._btnNoColoursV338 = true;
    }
    /* v341: colours-off also neutralizes role CSS (not only custom shades). Force on once more. */
    if (!d._btnNoColoursV341) {
      d.btnColoursOff = true;
      d.btnShades = {};
      d._btnNoColoursV341 = true;
    }
    /* v344: CSS role colours are neutral by default; clear any leftover saved shades. */
    if (!d._btnNoColoursV344) {
      d.btnColoursOff = true;
      d.btnShades = {};
      d._btnNoColoursV344 = true;
    }
    /* v351: Don’t show button colour picker is unticked by default (picker available). */
    if (!d._btnColoursOffUntickV351) {
      d.btnColoursOff = false;
      d._btnColoursOffUntickV351 = true;
    }
    d.publicPolicy = sanitizePublicPolicy(d.publicPolicy);
    d.panelSideDockSide = "left";
    var spPct = Number(d.panelSidePct);
    if (!isFinite(spPct)) d.panelSidePct = 35;
    else d.panelSidePct = normalizePreferredSidePct(spPct);
    if (typeof d.panelSideDock !== "boolean") d.panelSideDock = true;
    /* Always left dock; migrate any saved "right" preference. */
    if (!d.sideDockAlwaysLeftMigrated) {
      d.panelSideDock = true;
      d.panelSideDockSide = "left";
      d.sideDockAlwaysLeftMigrated = true;
    }
    if (!Array.isArray(d.loadUserBmBands)) {
      d.loadUserBmBands = [];
      var old = d.loadUserBmScope;
      if (typeof old === "string" && old.indexOf("p:") === 0) {
        d.loadUserBmBands = [old.slice(2)];
      }
    }
    delete d.loadUserBmScope;
    d.extras = sanitizeExtras(d.extras);
    if (d.extras && d.extras.autoStartOwrx) d.autoStartOwrx = true;
    d.maxClipSec = Math.max(5, Math.min(600, Number(d.maxClipSec) || 60));
    if (!d.listenScanOrder) d.listenScanOrder = "priority";
    d.listenPasses = Math.max(0, Math.min(999, Number(d.listenPasses) || 0));
    d.passes = Math.max(1, Math.min(MAX_PASSES, Number(d.passes) || 2));
    if (typeof d.listenAskPasses !== "boolean") d.listenAskPasses = true;
    if (typeof d.digiLongDwell !== "boolean") d.digiLongDwell = false;
    d.digiDwellSec = Math.max(15, Math.min(180, Number(d.digiDwellSec) || 90));
    if (!d.digiForceMode) d.digiForceMode = "ft8";
    if (typeof d.digiForceOn !== "boolean") d.digiForceOn = false;
    if (typeof d.dayNightBeforeSched !== "boolean") d.dayNightBeforeSched = false;
    if (d.peaksView !== "heatmap") d.peaksView = "list";
    d.occDays = Math.max(1, Math.min(30, Number(d.occDays) || 7));
    if (typeof d.showNewOnly !== "boolean") d.showNewOnly = false;
    if (typeof d.showDiffOnly !== "boolean") d.showDiffOnly = false;
    if (!d.bandMeta || typeof d.bandMeta !== "object" || Array.isArray(d.bandMeta)) d.bandMeta = {};
    if (!Array.isArray(d.bandOrder)) d.bandOrder = [];
    if (d.uiDensity !== "minimal") d.uiDensity = "full";
    d.tabDensity = normalizeTabDensityMap(d.tabDensity);
    d.uxFeel = normalizeUxFeel(d.uxFeel);
    if (d.chkStyle !== "switch") d.chkStyle = "tick";
    if (typeof d.bdEditMinimal !== "boolean") d.bdEditMinimal = false;
    if (typeof d.bdEditPopMinimal !== "boolean") d.bdEditPopMinimal = false;
    if (typeof d.clipMuted !== "boolean") d.clipMuted = false;
    var cv = Number(d.clipVolume);
    d.clipVolume = Math.max(0, Math.min(100, isFinite(cv) ? cv : 80));
    if (typeof saDefaultsPatch === "function") saDefaultsPatch(d);
    if (typeof rangeExtrasDefaultsPatch === "function") rangeExtrasDefaultsPatch(d);
    delete d.leftTopSplit1;
    delete d.leftTopSplit2;
    return d;
  }

