  function isSubTabBtn(el) {
    if (!el || !el.classList) return false;
    return el.classList.contains("bs-bm-sub") ||
      el.classList.contains("bs-bd-sub") ||
      el.classList.contains("bs-au-sub") ||
      el.classList.contains("bs-rg-sub");
  }

  function isMainTabBtn(el) {
    return !!(el && el.classList && el.classList.contains("bs-tab") && el.getAttribute("data-tab"));
  }

  function subTabKind(el) {
    if (!el || !el.getAttribute) return "";
    return el.getAttribute("data-bm-sub") ||
      el.getAttribute("data-bd-sub") ||
      el.getAttribute("data-au-sub") ||
      el.getAttribute("data-rg-sub") ||
      "";
  }

  function btnInShadeRoot(btn) {
    if (!btn || !btn.closest) return false;
    for (var i = 0; i < BTN_SHADE_ROOTS.length; i++) {
      if (btn.closest(BTN_SHADE_ROOTS[i])) return true;
    }
    return false;
  }

  function forEachBtnShadeRoot(fn) {
    BTN_SHADE_ROOTS.forEach(function (sel) {
      var el = document.querySelector(sel);
      if (el) fn(el);
    });
  }

  function btnRoleFromEl(el) {
    if (!el || !el.classList) return null;
    if (el.classList.contains("bs-x") || el.classList.contains("bs-check-dismiss")) return null;
    if (el.classList.contains("bs-ex-mode")) return null;
    /* Stock-look SQL auto — colour locked to OpenWebRX chrome. */
    if (el.id === "bs-ex-sql-auto" || el.classList.contains("openwebrx-squelch-auto") || el.getAttribute("data-bs-no-shade") === "1") return null;
    if (el.classList.contains("bs-shade-swatch") || el.classList.contains("bs-box-help") || el.classList.contains("bs-box-help-close")) return null;
    if (el.classList.contains("bs-set-box-toggle") || el.classList.contains("bs-ex-box-toggle")) return null;
    if (isMainTabBtn(el)) return { id: "maintab", cls: "bs-tab", label: "Tab" };
    if (isSubTabBtn(el)) return { id: "subtab", cls: "bs-subtab", label: "Sub tab" };
    var i, meta;
    for (i = 0; i < BTN_ROLE_META.length; i++) {
      meta = BTN_ROLE_META[i];
      if (el.classList.contains(meta.cls)) return meta;
      if (meta.id === "jump" && el.classList.contains("bs-ex-nudge")) return meta;
      if (meta.id === "jump" && el.classList.contains("bs-ex-arrow")) return meta;
    }
    return null;
  }

  function ensureBtnShadesObj() {
    if (!S.btnShades || typeof S.btnShades !== "object") S.btnShades = {};
    return S.btnShades;
  }

  function cssEscapeIdent(s) {
    return String(s || "").replace(/([^\w-])/g, "\\$1");
  }

  function btnShadeKey(el) {
    if (!el) return null;
    if (isMainTabBtn(el)) {
      var tabId = el.getAttribute("data-tab");
      if (!tabId) return null;
      var tabKey = "tab:" + tabId;
      el.setAttribute("data-bs-btn", tabKey);
      return tabKey;
    }
    if (isSubTabBtn(el)) {
      var kind = subTabKind(el);
      var pane = el.closest && el.closest(".bs-tab-pane[data-tab], [id^='bs-tab-'][data-tab]");
      var paneTabId = (pane && pane.getAttribute("data-tab")) || "tab";
      if (!kind) return null;
      var subKey = "sub:" + paneTabId + ":" + kind;
      el.setAttribute("data-bs-btn", subKey);
      return subKey;
    }
    if (el.id) return "id:" + el.id;
    var existing = el.getAttribute("data-bs-btn");
    if (existing) return existing;
    var parts = [];
    var preset = el.getAttribute("data-preset");
    if (preset) parts.push("preset:" + preset);
    var pack = el.getAttribute("data-band-pack") || el.getAttribute("data-pack-dl");
    if (pack) parts.push("pack:" + pack);
    var role = btnRoleFromEl(el);
    if (role) parts.push("role:" + role.id);
    var txt = String(el.textContent || "").replace(/\s+/g, " ").trim().slice(0, 32);
    if (txt) parts.push("t:" + txt);
    if (!parts.length) return null;
    var key = "btn:" + parts.join("|");
    key = key.replace(/[^\w:.\-|]+/g, "_").slice(0, 96);
    el.setAttribute("data-bs-btn", key);
    return key;
  }

  function btnShadeSelector(key) {
    key = String(key || "");
    if (key.indexOf("id:") === 0) {
      /* IDs are unique — match panel and body-hosted popups. */
      return "button#" + cssEscapeIdent(key.slice(3)) + ":not(.bs-on)";
    }
    var attr = key.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
    return BTN_SHADE_ROOTS.map(function (root) {
      return root + ' button[data-bs-btn="' + attr + '"]:not(.bs-on)';
    }).join(",");
  }

  function btnShadeIsSubTabKey(key) {
    return String(key || "").indexOf("sub:") === 0;
  }

  function btnShadeIsMainTabKey(key) {
    return String(key || "").indexOf("tab:") === 0;
  }

  function btnFactoryShadeForKey(key) {
    key = String(key || "");
    if (!key || key === "id:bs-ex-sql-auto") return null;
    var shade = BTN_FACTORY_BTN_SHADES && BTN_FACTORY_BTN_SHADES[key];
    if (shade && BTN_SHADES[shade]) return shade;
    return null;
  }

  function btnDefaultShadeName(el) {
    /* Main tabs use stock CSS until a shade is chosen — Default clears the key. */
    if (isMainTabBtn(el)) return "";
    var key = el && (el.id ? ("id:" + el.id) : el.getAttribute && el.getAttribute("data-bs-btn"));
    if (!key && el) {
      try { key = btnShadeKey(el); } catch (eKey) { key = null; }
    }
    var fac = btnFactoryShadeForKey(key);
    if (fac) return fac;
    var meta = btnRoleFromEl(el);
    if (meta && BTN_DEFAULT_SHADE[meta.id]) return BTN_DEFAULT_SHADE[meta.id];
    return "zinc";
  }

  function btnShadeLabel(el) {
    var txt = String((el && el.textContent) || "").replace(/\s+/g, " ").trim();
    if (txt) return txt.slice(0, 28);
    var meta = btnRoleFromEl(el);
    return (meta && meta.label) || "Button";
  }

  /** Old builds stored one shade per button *type*; expand those onto each matching button once. */
  function migrateRoleBtnShades() {
    var map = ensureBtnShadesObj();
    var dirty = false;
    Object.keys(BTN_DEFAULT_SHADE).forEach(function (role) {
      var shade = map[role];
      if (!shade || !BTN_SHADES[shade]) return;
      delete map[role];
      dirty = true;
      forEachBtnShadeRoot(function (root) {
        Array.prototype.forEach.call(root.querySelectorAll("button"), function (btn) {
          var meta = btnRoleFromEl(btn);
          if (!meta || meta.id !== role) return;
          var k = btnShadeKey(btn);
          if (k && map[k] == null) map[k] = shade;
        });
      });
    });
    if (dirty) {
      S.btnShades = map;
      try { saveSettings(); } catch (eMig) {}
    }
  }

  function stampBtnShadeAttrs() {
    forEachBtnShadeRoot(function (root) {
      Array.prototype.forEach.call(root.querySelectorAll("button"), function (btn) {
        /* Main / sub tabs must get data-bs-btn or saved shades never match after reload. */
        if (isMainTabBtn(btn) || isSubTabBtn(btn)) {
          btnShadeKey(btn);
          return;
        }
        if (!btnRoleFromEl(btn)) return;
        if (btn.id) return;
        btnShadeKey(btn);
      });
    });
  }

  function btnColoursOffNeutralCss() {
    /* Neutralize stock role colours (Scan blue, Stop red, …) — not only custom shades. */
    var roots = "#bs-panel, #bs-bm-edit-pop, #bs-bd-edit-pop, #bs-help, #bs-fallback, #bs-box-help-pop";
    var roles = [
      "bs-primary", "bs-stop", "bs-btn-fresh", "bs-btn-jump", "bs-btn-hold", "bs-btn-skip",
      "bs-btn-lock", "bs-btn-go", "bs-btn-bm", "bs-btn-util", "bs-btn-info", "bs-btn-export",
      "bs-btn-import", "bs-btn-clear", "bs-btn-preset", "bs-btn-play", "bs-tune", "bs-ex-btn",
      "bs-ex-nudge"
    ];
    var sel = roles.map(function (cls) {
      return roots.split(", ").map(function (r) { return r + " button." + cls; }).join(",");
    }).join(",");
    var hoverSel = roles.map(function (cls) {
      return roots.split(", ").map(function (r) {
        return r + " button." + cls + ":hover," + r + " button." + cls + ":active";
      }).join(",");
    }).join(",");
    var pack = "#bs-panel .bs-pack-list button," +
      "#bs-panel .bs-pack-list button.bs-pack-present," +
      "#bs-panel .bs-pack-list button[data-band-pack]";
    return sel + "{background:#1e293b !important;color:#e2e8f0 !important;border-color:#64748b !important;}" +
      hoverSel + "{background:#475569 !important;color:#e2e8f0 !important;border-color:#94a3b8 !important;}" +
      pack + "{background:#1e293b !important;color:#e2e8f0 !important;border-color:#64748b !important;opacity:1 !important;}" +
      pack + ":hover{background:#475569 !important;}" +
      /* Keep selected sub-tabs yellow and .bs-on amber (those rules already use !important). */
      "";
  }

  function applyBtnShades() {
    migrateRoleBtnShades();
    stampBtnShadeAttrs();
    var style = $("bs-btn-shade-style");
    if (!style) {
      style = document.createElement("style");
      style.id = "bs-btn-shade-style";
      document.head.appendChild(style);
    }
    var map = ensureBtnShadesObj();
    /* Drop any saved shade for stock-locked SQL auto. */
    var shadeDirty = false;
    if (map["id:bs-ex-sql-auto"]) {
      delete map["id:bs-ex-sql-auto"];
      shadeDirty = true;
    }
    /* One-shot: drop former Bands sub-tab factory colours → CSS yellow when selected. */
    if (!S._bandSubShadesCleared) {
      BTN_SHADE_CLEAR_KEYS.forEach(function (k) {
        if (map[k]) {
          delete map[k];
          shadeDirty = true;
        }
      });
      S._bandSubShadesCleared = true;
      shadeDirty = true;
    }
    if (shadeDirty) {
      S.btnShades = map;
      try { saveSettings(); } catch (eSqlShade) {}
    }
    var css = "";
    if (S.btnColoursOff) {
      /* Default / factory: no custom shades and no stock role colours — neutral slate. */
      css = btnColoursOffNeutralCss();
    } else {
      Object.keys(map).forEach(function (key) {
        var shadeName = map[key];
        if (!shadeName || !BTN_SHADES[shadeName]) return;
        if (key === "id:bs-ex-sql-auto") return;
        if (BTN_DEFAULT_SHADE.hasOwnProperty(key)) return;
        var shade = BTN_SHADES[shadeName];
        var sel = btnShadeSelector(key);
        if (btnShadeIsMainTabKey(key)) {
          var tabAttr = key.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
          var tabSel = '#bs-panel button.bs-tab[data-bs-btn="' + tabAttr + '"]';
          /* Colour inactive tabs only — the active tab always stays yellow (.bs-tab-on). */
          css += tabSel + ":not(.bs-tab-on){background:" + shade.bg + " !important;color:" + shade.fg +
            " !important;border-color:" + shade.border + " !important;}" +
            tabSel + ":not(.bs-tab-on):hover{background:" + shade.hover + " !important;}";
          return;
        }
        if (btnShadeIsSubTabKey(key)) {
          var subSel = '#bs-panel button[data-bs-btn="' + key.replace(/\\/g, "\\\\").replace(/"/g, '\\"') + '"]';
          css += subSel + "{background:" + shade.bg + " !important;color:" + shade.fg +
            " !important;border-color:" + shade.border + " !important;}" +
            subSel + ":hover{background:" + shade.hover + " !important;}" +
            subSel + ".bs-bm-sub-on," + subSel + ".bs-bd-sub-on," +
            subSel + ".bs-au-sub-on," + subSel + ".bs-rg-sub-on{" +
            "box-shadow:inset 0 -3px 0 " + shade.border + " !important;}";
          return;
        }
        css += sel + "{background:" + shade.bg + " !important;color:" + shade.fg +
          " !important;border-color:" + shade.border + " !important;}" +
          sel + ":hover{background:" + shade.hover + " !important;}";
      });
    }
    /* Skip identical writes — readForm/scans call this often; rewriting the sheet flashes buttons. */
    if (applyBtnShades._css === css && style.textContent === css) return;
    applyBtnShades._css = css;
    style.textContent = css;
  }

  function closeBtnShadeMenu() {
    var menu = $("bs-shade-menu");
    if (menu) menu.hidden = true;
  }

  function openBtnShadeMenu(ev, btn) {
    try { closeTabContextMenu(); } catch (eTab) {}
    if (S.btnColoursOff) {
      setStatus("Colour picker is off — tick “Show colour picker” under Settings → Appearance.");
      return;
    }
    var menu = $("bs-shade-menu");
    if (!menu || !btn) return;
    var key = btnShadeKey(btn);
    if (!key) return;
    var map = ensureBtnShadesObj();
    var def = btnDefaultShadeName(btn);
    var cur = map[key] || def;
    var title = menu.querySelector(".bs-shade-title");
    var what = isMainTabBtn(btn) ? "tab" : (isSubTabBtn(btn) ? "sub-tab" : "button");
    if (title) title.textContent = btnShadeLabel(btn) + " — this " + what + " only";
    var hint = menu.querySelector(".bs-shade-hint");
    if (hint) {
      if (isMainTabBtn(btn)) {
        hint.textContent = "Colour applies when this tab is not selected — the active tab stays yellow. Default restores the stock look.";
      } else if (isSubTabBtn(btn)) {
        hint.textContent = "Colour applies to this sub-tab only — other sub-tabs stay unchanged.";
      } else {
        hint.textContent = "Colour applies to this button only — not every similar button.";
      }
    }
    var grid = menu.querySelector(".bs-shade-swatches");
    if (grid) {
      grid.innerHTML = Object.keys(BTN_SHADES).map(function (shadeKey) {
        var sh = BTN_SHADES[shadeKey];
        var on = shadeKey === cur ? " bs-shade-on" : "";
        return '<button type="button" class="bs-shade-swatch' + on + '" data-shade="' + shadeKey +
          '" title="' + shadeKey + '" style="background:' + sh.bg + ';border-color:' + sh.border +
          ';color:' + sh.fg + '">' + shadeKey.charAt(0).toUpperCase() + "</button>";
      }).join("");
    }
    menu.setAttribute("data-btn-key", key);
    menu.setAttribute("data-btn-default", def);
    menu.removeAttribute("data-role");
    menu.hidden = false;
    var x = ev.clientX;
    var y = ev.clientY;
    menu.style.left = "0px";
    menu.style.top = "0px";
    var w = menu.offsetWidth || 220;
    var h = menu.offsetHeight || 160;
    var left = Math.min(x, window.innerWidth - w - 8);
    var top = Math.min(y, window.innerHeight - h - 8);
    menu.style.left = Math.max(8, left) + "px";
    menu.style.top = Math.max(8, top) + "px";
  }

  function bindButtonPressFlash(root) {
    if (!root || root._bs_press_flash) return;
    root._bs_press_flash = true;
    function clearPress(btn) {
      if (!btn) return;
      btn.classList.remove("bs-press");
      if (btn._bs_press_t) {
        try { clearTimeout(btn._bs_press_t); } catch (eT) {}
        btn._bs_press_t = 0;
      }
    }
    root.addEventListener("pointerdown", function (ev) {
      if (ev.button != null && ev.button !== 0) return;
      var t = ev.target;
      if (!t || !t.closest) return;
      var btn = t.closest("button");
      if (!btn || !root.contains(btn)) return;
      if (btn.disabled || btn.classList.contains("bs-x") || btn.classList.contains("bs-check-dismiss")) return;
      if (btn.classList.contains("openwebrx-squelch-auto") || btn.id === "bs-ex-sql-auto") return;
      clearPress(btn);
      btn.classList.add("bs-press");
      btn._bs_press_t = setTimeout(function () { clearPress(btn); }, 180);
    }, true);
    root.addEventListener("pointerup", function (ev) {
      var t = ev.target;
      if (!t || !t.closest) return;
      clearPress(t.closest("button"));
    }, true);
    root.addEventListener("pointercancel", function (ev) {
      var t = ev.target;
      if (!t || !t.closest) return;
      clearPress(t.closest("button"));
    }, true);
  }

  function bindBtnShadePicker(panel) {
    if (!panel) return;
    /* Recreate picker if an older type-based menu is still in the DOM. */
    var existingMenu = $("bs-shade-menu");
    if (existingMenu && existingMenu.getAttribute("data-per-btn") !== "1") {
      existingMenu.parentNode.removeChild(existingMenu);
      existingMenu = null;
    }
    if (!$("bs-shade-menu")) {
      var menu = document.createElement("div");
      menu.id = "bs-shade-menu";
      menu.setAttribute("data-per-btn", "1");
      menu.hidden = true;
      menu.setAttribute("role", "menu");
      menu.innerHTML =
        '<div class="bs-shade-title">Choose shade</div>' +
        '<div class="bs-shade-swatches"></div>' +
        '<div class="bs-shade-actions">' +
        '<button type="button" class="bs-tiny bs-btn-util" data-shade-default="1" title="Restore the default colour for this button only.">Default</button>' +
        '<button type="button" class="bs-tiny bs-btn-clear" data-shade-reset-all="1" title="Restore default colours for every individually coloured button.">Reset all</button>' +
        "</div>" +
        '<p class="bs-shade-hint">Colour applies to this button only</p>';
      document.body.appendChild(menu);
      menu.addEventListener("click", function (ev) {
        ev.stopPropagation();
        var t = ev.target && ev.target.closest && ev.target.closest("[data-shade], [data-shade-default], [data-shade-reset-all]");
        if (!t) return;
        var map = ensureBtnShadesObj();
        if (t.getAttribute("data-shade-reset-all")) {
          S.btnShades = cloneBtnFactoryShades();
          saveSettings();
          applyBtnShades();
          closeBtnShadeMenu();
          setStatus("Button colours reset to factory defaults.");
          return;
        }
        var key = menu.getAttribute("data-btn-key");
        if (!key) return;
        var def = menu.getAttribute("data-btn-default") || "";
        var fac = btnFactoryShadeForKey(key);
        if (t.getAttribute("data-shade-default")) {
          /* Factory-coloured buttons must keep their key so CSS role styles do not replace them. */
          if (fac) map[key] = fac;
          else delete map[key];
        } else {
          var shadeName = t.getAttribute("data-shade");
          if (!BTN_SHADES[shadeName]) return;
          if (fac && shadeName === fac) map[key] = fac;
          else if (def && shadeName === def && !fac) delete map[key];
          else map[key] = shadeName;
        }
        S.btnShades = map;
        saveSettings();
        applyBtnShades();
        closeBtnShadeMenu();
        setStatus("Button colour updated (this button only).");
      });
      if (!bindBtnShadePicker._docClose) {
        bindBtnShadePicker._docClose = true;
        document.addEventListener("click", function () { closeBtnShadeMenu(); });
        document.addEventListener("keydown", function (ev) {
          if (ev.key === "Escape") closeBtnShadeMenu();
        });
      }
    }
    /* Document capture so body-hosted edit popups work, not only #bs-panel. */
    if (!bindBtnShadePicker._ctxBound) {
      bindBtnShadePicker._ctxBound = true;
      document.addEventListener("contextmenu", function (ev) {
        var t = ev.target;
        if (!t) return;
        if (t.nodeType === 3) t = t.parentElement;
        if (!t || !t.closest) return;
        var btn = t.closest("button");
        if (!btn) return;
        if (btn.closest("#bs-shade-menu")) return;
        if (!btnInShadeRoot(btn)) return;
        if (!btnRoleFromEl(btn)) return;
        ev.preventDefault();
        ev.stopPropagation();
        if (typeof ev.stopImmediatePropagation === "function") ev.stopImmediatePropagation();
        openBtnShadeMenu(ev, btn);
      }, true);
    }
    panel.setAttribute("data-bs-shade-bound", "1");
  }

  function resetBtnShades() {
    S.btnShades = cloneBtnFactoryShades();
    saveSettings();
    applyBtnShades();
    setStatus("Button colours reset to factory defaults.");
  }

  function loadHits() {
    try {
      var raw = window.localStorage.getItem(LS_HITS);
      if (!raw) return;
      var o = JSON.parse(raw);
      if (o && Array.isArray(o.hits)) hits = o.hits;
      if (o && o.tileLooks && typeof o.tileLooks === "object") tileLooks = o.tileLooks;
    } catch (e) {}
  }

  function slimHitSamplesIfHuge() {
    if (hits.length < 600) return;
    hits.forEach(function (h) {
      if (h.samples && h.samples.length > 8) h.samples = h.samples.slice(-8);
    });
  }

  function ensureHitsLoaded(done) {
    if (S.keepPeaks === false) {
      _hitsLoaded = true;
      if (done) done(0);
      return;
    }
    if (_hitsLoaded) {
      if (done) done(hits.length);
      return;
    }
    if (done) _hitsLoadQueue.push(done);
    if (_hitsLoading) return;
    _hitsLoading = true;
    setTimeout(function () {
      try {
        loadHits();
        trimPeaksIfNeeded();
        slimHitSamplesIfHuge();
      } catch (e) {}
      _hitsLoaded = true;
      _hitsLoading = false;
      var n = hits.length;
      var q = _hitsLoadQueue.slice();
      _hitsLoadQueue = [];
      q.forEach(function (cb) { cb(n); });
    }, 0);
  }

  function ensureHitsLoadedPromise() {
    return new Promise(function (resolve) {
      ensureHitsLoaded(resolve);
    });
  }

  function ensureHitsClassified() {
    if (_hitsClassified || !hits.length) return;
    classifyAll();
    _hitsClassified = true;
  }

  function saveHits() {
    if (S.keepPeaks === false) return;
    try {
      hits.forEach(function (h) {
        if (h.samples && h.samples.length > 48) h.samples = h.samples.slice(-48);
      });
      window.localStorage.setItem(LS_HITS, JSON.stringify({ hits: hits, tileLooks: tileLooks }));
    } catch (e) {}
  }

  function alwaysOnBand(pid, label) {
    if (/^(fm_|dab_|ais|adsb|vdl2|pocsag|tetra|ism)/.test(pid || "")) return true;
    return isFmBroadcastProfile(pid, label) || isHfBroadcastProfile(pid, label);
  }

  function deferPanelHeavyWork(includeHealth) {
    if (_panelHeavyTimer) clearTimeout(_panelHeavyTimer);
    _panelHeavyTimer = setTimeout(function () {
      _panelHeavyTimer = null;
      fillBands();
      var peaksOpen = panelQs('#bs-tabs .bs-tab.bs-tab-on[data-tab="peaks"]');
      if (peaksOpen) {
        ensureHitsClassified();
        renderHits();
      } else {
        var host = $("bs-hitwrap");
        if (host && hits.length && !host.querySelector("table")) {
          host.innerHTML = '<p class="bs-empty">' + hits.length +
            " peaks stored. Open the Peaks tab to load the table (keeps Toolbox snappy).</p>";
        }
      }
      renderBookmarkPane();
      updateTabLabels();
      if (includeHealth) renderHealth();
      requestAnimationFrame(function () { applyPanelLayout(); });
    }, 0);
  }

  function stddev(arr) {
    if (!arr || arr.length < 4) return 99;
    var m = 0;
    var i;
    for (i = 0; i < arr.length; i++) m += arr[i];
    m /= arr.length;
    var s = 0;
    for (i = 0; i < arr.length; i++) s += (arr[i] - m) * (arr[i] - m);
    return Math.sqrt(s / arr.length);
  }

  function offsetBucket(hz) {
    return Math.round(hz / OFFSET_BUCKET_HZ) * OFFSET_BUCKET_HZ;
  }

  function isIgnoredFreq(freq) {
    var list = S.ignoredFreqs || [];
    for (var i = 0; i < list.length; i++) {
      if (Math.abs(list[i] - freq) < 4000) return true;
    }
    return false;
  }

  function shouldSkipTune(freq) {
    return isLocked(freq) || isIgnoredFreq(freq);
  }

  function isSpur(h) {
    return !!(h && (h.spur || h.ignored || isIgnoredFreq(h.freq)));
  }

  function icao833(hz) {
    if (!hz || hz < 118e6 || hz > 137e6) return "";
    var step = 25000 / 3;
    var n = Math.round(hz / step);
    var rem = ((n % 3) + 3) % 3;
    var block = Math.floor(n / 3) * 25000;
    var suffix = rem === 0 ? 0 : rem === 1 ? 5 : 10;
    var mhz = Math.floor(block / 1e6);
    var frac = Math.round((block % 1e6) / 1000) + suffix;
    return mhz + "." + String(frac).padStart(3, "0");
  }

  function freqKey(hz) {
    return String(Math.round(Number(hz) / 1000));
  }

  function loadSnap() {
    try { return JSON.parse(window.localStorage.getItem(LS_SNAP) || "{}"); } catch (e) { return {}; }
  }

  function saveSnap() {
    var o = loadSnap();
    hits.forEach(function (h) {
      if (!isSpur(h)) o[freqKey(h.freq)] = Date.now();
    });
    try { window.localStorage.setItem(LS_SNAP, JSON.stringify(o)); } catch (e) {}
  }

  function markNewFlags(prev) {
    prev = prev || loadSnap();
    hits.forEach(function (h) {
      h.isNew = !isSpur(h) && !prev[freqKey(h.freq)];
    });
  }

  function loadLockouts() {
    try { return JSON.parse(window.localStorage.getItem(LS_LOCK) || "[]"); } catch (e) { return []; }
  }

  function saveLockouts(list) {
    try { window.localStorage.setItem(LS_LOCK, JSON.stringify(list || [])); } catch (e) {}
  }

  function pruneLockouts() {
    var now = Date.now();
    var list = loadLockouts().filter(function (l) { return l && l.until > now; });
    saveLockouts(list);
    return list;
  }

  function isLocked(freq) {
    return pruneLockouts().some(function (l) { return Math.abs(l.freq - freq) < 4000; });
  }

  function lockout(freq) {
    var minutes = Math.max(1, Number(S.lockoutMin) || 30);
    var list = pruneLockouts().filter(function (l) { return Math.abs(l.freq - freq) >= 4000; });
    list.push({ freq: Math.round(freq), until: Date.now() + minutes * 60 * 1000 });
    saveLockouts(list);
  }

  function parseHzList(s) {
    var out = [];
    String(s || "").split(/[\s,;]+/).forEach(function (p) {
      p = String(p || "").trim();
      if (!p) return;
      var n = parseFloat(p);
      if (!isFinite(n) || n <= 0) return;
      if (n < 2000) n *= 1e6;
      else if (n < 1e6) n *= 1e3;
      out.push(n);
    });
    return out;
  }

  function priorityFreqs() {
    var out = parseHzList(S.priority);
    allBookmarks().forEach(function (b) {
      if (b && b.frequency && b.name && /guard|tower|twr|atis/i.test(b.name)) {
        out.push(b.frequency);
      }
    });
    return out;
  }

  function isPriority(freq) {
    return priorityFreqs().some(function (p) { return Math.abs(p - freq) < 4000; });
  }

  function sortListenPriority(items) {
    var scored = (items || []).map(function (row, idx) {
      var it = row.hit || row;
      var freq = it.freq || it.frequency || row.frequency;
      return {
        row: row,
        idx: idx,
        pri: isPriority(freq) ? 0 : 1,
        pid: String(it.pid || ""),
        seen: (row.hit && row.hit.seen) || row.seen || 0
      };
    });
    var pidPri = {};
    scored.forEach(function (s) {
      if (s.pri === 0 && typeof pidPri[s.pid] === "undefined") pidPri[s.pid] = s.idx;
    });
    scored.sort(function (a, b) {
      var ap = typeof pidPri[a.pid] !== "undefined" ? 0 : 1;
      var bp = typeof pidPri[b.pid] !== "undefined" ? 0 : 1;
      if (ap !== bp) return ap - bp;
      if (a.pid !== b.pid) {
        if (ap === 0) return pidPri[a.pid] - pidPri[b.pid];
        return a.pid < b.pid ? -1 : a.pid > b.pid ? 1 : 0;
      }
      if (a.pri !== b.pri) return a.pri - b.pri;
      if (b.seen !== a.seen) return b.seen - a.seen;
      return a.idx - b.idx;
    });
    return scored.map(function (s) { return s.row; });
  }

  function continuousBmScanOn() {
    return S.continuousBmScan !== false;
  }

  function listenScanIdleTitle() {
    var passes = Math.max(0, Number(S.listenPasses) || 0);
    var passHint = passes > 0 ? (" Runs " + passes + " pass(es).") : " Runs until Stop.";
    return continuousBmScanOn()
      ? ("Loop through bookmarks continuously." + passHint + " New auto bookmarks first, then all local and loaded.")
      : ("Loop bookmarks — pauses on busy channels (Continue / Skip / Hold)." + passHint + " New auto bookmarks first, then all local and loaded.");
  }

  function listenScanPassText() {
    if (!(listenScanPass > 0)) return "";
    if (listenScanMaxPasses > 0) return listenScanPass + "/" + listenScanMaxPasses;
    return String(listenScanPass);
  }

  function setListenScanRunning(on) {
    listenScanRunning = !!on;
    if (!on) {
      listenScanPass = 0;
      listenScanMaxPasses = 0;
    }
    if (on && listenPaused && !continuousBmScanOn()) {
      setListenPaused(true);
      applyToolbarVisibility();
      return;
    }
    var passTxt = listenScanPassText();
    var label = listenScanRunning
      ? (listenPaused && !continuousBmScanOn()
        ? (passTxt ? ("Continue scan · pass " + passTxt) : "Continue scan bookmarks")
        : (passTxt ? ("Scanning bookmarks · " + passTxt) : "Scanning bookmarks"))
      : "Scan bookmarks";
    var title = listenScanRunning
      ? (listenPaused && !continuousBmScanOn()
        ? "Leave this busy channel and continue hopping through bookmarks."
        : (passTxt
          ? ("Bookmark scan pass " + passTxt + " — click Stop to end.")
          : "Bookmark scan is running — click Stop to end."))
      : listenScanIdleTitle();
    var btn = $("bs-listen-top");
    if (btn) {
      btn.textContent = label;
      btn.title = title;
      btn.disabled = listenScanRunning && (continuousBmScanOn() || !listenPaused);
      btn.classList.toggle("bs-on", listenScanRunning || listenPaused);
      btn.classList.toggle("bs-running", listenScanRunning && (continuousBmScanOn() || !listenPaused));
    }
    applyToolbarVisibility();
  }

  function setSurveyRunning(on) {
    surveyRunning = !!on;
    var label = surveyRunning ? "Scanning bands" : "Scan bands";
    var title = surveyRunning
      ? "Toolbox is running — click Stop to end."
      : "Walk ticked bands and add to Seen counts.";
    var btn = $("bs-start");
    if (btn) {
      btn.textContent = label;
      btn.title = title;
      btn.disabled = surveyRunning;
      btn.classList.toggle("bs-on", surveyRunning);
      btn.classList.toggle("bs-running", surveyRunning);
    }
    applyToolbarVisibility();
  }

  function setListenPaused(on) {
    listenPaused = !!on;
    if (listenScanRunning && continuousBmScanOn()) return;
    var passTxt = listenScanPassText();
    var listenLabel = listenPaused
      ? (passTxt ? ("Continue scan · pass " + passTxt) : "Continue scan bookmarks")
      : (listenScanRunning
        ? (passTxt ? ("Scanning bookmarks · " + passTxt) : "Scanning bookmarks")
        : "Scan bookmarks");
    var listenTitle = listenPaused
      ? "Leave this busy channel and continue hopping through bookmarks."
      : (listenScanRunning
        ? (passTxt ? ("Bookmark scan pass " + passTxt + " — click Stop to end.") : "Bookmark scan is running — click Stop to end.")
        : listenScanIdleTitle());
    var btn = $("bs-listen-top");
    if (!btn) return;
    btn.textContent = listenLabel;
    btn.title = listenTitle;
    btn.disabled = listenScanRunning && !listenPaused;
    btn.classList.toggle("bs-on", listenPaused || listenScanRunning);
    btn.classList.toggle("bs-running", listenScanRunning && !listenPaused);
    applyToolbarVisibility();
  }

  function resumeListenScan() {
    listenCmd = "continue";
  }

  function sameListenFreq(freq) {
    return !!(listenFreq && freq && Math.abs(Number(freq) - listenFreq) < 4000);
  }

  function alwaysSkipAndContinue(freq) {
    freq = Number(freq) || currentTuneHz();
    if (freq) ignoreFreq(freq);
    listenCmd = "skip";
    if (listenPaused) resumeListenScan();
    if (freq) {
      setStatus("Always skip " + fmtMhz(freq) + (listenPaused ? " — continuing scan." : " — next scan will not land here."));
    }
  }

  function continueIfPausedOn(freq) {
    if (!sameListenFreq(freq)) return false;
    listenCmd = "skip";
    if (listenPaused) resumeListenScan();
    return listenPaused;
  }

  function ownerOverrideAllowed() {
    return TOOLBOX_ALLOW_OWNER_OVERRIDE !== false;
  }

  /* Stock OpenWebRX General setting toolbox_public_mode (via WS config). null=unknown. */
  var serverPublicMode = null;
  /* OpenWebRX /settings admin session. null=unknown; Settings pane stays locked until proven admin. */
  var owrxAdmin = null;
  var owrxAdminProbeAt = 0;

  function isOwrxAdmin() {
    return owrxAdmin === true;
  }

  function refreshOwrxAdmin(done) {
    owrxAdminProbeAt = Date.now();
    fetch("/settings", { credentials: "same-origin", cache: "no-store", redirect: "manual" })
      .then(function (res) {
        var ok = res.status === 200 && res.type !== "opaqueredirect";
        owrxAdmin = ok;
        try { syncSettingsAdminGate(); } catch (eG) {}
        try {
          exGain.stale = true;
          exploreGainMaybeLoad();
        } catch (eGainAdm) {}
        if (done) done(ok);
      })
      .catch(function () {
        owrxAdmin = false;
        try { syncSettingsAdminGate(); } catch (eG2) {}
        try {
          exGain.stale = true;
          exploreGainMaybeLoad();
        } catch (eGainAdm2) {}
        if (done) done(false);
      });
  }

  /** Settings tab is always visible; non-admins see how to unlock, not a blank missing tab. */
  function syncSettingsAdminGate() {
    var gate = $("bs-settings-admin-gate");
    var stack = $("bs-settings-stack");
    var body = $("bs-settings");
    var admin = isOwrxAdmin();
    var probing = owrxAdmin === null;
    if (gate) {
      gate.hidden = !!admin;
      gate.classList.toggle("bs-settings-admin-gate-wait", probing && !admin);
      var title = $("bs-settings-admin-gate-title");
      var detail = $("bs-settings-admin-gate-detail");
      if (title) {
        title.textContent = probing
          ? "Checking OpenWebRX admin session…"
          : "Settings needs an OpenWebRX admin login";
      }
      if (detail) {
        detail.innerHTML = probing
          ? "One moment — confirming whether this browser is logged into OpenWebRX Settings."
          : "Log into OpenWebRX <b>Settings</b> (admin password) in <b>this</b> browser, then return to the receiver and hard-refresh (<b>Ctrl+Shift+R</b>). " +
            "Guests can use Help and the other tabs; Toolbox Settings stays locked so visitors cannot change shared options.";
      }
    }
    if (stack) stack.hidden = !admin;
    if (body) {
      body.classList.toggle("bs-settings-locked", !admin);
      Array.prototype.forEach.call(body.querySelectorAll(".bs-settings-admin-only"), function (el) {
        el.hidden = !admin;
      });
    }
    try {
      var tabBtn = document.querySelector('#bs-tabs .bs-tab[data-tab="settings"]');
      if (tabBtn) {
        tabBtn.title = admin
          ? (TAB_HOVER_TIPS.settings || "Settings")
          : "Settings — log into OpenWebRX admin Settings to unlock";
        tabBtn.classList.toggle("bs-tab-locked", !admin);
      }
    } catch (eTab) {}
  }

  function applyServerPublicMode(val) {
    if (typeof val === "undefined") return;
    serverPublicMode = !!val;
    try {
      if (S && S.extras) S.extras.publicMode = !!val;
    } catch (e) {}
    try {
      if (typeof applyPublicModeExtra === "function") applyPublicModeExtra();
      if (typeof applyHiddenTabs === "function") applyHiddenTabs();
      if (typeof gatePublicActions === "function") gatePublicActions();
      if (typeof applyPublicPolicyUi === "function") applyPublicPolicyUi();
    } catch (e2) {}
  }

  function hookToolboxServerConfig() {
    if (window._toolbox_cfg_hooked) return;
    window._toolbox_cfg_hooked = true;
    function ingestFromEvent(ev) {
      try {
        if (!ev || typeof ev.data !== "string" || ev.data.charAt(0) !== "{") return;
        var msg = JSON.parse(ev.data);
        if (!msg || msg.type !== "config") return;
        var cfg = msg.value || msg.params || {};
        if (Object.prototype.hasOwnProperty.call(cfg, "toolbox_public_mode")) {
          applyServerPublicMode(cfg.toolbox_public_mode);
        }
      } catch (e) {}
    }
    function wrapOnWsRecv() {
      if (typeof window.on_ws_recv !== "function" || window._tb_on_ws_wrap) return;
      window._tb_on_ws_wrap = true;
      var prevRecv = window.on_ws_recv;
      window.on_ws_recv = function (ev) {
        ingestFromEvent(ev);
        return prevRecv.apply(this, arguments);
      };
    }
    function wrapSock(sock) {
      if (!sock || sock._tb_pub_wrap) return;
      sock._tb_pub_wrap = true;
      var prev = sock.onmessage;
      sock.onmessage = function (ev) {
        ingestFromEvent(ev);
        if (typeof prev === "function") return prev.apply(this, arguments);
      };
    }
    wrapOnWsRecv();
    wrapSock(window.ws);
    var n = 0;
    var t = setInterval(function () {
      wrapOnWsRecv();
      wrapSock(window.ws);
      if (++n > 80) clearInterval(t);
    }, 250);
  }

  function ownerHopsOn() {
    return ownerOverrideAllowed() && !!S.ownRadio;
  }

  function profileGapMs() {
    return ownerHopsOn() ? PROFILE_GAP_OWN_MS : PROFILE_GAP_MS;
  }

  function freqInVisibleRange(freq, center, bw) {
    center = center || window.center_freq;
    bw = bw || window.bandwidth;
    if (!freq || !center || !bw) return false;
    var pad = bw * EDGE_FRAC;
    return freq >= (center - bw / 2 + pad) && freq <= (center + bw / 2 - pad);
  }

  function currentProfileValue() {
    var sel = $("openwebrx-sdr-profiles-listbox");
    return (sel && sel.value) ? sel.value : "";
  }

  async function waitProfileGap(label) {
    if (!lastProfileSwitchAt) return;
    var waitMore = profileGapMs() - (Date.now() - lastProfileSwitchAt);
    if (waitMore > 0) {
      var why = ownerHopsOn() ? "fast hops (own radio)" : "anti-ban, profile change";
      setStatus((label || "waiting") + " " + Math.ceil(waitMore / 1000) + "s (" + why + ")");
      await sleep(waitMore);
    }
  }

  function clientCount() {
    var el = $("openwebrx-bar-clients");
    if (el) {
      var m = String(el.textContent || "").match(/(\d+)/);
      if (m) return parseInt(m[1], 10);
    }
    try {
      if (window.jQuery) {
        var $el = jQuery("#openwebrx-bar-clients");
        var pb = $el.data("ui-progressbar") || $el.data("progressbar");
        if (pb && typeof pb.clients === "number") return pb.clients;
      }
    } catch (e) {}
    return 1;
  }

  function courtesyBlocked(action) {
    if (!S.aloneOnly) return false;
    var n = clientCount();
    if (n <= 1) return false;
    var msg = "Other listeners online (" + n + ") — untick Only if alone (Range / Bands / Settings).";
    setStatus(msg);
    toast(msg);
    return true;
  }

  function notify(msg) {
    notifyNewPeak(msg, null);
  }

  function beep() {
    try {
      var AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      var ctx = new AC();
      var osc = ctx.createOscillator();
      var g = ctx.createGain();
      osc.frequency.value = 880;
      osc.connect(g);
      g.connect(ctx.destination);
      g.gain.value = 0.06;
      osc.start();
      osc.stop(ctx.currentTime + 0.12);
      setTimeout(function () { try { ctx.close(); } catch (e) {} }, 400);
    } catch (e2) {}
  }

  function askNotifyPerm() {
    try {
      if ((S.notifyNew || S.notifyScanDone) && window.Notification && Notification.permission === "default") {
        Notification.requestPermission();
      }
    } catch (e) {}
  }

  function getHopSettleMs() {
    var v = Number(S.profileSettleMs);
    return (isFinite(v) && v >= 100) ? Math.min(5000, v) : HOP_SETTLE_MS;
  }

  function maxAudioClipsCap() {
    var n = Number(S.maxAudioClips);
    return (isFinite(n) && n >= 5) ? Math.min(200, Math.round(n)) : 40;
  }

  function getMagicKey() {
    try {
      if (window.UI && typeof UI.getDemodulatorPanel === "function") {
        var dp = UI.getDemodulatorPanel();
        if (dp && typeof dp.getMagicKey === "function") {
          var k = dp.getMagicKey();
          if (k) return k;
        }
      }
    } catch (e) {}
    try {
      var m = (window.location.hash || "").match(/(?:^|[&#])key=([^&]*)/);
      if (m && m[1]) return decodeURIComponent(m[1]);
    } catch (e2) {}
    return Plugins.toolbox.magic_key || "";
  }

  function pluginSetFrequency(freq) {
    freq = Math.round(freq);
    if (!isFinite(freq) || freq < 0) return;
    bsInternalTune = true;
    try {
      var sock = window.ws;
      var key = getMagicKey();
      if (sock && sock.readyState === 1 && key) {
        sock.send(JSON.stringify({
          type: "setfrequency",
          params: { frequency: freq, key: key }
        }));
      }
      if (window.UI && typeof UI.setFrequency === "function") {
        UI.setFrequency(freq);
      }
      if (window.UI && typeof UI.toggleScanner === "function") {
        UI.toggleScanner(false);
      }
    } finally {
      setTimeout(function () { bsInternalTune = false; }, 0);
    }
  }

  function hookTuneApi() {
    if (window._bs_tune_hooked || !window.UI || typeof UI.setFrequency !== "function") return;
    var orig = UI.setFrequency.bind(UI);
    /* Forward all args — snap=false must reach OpenWebRX (Band Tune ± / exact dial). */
    UI.setFrequency = function (freq, snap) {
      if (running && S.pauseOnManualTune && !bsInternalTune) {
        stopFlag = true;
        setStatus("Paused — you tuned manually.");
      }
      if (!bsInternalTune && !running && !listenScanRunning) lastManualTuneAt = Date.now();
      return orig(freq, snap);
    };
    window._bs_tune_hooked = true;
  }

  function parseTimeHm(s) {
    var m = String(s || "").trim().match(/^(\d{1,2}):(\d{2})$/);
    if (!m) return null;
    var h = Number(m[1]);
    var min = Number(m[2]);
    if (!isFinite(h) || !isFinite(min) || h < 0 || h > 23 || min < 0 || min > 59) return null;
    return h * 60 + min;
  }

  function inQuietHours() {
    var sm = parseTimeHm(S.quietStart);
    var em = parseTimeHm(S.quietEnd);
    if (sm === null || em === null) return false;
    var now = new Date();
    var mins = now.getHours() * 60 + now.getMinutes();
    if (sm <= em) return mins >= sm && mins < em;
    return mins >= sm || mins < em;
  }

  function receiverRecentlyActive() {
    if (!S.schedIdleOnly) return false;
    return lastManualTuneAt && (Date.now() - lastManualTuneAt) < SCHED_IDLE_MS;
  }

  function isAlertFreq(freq) {
    var list = parseHzList(S.alertFreqs);
    if (!list.length) return false;
    var offset = Math.max(1, Number(S.alertOffsetKhz) || 25) * 1000;
    for (var i = 0; i < list.length; i++) {
      if (Math.abs(list[i] - freq) <= offset) return true;
    }
    return false;
  }

  function fireWebhook(hit) {
    var url = String(S.webhookUrl || "").trim();
    if (!url || !hit) return;
    var payload = {
      freq: hit.freq,
      name: hit.name || existingName(hit.freq) || "",
      db: hit.maxDb || hit.lastDb || 0,
      band: hit.label || hit.pid || ""
    };
    try {
      fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
        mode: "cors",
        keepalive: true
      }).catch(function () {});
    } catch (e) {}
  }

  function notifyScanComplete(msg) {
    if (!S.notifyScanDone || !msg) return;
    try {
      if (window.Plugins && Plugins.notify && typeof Plugins.notify.show === "function") {
        Plugins.notify.show(msg);
      }
    } catch (e) {}
    try {
      if (window.Notification && Notification.permission === "granted") {
        new Notification("Toolbox", { body: msg, silent: true });
      }
    } catch (e2) {}
    setStatus(msg);
  }

  function notifyNewPeak(msg, hit) {
    if (!S.notifyNew || !msg) return;
    var alertHit = hit && isAlertFreq(hit.freq);
    if (S.soundNewPeak !== false || alertHit) beep();
    if (alertHit && S.notifyNew) {
      msg = "Alert " + msg;
      if (S.soundNewPeak !== false) beep();
    }
    try {
      if (window.Plugins && Plugins.notify && typeof Plugins.notify.show === "function") {
        Plugins.notify.show(msg);
      }
    } catch (e) {}
    try {
      if (window.Notification && Notification.permission === "granted") {
        new Notification("Toolbox", { body: msg, silent: true });
      }
    } catch (e2) {}
    setStatus(msg);
    if (hit) fireWebhook(hit);
  }

  function trimPeaksIfNeeded() {
    var max = Number(S.maxPeaks);
    if (!isFinite(max) || max < 1 || hits.length <= max) return;
    hits.sort(function (a, b) { return (a.last || 0) - (b.last || 0); });
    while (hits.length > max) hits.shift();
  }

  function resolveOpenTab() {
    var tab = "explore";
    if (S.defaultTab && S.defaultTab !== "last" && TAB_IDS.indexOf(S.defaultTab) >= 0) {
      tab = S.defaultTab;
    } else {
      try {
        var saved = null;
        if (S.rememberTab !== false) saved = window.localStorage.getItem(SS_TAB);
        if (!saved) saved = sessionStorage.getItem(SS_TAB);
        if (saved && TAB_IDS.indexOf(saved) >= 0) tab = saved;
      } catch (e) {}
    }
    if (isTabHidden(tab)) return firstVisibleTab();
    return tab;
  }

  function isTabHidden(id) {
    if (!id) return false;
    /* Settings stays in the header for everyone; non-admins see an unlock hint inside. */
    if (id === "settings") {
      var roleS = uxFeelActiveRole();
      if (roleS && UX_ROLE_TABS[roleS]) {
        return UX_ROLE_TABS[roleS].indexOf(id) < 0;
      }
      return false;
    }
    if (!publicAllowsTab(id)) return true;
    var role = uxFeelActiveRole();
    if (role && UX_ROLE_TABS[role]) {
      return UX_ROLE_TABS[role].indexOf(id) < 0;
    }
    if (uxFeelOn("leanChrome") && UX_LEAN_HIDE_TABS.indexOf(id) >= 0) return true;
    if (uxFeelOn("simpleMode") && UX_LEAN_HIDE_TABS.indexOf(id) >= 0) return true;
    var list = S.hiddenTabs;
    return Array.isArray(list) && list.indexOf(id) >= 0;
  }

  function firstVisibleTab() {
    var i;
    for (i = 0; i < TAB_IDS.length; i++) {
      if (!isTabHidden(TAB_IDS[i])) return TAB_IDS[i];
    }
    return "help";
  }

  function fillVisibleTabsForm() {
    var box = $("bs-visible-tabs");
    if (!box) return;
    var pub = isPublicReceiver();
    var list = S.hiddenTabs;
    Array.prototype.forEach.call(box.querySelectorAll("input.bs-tab-vis[data-tab]"), function (inp) {
      var id = inp.getAttribute("data-tab");
      /* Personal preference only — public allowlist has its own Tabs box. */
      var prefOn = id === "settings" || !(Array.isArray(list) && list.indexOf(id) >= 0);
      inp.checked = prefOn;
      /* Settings tab itself is admin-gated; don't offer guests a visible-tabs tick for it. */
      inp.disabled = id === "settings" || (pub && !canEditPublicPolicy());
      var lab = inp.closest && inp.closest("label");
      if (lab) {
        lab.classList.toggle("bs-tab-vis-off", !prefOn && id !== "settings");
        if (id === "settings") lab.hidden = false;
      }
    });
  }

  function readHiddenTabsFromForm() {
    var box = $("bs-visible-tabs");
    if (!box) return;
    var hidden = [];
    Array.prototype.forEach.call(box.querySelectorAll("input.bs-tab-vis[data-tab]"), function (inp) {
      var id = inp.getAttribute("data-tab");
      if (id === "settings") return;
      if (!inp.checked) hidden.push(id);
    });
    S.hiddenTabs = hidden;
  }

  var TAB_HOVER_TIPS = {
    explore: "Explore — tune and hop between SDR profiles on the waterfall.",
    bands: "Bands — tick profiles and run Scan bands / Fresh scan.",
    range: "Range — scan a custom start–end MHz span.",
    analyzer: "Analyzer — experimental live spectrum view (optional tab).",
    peaks: "Peaks — ranked list of signals found by scans.",
    bookmarks: "Bookmarks — local and loaded frequencies; scan bookmarks.",
    audio: "Audio — record clips, play, and export WAV.",
    skip: "Skip — frequencies always ignored during scans.",
    settings: "Settings — panel prefs (OpenWebRX admin login required to edit).",
    help: "Help — how to install and use Toolbox."
  };

  function syncTabHoverTips() {
    var bar = $("bs-tabs");
    if (bar) {
      Array.prototype.forEach.call(bar.querySelectorAll(".bs-tab[data-tab]"), function (btn) {
        var id = btn.getAttribute("data-tab");
        var tip = TAB_HOVER_TIPS[id] || (id ? (id.charAt(0).toUpperCase() + id.slice(1)) : "Tab");
        btn.setAttribute("data-tab-base-title", tip);
        if (id === "settings") {
          btn.setAttribute("data-tip", tip);
        } else {
          btn.setAttribute("data-tip", tip + "\nRight-click colours this tab · Shift+right-click closes it.");
        }
        btn.removeAttribute("title");
      });
    }
    var helpTog = $("bs-help-tog");
    if (helpTog) {
      helpTog.setAttribute("data-tip", TAB_HOVER_TIPS.help);
      helpTog.removeAttribute("title");
    }
  }

  function applyHiddenTabs() {
    var bar = $("bs-tabs");
    if (bar) {
      Array.prototype.forEach.call(bar.querySelectorAll(".bs-tab"), function (btn) {
        var id = btn.getAttribute("data-tab");
        var hide = isTabHidden(id);
        /* Unticked tabs leave the header; Settings → Visible tabs (or Show all) restores. */
        btn.hidden = hide;
        btn.classList.remove("bs-tab-dim");
        btn.removeAttribute("aria-disabled");
        btn.removeAttribute("tabIndex");
        if (hide) btn.classList.remove("bs-tab-on");
      });
    }
    var helpTog = $("bs-help-tog");
    if (helpTog) {
      var helpHide = isTabHidden("help");
      helpTog.hidden = helpHide;
      if (helpHide) helpTog.classList.remove("bs-on");
      helpTog.setAttribute("aria-pressed", helpTog.classList.contains("bs-on") ? "true" : "false");
    }
    syncTabHoverTips();
    fillVisibleTabsForm();
    try { syncSettingsAdminGate(); } catch (eGate) {}
    var cur = currentPanelTab();
    if (!cur || isTabHidden(cur)) switchTab(firstVisibleTab(), true);
  }

  function canEditHiddenTabs() {
    return !(isPublicReceiver() && !canEditPublicPolicy());
  }

  /** Hide or restore a main header tab (Visible tabs preference). Settings cannot close. */
  function setMainTabHidden(id, hide) {
    if (!id || id === "settings") return false;
    if (!canEditHiddenTabs()) return false;
    if (!Array.isArray(S.hiddenTabs)) S.hiddenTabs = [];
    var i = S.hiddenTabs.indexOf(id);
    if (hide) {
      if (i < 0) S.hiddenTabs.push(id);
    } else if (i >= 0) {
      S.hiddenTabs.splice(i, 1);
    }
    saveSettings();
    applyHiddenTabs();
    return true;
  }

  function fillUxFeelForm() {
    if (!S.uxFeel) S.uxFeel = uxFeelDefaults();
    var map = {
      "bs-ux-role-presets": "rolePresets",
      "bs-ux-lean-chrome": "leanChrome",
      "bs-ux-simple-mode": "simpleMode",
      "bs-ux-quieter": "quieterSurfaces",
      "bs-ux-task-entry": "taskEntry",
      "bs-ux-extras-job": "extrasByJob"
    };
    Object.keys(map).forEach(function (id) {
      if ($(id)) $(id).checked = !!S.uxFeel[map[id]];
    });
  }

  function readUxFeelFromForm() {
    if (!S.uxFeel) S.uxFeel = uxFeelDefaults();
    var map = {
      "bs-ux-role-presets": "rolePresets",
      "bs-ux-lean-chrome": "leanChrome",
      "bs-ux-simple-mode": "simpleMode",
      "bs-ux-quieter": "quieterSurfaces",
      "bs-ux-task-entry": "taskEntry",
      "bs-ux-extras-job": "extrasByJob"
    };
    Object.keys(map).forEach(function (id) {
      if ($(id)) S.uxFeel[map[id]] = !!$(id).checked;
    });
    if (!S.uxFeel.rolePresets) S.uxFeel.activeRole = "";
  }

  function rebuildExtrasGridForUx() {
    var host = $("bs-extras");
    if (!host) return;
    var byJob = uxFeelOn("extrasByJob");
    var want = byJob ? "job" : "tab";
    if (host.getAttribute("data-bs-ux-group") === want) {
      if (typeof fillExtrasForm === "function") fillExtrasForm();
      return;
    }
    host.setAttribute("data-bs-ux-group", want);
    host.innerHTML = extrasGridInnerHtml(byJob);
    if (typeof fillExtrasForm === "function") fillExtrasForm();
    Array.prototype.forEach.call(host.querySelectorAll("input.bs-extra-tog"), function (inp) {
      inp.onchange = function () {
        if (typeof readForm === "function") readForm();
      };
    });
    if (typeof packExtrasMasonry === "function") packExtrasMasonry(true);
  }

  function applyUxQuieterSurfaces(on) {
    UX_QUIET_BOX_IDS.forEach(function (id) {
      var box = $(id);
      if (!box) return;
      var btn = box.querySelector(".bs-ex-box-toggle, .bs-set-box-toggle");
      if (on) {
        if (!box.hasAttribute("data-bs-ux-prev")) {
          box.setAttribute("data-bs-ux-prev", box.classList.contains("bs-collapsed") ? "0" : "1");
        }
        box.classList.add("bs-collapsed");
        if (btn) btn.setAttribute("aria-expanded", "false");
      } else if (box.hasAttribute("data-bs-ux-prev")) {
        var prev = box.getAttribute("data-bs-ux-prev");
        box.classList.toggle("bs-collapsed", prev === "0");
        if (btn) btn.setAttribute("aria-expanded", prev === "0" ? "false" : "true");
        box.removeAttribute("data-bs-ux-prev");
      }
    });
    try {
      packExploreMasonry();
      fitExplorePack();
    } catch (ePk) {}
  }

  function applyUxFeelStrips() {
    var roles = $("bs-ux-roles");
    var tasks = $("bs-ux-tasks");
    var panel = $("bs-panel");
    if (roles) {
      roles.hidden = !uxFeelOn("rolePresets");
      Array.prototype.forEach.call(roles.querySelectorAll("[data-ux-role]"), function (btn) {
        var id = btn.getAttribute("data-ux-role") || "";
        btn.classList.toggle("bs-ux-on", uxFeelActiveRole() === id || (id === "" && !uxFeelActiveRole()));
      });
    }
    if (tasks) tasks.hidden = !uxFeelOn("taskEntry");
    if (panel) {
      var role = uxFeelActiveRole();
      panel.classList.toggle("bs-ux-simple", uxFeelOn("simpleMode") || role === "listen");
      panel.classList.toggle("bs-ux-lean", uxFeelOn("leanChrome") || (!!role && role !== "power"));
      panel.classList.toggle("bs-ux-quiet", uxFeelOn("quieterSurfaces") || role === "listen");
      panel.classList.toggle("bs-ux-tasks-on", uxFeelOn("taskEntry"));
      panel.classList.toggle("bs-ux-roles-on", uxFeelOn("rolePresets"));
    }
  }

  function applyUxFeel() {
    if (!S.uxFeel) S.uxFeel = uxFeelDefaults();
    applyUxFeelStrips();
    var quiet = uxFeelOn("quieterSurfaces") || uxFeelActiveRole() === "listen";
    applyUxQuieterSurfaces(quiet);
    rebuildExtrasGridForUx();
    applyHiddenTabs();
    applyExtrasUi();
    fillUxFeelForm();
  }

  function setUxFeelRole(role) {
    if (!S.uxFeel) S.uxFeel = uxFeelDefaults();
    if (!uxFeelOn("rolePresets")) {
      setStatus("Turn on Role presets under Settings → UX feel first.");
      return;
    }
    if (role && !UX_ROLE_TABS.hasOwnProperty(role)) role = "";
    S.uxFeel.activeRole = role || "";
    saveSettings();
    applyUxFeel();
    setStatus(role
      ? ("UX role: " + (UX_ROLE_LABELS[role] || role) + " (soft overlay — your Visible tabs / Extras ticks unchanged).")
      : "UX role cleared — back to your saved Visible tabs.");
  }

  function runUxTask(task) {
    if (!uxFeelOn("taskEntry")) return;
    if (task === "tune") {
      switchTab("explore", true);
      setStatus("Task: Tune around — Explore LCD / Go.");
    } else if (task === "scan") {
      switchTab("bands", true);
      setStatus("Task: Scan bands — tick bands, then Scan bands.");
    } else if (task === "peaks") {
      switchTab("peaks", true);
      setStatus("Task: Review peaks.");
    } else if (task === "bookmarks") {
      switchTab("bookmarks", true);
      setStatus("Task: Scan / manage bookmarks.");
    }
  }

  function closeTabContextMenu() {
    var menu = $("bs-tab-menu");
    if (menu) menu.hidden = true;
  }

  function ensureTabContextMenu() {
    var menu = $("bs-tab-menu");
    /* Drop menus that still offer Colour… — right-click opens the picker directly. */
    if (menu && menu.querySelector('[data-tab-act="colour"]')) {
      try { menu.parentNode.removeChild(menu); } catch (eOld) {}
      menu = null;
    }
    if (menu) return menu;
    menu = document.createElement("div");
    menu.id = "bs-tab-menu";
    menu.hidden = true;
    menu.setAttribute("role", "menu");
    menu.innerHTML =
      '<div class="bs-tab-menu-title" id="bs-tab-menu-title">Tab</div>' +
      '<button type="button" class="bs-tab-menu-item" role="menuitem" data-tab-act="close" title="Hide this tab from the header. Restore under Settings → Visible tabs.">Close tab</button>' +
      '<p class="bs-tab-menu-hint" id="bs-tab-menu-hint">Shift+right-click a tab for this menu. Restore under Settings → Visible tabs.</p>';
    document.body.appendChild(menu);
    menu.addEventListener("click", function (ev) {
      ev.stopPropagation();
      var t = ev.target && ev.target.closest && ev.target.closest("[data-tab-act]");
      if (!t || t.disabled) return;
      var act = t.getAttribute("data-tab-act");
      var id = menu.getAttribute("data-tab-id");
      closeTabContextMenu();
      if (act === "close" && id) {
        if (setMainTabHidden(id, true)) {
          setStatus("Tab closed. Restore under Settings → Visible tabs.");
        }
      }
    });
    if (!ensureTabContextMenu._docClose) {
      ensureTabContextMenu._docClose = true;
      document.addEventListener("click", function () { closeTabContextMenu(); });
      document.addEventListener("keydown", function (ev) {
        if (ev.key === "Escape") closeTabContextMenu();
      });
    }
    return menu;
  }

  function openTabContextMenu(ev, tabId) {
    var menu = ensureTabContextMenu();
    if (!menu || !tabId) return;
    var labs = {
      explore: "Explore", bands: "Bands", range: "Range", analyzer: "Analyzer",
      peaks: "Peaks", bookmarks: "Bookmarks", audio: "Audio", skip: "Skip",
      settings: "Settings", help: "Help"
    };
    var title = menu.querySelector("#bs-tab-menu-title");
    if (title) title.textContent = labs[tabId] || tabId;
    var closeBtn = menu.querySelector('[data-tab-act="close"]');
    var hint = menu.querySelector("#bs-tab-menu-hint");
    var canClose = tabId !== "settings" && canEditHiddenTabs();
    if (closeBtn) {
      closeBtn.disabled = !canClose;
      closeBtn.classList.toggle("bs-tab-menu-disabled", !canClose);
      if (tabId === "settings") closeBtn.title = "Settings cannot be closed.";
      else if (!canEditHiddenTabs()) closeBtn.title = "Visible tabs locked on this public receiver.";
      else closeBtn.title = "Hide this tab from the header. Restore under Settings → Visible tabs.";
    }
    if (hint) {
      hint.textContent = tabId === "settings"
        ? "Settings always stays available."
        : (!canEditHiddenTabs()
          ? "Visible tabs are locked on this public receiver."
          : "Right-click colours the tab. Shift+right-click opens Close tab.");
    }
    menu.setAttribute("data-tab-id", tabId);
    menu.hidden = false;
    menu.style.left = "0px";
    menu.style.top = "0px";
    var w = menu.offsetWidth || 180;
    var h = menu.offsetHeight || 80;
    var left = Math.min(ev.clientX, window.innerWidth - w - 8);
    var top = Math.min(ev.clientY, window.innerHeight - h - 8);
    menu.style.left = Math.max(8, left) + "px";
    menu.style.top = Math.max(8, top) + "px";
  }

  function currentPanelTab() {
    var helpOn = panelQs("#bs-tab-help.bs-tab-on") || panelQs("#bs-help-tog.bs-on");
    if (helpOn) return "help";
    var on = panelQs("#bs-tabs .bs-tab.bs-tab-on");
    return (on && on.getAttribute("data-tab")) || "";
  }

  function setElHidden(el, hide) {
    if (!el) return;
    el.hidden = !!hide;
  }

  function applyToolbarVisibility() {
    var tb = $("bs-toolbar");
    var p = $("bs-panel");
    var hidePref = !!S.hideToolbar;
    var tab = currentPanelTab();
    var survey = !!(running || surveyRunning);
    var listen = !!listenScanRunning;
    var busy = survey || listen;
    if (p) p.classList.toggle("bs-hide-toolbar", hidePref);

    var showBand = !hidePref && tab === "bands";
    var showBm = !hidePref && (tab === "bookmarks" || listen);
    var showBusyStop = !hidePref && busy && !showBand && !showBm;
    var showStatus = !hidePref && (showBand || showBm || showBusyStop || busy);
    var showAny = showBand || showBm || showBusyStop || showStatus;

    setElHidden($("bs-tb-bands-note"), !showBand);
    setElHidden($("bs-tb-bands-box"), !(showBand || showBusyStop));
    setElHidden($("bs-tb-band-row"), !(showBand || showBusyStop));
    setElHidden($("bs-bands-scan-opts"), !showBand);
    setElHidden($("bs-start"), !showBand);
    setElHidden($("bs-fresh"), !showBand);
    setElHidden($("bs-jump"), !showBand);
    setElHidden($("bs-selcount"), !showBand);
    setElHidden($("bs-stop"), !(showBand || showBusyStop));
    setElHidden($("bs-tb-bm-row"), !showBm);
    setElHidden($("bs-status"), !showStatus);
    setElHidden($("bs-tb-progress"), !showStatus);
    if (tb) {
      tb.hidden = hidePref || !showAny;
      tb.classList.toggle("bs-tb-bands-on", !!showBand);
      tb.classList.toggle("bs-tb-busy-on", !!showBusyStop && !showBand);
    }
    if ($("bs-hide-toolbar")) $("bs-hide-toolbar").checked = hidePref;
  }

  /** Tell owrx_hush / owrx_quiet whether to mute when this tab is backgrounded. Default on. */
  function applyMuteOnTabHidePref() {
    var on = S.muteOnTabHide !== false;
    try { Plugins.toolbox.muteOnTabHide = on; } catch (eP) {}
    try {
      window.localStorage.setItem("owrx_toolbox_mute_on_tab_hide", on ? "1" : "0");
    } catch (eLs) {}
    if ($("bs-mute-on-tab")) $("bs-mute-on-tab").checked = on;
    try { window.postMessage({ type: "owrx-mute-on-tab-pref", enabled: on }, "*"); } catch (eMsg) {}
    if (!on) {
      try { window.postMessage({ type: "owrx-unmute" }, "*"); } catch (eU) {}
    }
  }

  function applyStockReceiverVisibility() {
    var hide = !!S.hideStockReceiver;
    try {
      document.documentElement.classList.toggle("bs-hide-stock-rx", hide);
      document.body.classList.toggle("bs-hide-stock-rx", hide);
    } catch (e) {}
    if ($("bs-hide-stock-rx")) $("bs-hide-stock-rx").checked = hide;
    var el = $("openwebrx-panel-receiver");
    if (hide) {
      /* CSS class hides the panel. Do NOT set display:none / rotateX inline —
         owrx_hush / owrx_quiet treat that as a folded panel and mute audio.
         Toolbox hide means “use Explore”, not “stop listening”. */
      try {
        if (el) {
          /* Clear older Toolbox inline collapse leftovers. */
          if (el.style.display === "none") el.style.display = "";
          var tr = (el.style.transform || "").toLowerCase();
          if (tr.indexOf("rotatex(90") !== -1 || tr.indexOf("rotatex(-90") !== -1) {
            el.style.transform = "";
          }
        }
      } catch (eClr) {}
    } else {
      /* Un-hiding: drop any leftover inline hide so native toggle can open it. */
      try {
        if (el) {
          if (el.style.display === "none") el.style.display = "";
          var tr2 = (el.style.transform || "").toLowerCase();
          if (tr2.indexOf("rotatex(90") !== -1 || tr2.indexOf("rotatex(-90") !== -1) {
            el.style.transform = "";
          }
        }
      } catch (eShow) {}
    }
    /* Always tell hush/quiet to keep audio when Toolbox is the UI (panel open or closed). */
    try { window.postMessage({ type: "owrx-unmute" }, "*"); } catch (eMsg) {}
    try {
      if (window.UI && typeof UI.setVolume === "function" &&
          typeof UI.volume === "number" && UI.volume >= 0 &&
          !(UI.volumeMuted >= 0)) {
        UI.setVolume(UI.volume);
      }
    } catch (eVol) {}
  }

  /** Native top-bar Receiver must always be able to open the stock panel.
      If Toolbox "Hide stock receiver" is on, clear it on Receiver click. */
  function bindStockReceiverOpenUnhide() {
    var btn = document.querySelector('[data-toggle-panel="openwebrx-panel-receiver"]');
    if (!btn || btn.getAttribute("data-bs-rx-unhide") === "1") return;
    btn.setAttribute("data-bs-rx-unhide", "1");
    btn.addEventListener("click", function () {
      var hidden = !!S.hideStockReceiver;
      try {
        hidden = hidden
          || document.body.classList.contains("bs-hide-stock-rx")
          || document.documentElement.classList.contains("bs-hide-stock-rx");
      } catch (eCls) {}
      if (!hidden) return;
      S.hideStockReceiver = false;
      applyStockReceiverVisibility();
      try { saveSettings(); } catch (eSave) {}
      try { setStatus("Stock receiver panel shown again (Hide stock receiver was on)."); } catch (eSt) {}
    }, true);
  }

  function applyUiTextSize() {
    var p = $("bs-panel");
    if (!p) return;
    p.classList.remove("bs-text-sm", "bs-text-lg");
    var sz = S.uiTextSize || "default";
    if (sz === "small") p.classList.add("bs-text-sm");
    else if (sz === "large") p.classList.add("bs-text-lg");
  }

  function normalizeChkStyle(v) {
    if (v === "switch") return v;
    return "tick";
  }

  function applyChkStyle() {
    var style = normalizeChkStyle(S.chkStyle);
    S.chkStyle = style;
    try {
      document.documentElement.setAttribute("data-bs-chk-style", style);
    } catch (eHtml) {}
    try {
      if (document.body) document.body.setAttribute("data-bs-chk-style", style);
    } catch (eBody) {}
    var p = $("bs-panel");
    if (p) p.setAttribute("data-bs-chk-style", style);
    if ($("bs-chk-style")) $("bs-chk-style").value = style;
  }

  function resetPanelLayoutDefaults() {
    if (restorePanelLayoutSnapshot()) {
      saveSettings();
      setStatus("Panel layout restored from last save.");
      return;
    }
    S.panelW = 0;
    S.panelH = 0;
    S.panelLeft = null;
    S.panelTop = null;
    panelLayoutUserSet = false;
    saveSettings();
    applyPanelLayout();
    setStatus("No saved layout — using waterfall default.");
  }

  function writePanelLayoutSnapshot() {
    try {
      var payload = {
        panelW: Math.round(Number(S.panelW) || 0),
        panelH: Math.round(Number(S.panelH) || 0),
        panelLeft: typeof S.panelLeft === "number" ? Math.round(S.panelLeft) : null,
        panelTop: typeof S.panelTop === "number" ? Math.round(S.panelTop) : null,
        panelSideDock: !!S.panelSideDock,
        panelSideDockSide: sideDockSide(),
        panelSidePct: sideDockPct()
      };
      window.localStorage.setItem(LS_PANEL_LAYOUT, JSON.stringify(payload));
    } catch (e) {}
  }

  function readPanelLayoutSnapshot() {
    try {
      var raw = window.localStorage.getItem(LS_PANEL_LAYOUT);
      if (!raw) return null;
      var o = JSON.parse(raw);
      if (!o) return null;
      if (typeof o.panelSideDock === "boolean") return o;
      if (!(Number(o.panelW) > 40) || !(Number(o.panelH) > 40)) return null;
      return o;
    } catch (e) {
      return null;
    }
  }

  function restorePanelLayoutSnapshot() {
    var o = readPanelLayoutSnapshot();
    if (!o) return false;
    if (typeof o.panelSideDock === "boolean") S.panelSideDock = !!o.panelSideDock;
    S.panelSideDockSide = "left";
    /* Do not clobber a newer in-memory side % from the live slider. */
    if (isFinite(Number(o.panelSidePct)) && !window._bs_side_pct_live) {
      S.panelSidePct = normalizePreferredSidePct(o.panelSidePct);
    }
    if (Number(o.panelW) > 40 && Number(o.panelH) > 40) {
      S.panelW = Number(o.panelW);
      S.panelH = Number(o.panelH);
      S.panelLeft = typeof o.panelLeft === "number" && isFinite(o.panelLeft) ? o.panelLeft : null;
      S.panelTop = typeof o.panelTop === "number" && isFinite(o.panelTop) ? o.panelTop : null;
      panelLayoutUserSet = true;
    }
    applyPanelLayout();
    return true;
  }

  /** Re-apply last placement (side dock or float) after load / OWRX redraw. */
  function restoreSavedPanelPlacement(opts) {
    opts = opts || {};
    try { restorePanelLayoutSnapshot(); } catch (e0) {}
    if (!S.panelSideDock) {
      applySideDockChrome(false);
      applyPanelLayout();
      return;
    }
    makePanel();
    var p = $("bs-panel");
    if (!p) return;
    if (window._bs_user_closed_panel) {
      applySideDockChrome(false);
      syncSideDockLayout();
      applyPanelLayout();
      return;
    }
    /* Do not force-open just because side dock is on — honor "Open panel on startup". */
    var wantVisible = !!opts.forceOpen || !p.hidden || !!window._bs_startup_open_done;
    if (!wantVisible) {
      applySideDockChrome(false);
      syncSideDockLayout();
      applyPanelLayout();
      return;
    }
    if (isPanelDetached()) dockPanel({ keepHidden: false });
    p.hidden = false;
    setPanelMinimized(false);
    syncSideDockLayout();
    applyPanelLayout();
    if (!opts.noRetry) {
      setTimeout(function () { restoreSavedPanelPlacement({ noRetry: true, forceOpen: true }); }, 200);
      setTimeout(function () { restoreSavedPanelPlacement({ noRetry: true, forceOpen: true }); }, 800);
    }
  }

  function savePanelLayoutManual() {
    savePanelLayout();
    writePanelLayoutSnapshot();
    setStatus("Panel layout saved — factory reset will restore this size and position.");
  }

  function applyWaterfallPanelDefault() {
    S.panelW = 0;
    S.panelH = 0;
    S.panelLeft = null;
    S.panelTop = null;
    panelLayoutUserSet = false;
    saveSettings();
    applyPanelLayout();
    setStatus("Panel layout set to waterfall default.");
  }

