    Object.keys(d).forEach(function (k) {
      if (k === "ignoredFreqs") out[k] = (S.ignoredFreqs || []).slice();
      else if (k === "hiddenTabs") out[k] = (S.hiddenTabs || []).slice();
      else out[k] = S[k];
    });
