    if ($("bs-ui-density")) $("bs-ui-density").value = S.uiDensity === "minimal" ? "minimal" : "full";
    if ($("bs-chk-style")) $("bs-chk-style").value = normalizeChkStyle(S.chkStyle);
    if ($("bs-autoopen")) $("bs-autoopen").checked = !!S.autoOpenPanel;
    if ($("bs-autostart-owrx")) $("bs-autostart-owrx").checked = wantAutoStartOwrx();
    if ($("bs-hide-toolbar")) $("bs-hide-toolbar").checked = !!S.hideToolbar;
    if ($("bs-hide-stock-rx")) $("bs-hide-stock-rx").checked = !!S.hideStockReceiver;
    if ($("bs-mute-on-tab")) $("bs-mute-on-tab").checked = S.muteOnTabHide !== false;
    if ($("bs-btn-colours-on")) $("bs-btn-colours-on").checked = !S.btnColoursOff;
    else if ($("bs-btn-colours-off")) $("bs-btn-colours-off").checked = !!S.btnColoursOff;
    if ($("bs-btn-shade-hint")) $("bs-btn-shade-hint").checked = S.btnShadeHoverHint !== false;
    if ($("bs-side-dock-set")) $("bs-side-dock-set").checked = !!S.panelSideDock;
