    if ($("bs-ex-offset")) $("bs-ex-offset").value = S.exploreOffsetKhz || 0;
    if ($("bs-ex-extra-zoom")) $("bs-ex-extra-zoom").checked = !!S.exploreExtraZoom;
    try { exploreApplyExtraZoom(!!S.exploreExtraZoom); } catch (eZoomFill) {}
