        var lab = host.closest(
          "label[data-tip], label[title], button[data-tip], button[title], summary[data-tip], summary[title], " +
          ".bs-extra-item[data-tip], .bs-extra-item[title], .bs-bd-edit-row[data-tip], .bs-bd-edit-row[title], " +
          ".bs-bm-row[data-tip], .bs-bm-row[title], select[data-tip], select[title], span[data-tip], span[title], " +
          ".bs-tab[data-tip], .bs-tab[title]"
        );
