  function bookmarkDisplayName(b) {
    var n = String((b && b.name) || "").trim();
    if (/^\[auto\]/i.test(n)) n = n.replace(/^\[auto\]\s*/i, "");
    return n || (b && b.frequency ? fmtMhz(b.frequency) : "");
  }

  function tuneBookmark(freq, mode) {
    freq = Number(freq);
    if (!freq) return;
    var hit = null;
    for (var i = 0; i < hits.length; i++) {
      if (Math.abs(hits[i].freq - freq) < 2500) {
        hit = hits[i];
        break;
      }
    }
    if (hit) {
      tuneTo(hit.freq, hit.pid);
      return;
    }
    pluginSetFrequency(freq);
    if (mode && window.UI && typeof UI.setModulation === "function") {
      try { UI.setModulation(mode, ""); } catch (e) {}
    }
  }

  function renderBookmarkPane() {
    var host = $("bs-bmlist");
    if (!host) {
      updateTabLabels();
      return;
    }
    var list = localBookmarkList();
    if (!list) list = [];
    var skipN = (S.ignoredFreqs || []).length;
    var bmRows = visibleBookmarkRows();
    var visibleLocal = bmRows.local.slice().sort(function (a, b) {
      return (a.frequency || 0) - (b.frequency || 0);
    });
    var visibleLoaded = bmRows.loaded.slice().sort(function (a, b) {
      return a.frequency - b.frequency;
    });
    var count = $("bs-bmcount");
    if (count) {
      var parts = [];
      if (visibleLocal.length) parts.push(visibleLocal.length + " local");
      if (visibleLoaded.length) parts.push(visibleLoaded.length + " loaded");
      if (skipN) parts.push(skipN + " skipped");
      count.textContent = parts.length ? parts.join(" · ") : "";
    }
    var html = "";
    if (!visibleLocal.length) {
      html += '<div class="bs-bm-section"><b class="bs-bm-section-head" title="Blue bookmarks stored in this browser (manual, +, or auto-bookmark).">Local</b>' +
        (list.length && skipN
          ? '<p class="bs-empty">All local bookmarks are always-skipped — see Skip tab.</p>'
          : '<p class="bs-empty">No blue bookmarks yet. Auto-bookmark or + on a peak adds them here.</p>') +
        "</div>";
    } else {
      html += '<div class="bs-bm-section"><b class="bs-bm-section-head" title="Blue bookmarks stored in this browser (manual, +, or auto-bookmark).">Local (' + visibleLocal.length +
        ')</b><ul class="bs-bm-ul">' + visibleLocal.map(function (b) {
        var freq = b.frequency;
        var auto = isAuto(b);
        return '<li class="bs-bm-row' +
          '" data-bm-tune="' + freq + '" data-bm-mode="' + escapeHtml(b.modulation || "") +
          '" title="Click the row to tune. Use edit for name / MHz / mode, or ign to always-skip this frequency.">' +
          '<span class="bs-bm-name" title="Bookmark name. Click edit to rename.">' + escapeHtml(bookmarkDisplayName(b)) + "</span>" +
          (auto ? '<span class="bs-bm-auto" title="Created by Auto-bookmark actives during a scan.">[auto]</span>' : "") +
          '<span class="bs-bm-mhz" title="Frequency (MHz). Click the row to tune here.">' + fmtMhz(freq) + "</span>" +
          '<button type="button" class="bs-tiny bs-btn-util" data-bm-ren="' + freq + '" data-bm-kind="local" title="Open editor: change name, MHz, or mode for this local bookmark (this browser).">edit</button>' +
          '<button type="button" class="bs-tiny bs-btn-lock" data-bm-ign="' + freq + '" title="Always skip this MHz during scans (Skip tab). Does not delete the bookmark.">ign</button>' +
          "</li>";
      }).join("") + "</ul></div>";
    }
    if (!visibleLoaded.length) {
      html += '<div class="bs-bm-section"><b class="bs-bm-section-head" title="Imported / Load user bookmarks ([load]) stored in this browser.">Loaded</b>' +
        (loadedBookmarks.length && skipN
          ? '<p class="bs-empty">All loaded bookmarks are always-skipped — see Skip tab.</p>'
          : '<p class="bs-empty">Load bookmarks from JSON/CSV — tagged [load], scanned with Scan bookmarks.</p>') +
        "</div>";
    } else {
      html += '<div class="bs-bm-section"><b class="bs-bm-section-head" title="Imported / Load user bookmarks ([load]) stored in this browser.">Loaded (' + visibleLoaded.length +
        ')</b><ul class="bs-bm-ul">' +
        visibleLoaded.map(function (b) {
          var freq = b.frequency;
          return '<li class="bs-bm-row bs-bm-loaded' +
            '" data-loaded-tune="' + freq + '" data-bm-mode="' + escapeHtml(b.modulation || "") +
            '" title="Click the row to tune. Use edit for name / MHz / mode, or ign to always-skip this frequency.">' +
            '<span class="bs-bm-name" title="Loaded bookmark name. Click edit to rename.">' + escapeHtml(b.name || fmtMhz(freq)) + "</span>" +
            '<span class="bs-bm-load" title="Imported or Load user bookmark — scanned with Scan bookmarks.">[load]</span>' +
            '<span class="bs-bm-mhz" title="Frequency (MHz). Click the row to tune here.">' + fmtMhz(freq) + "</span>" +
            '<button type="button" class="bs-tiny bs-btn-util" data-bm-ren="' + freq + '" data-bm-kind="loaded" title="Open editor: change name, MHz, or mode for this loaded bookmark (this browser).">edit</button>' +
            '<button type="button" class="bs-tiny bs-btn-lock" data-bm-ign="' + freq + '" title="Always skip this MHz during scans (Skip tab). Does not delete the bookmark.">ign</button>' +
            "</li>";
        }).join("") + "</ul></div>";
    }
    host.innerHTML = html;
    try { stripNativeTitles(host); } catch (eSt) {}
    var editOrig = Number($("bs-bm-edit-orig") && $("bs-bm-edit-orig").value);
    var editKind = ($("bs-bm-edit-kind") && $("bs-bm-edit-kind").value) || "local";
    if (isFinite(editOrig) && editOrig > 0) highlightBookmarkEditorRow(editKind, editOrig);
    var skipHead = $("bs-skiphead");
    var skipHost = $("bs-skiplist");
    var ign = (S.ignoredFreqs || []).slice().sort(function (a, b) { return a - b; });
    if (skipHead) skipHead.textContent = ign.length ? ("Always skip (" + ign.length + ")") : "Always skip";
    if (skipHost) {
      if (!ign.length) {
        skipHost.innerHTML = '<p class="bs-empty">None. Always skip or ign on a peak adds frequencies here.</p>';
      } else {
        skipHost.innerHTML =
          '<div class="bs-skip-row bs-skip-head" aria-hidden="true">' +
          '<span class="bs-skip-mhz">MHz</span>' +
          '<span class="bs-skip-name">Name</span>' +
          '<span class="bs-skip-info">Details</span>' +
          '<span class="bs-skip-act"></span></div>' +
          ign.map(function (f) {
            var det = skipDetailForFreq(f);
            return '<div class="bs-skip-row">' +
              '<button type="button" class="bs-tune bs-skip-mhz" data-skip-tune="' + f + '" title="Tune to this frequency.">' +
              fmtMhz(f) + "</button>" +
              '<span class="bs-skip-name bs-bm-name" title="' + escapeHtml(det.name || "") + '">' +
              (det.name ? escapeHtml(det.name) : "—") + "</span>" +
              '<span class="bs-skip-info" title="' + escapeHtml(det.info) + '">' + escapeHtml(det.info) + "</span>" +
              '<button type="button" class="bs-tiny bs-on bs-skip-act" data-bm-ign="' + f + '" title="Stop always-skipping this frequency.">un-ign</button></div>';
          }).join("");
      }
    }
    try { renderLockoutList(); } catch (eLo) {}
    renderAudioClips();
    updateTabLabels();
  }

  function clipLabel(clip) {
    return clip.name || (clip.freq ? fmtMhz(clip.freq) : (clip.file || "clip"));
  }

  function clipPreviewSec() {
    var n = Number(S.clipPreviewSec);
    var fromUi = NaN;
    if ($("bs-aud-preview-sec") && document.activeElement === $("bs-aud-preview-sec")) {
      fromUi = Number($("bs-aud-preview-sec").value);
    } else if ($("bs-dec-preview-sec") && document.activeElement === $("bs-dec-preview-sec")) {
      fromUi = Number($("bs-dec-preview-sec").value);
    } else if ($("bs-aud-preview-sec")) {
      fromUi = Number($("bs-aud-preview-sec").value);
    } else if ($("bs-dec-preview-sec")) {
      fromUi = Number($("bs-dec-preview-sec").value);
    }
    if (isFinite(fromUi) && fromUi > 0) n = fromUi;
    return Math.max(1, Math.min(15, isFinite(n) && n > 0 ? n : 3));
  }

  function clipVolumeLevel() {
    var n = Number(S.clipVolume);
    var active = document.activeElement;
    if (active && active.id === "bs-aud-vol") {
      var fromActive = Number(active.value);
      if (isFinite(fromActive)) n = fromActive;
    } else if ($("bs-aud-vol")) {
      var fromAud = Number($("bs-aud-vol").value);
      if (isFinite(fromAud)) n = fromAud;
    }
    return Math.max(0, Math.min(100, isFinite(n) ? n : 80));
  }

  function syncClipMuteUi() {
    var btn = $("bs-aud-mute");
    if (!btn) return;
    var muted = !!S.clipMuted;
    btn.classList.toggle("bs-on", muted);
    btn.textContent = muted ? "Muted" : "Mute";
    btn.setAttribute("aria-pressed", muted ? "true" : "false");
    btn.title = muted
      ? ("Unmute clip playback — Vol " + clipVolumeLevel() + "% remembered for Play / Play all.")
      : "Mute Play / Play all in this panel. Does not change OpenWebRX receiver volume.";
  }

  function toggleClipMute() {
    S.clipMuted = !S.clipMuted;
    applyClipVolume();
    saveSettings();
    setStatus(S.clipMuted
      ? ("Audio clips muted — Vol " + clipVolumeLevel() + "% remembered.")
      : ("Audio clips unmuted — Vol " + clipVolumeLevel() + "%."));
  }

  function applyClipVolume() {
    var pct = clipVolumeLevel();
    var muted = !!S.clipMuted;
    var v = muted ? 0 : pct / 100;
    var lbl = $("bs-aud-vol-lbl");
    if (lbl) lbl.textContent = muted ? ("mute · " + pct + "%") : (pct + "%");
    var slider = $("bs-aud-vol");
    if (slider && document.activeElement !== slider) slider.value = pct;
    if ($("bs-aud-vol-box")) $("bs-aud-vol-box").classList.toggle("bs-aud-muted", muted);
    syncClipMuteUi();
    if (clipPlaying && clipPlaying.el) {
      try { clipPlaying.el.volume = v; } catch (e) {}
    }
    return v;
  }

  function makeClipAudio(url) {
    var el = new Audio(url);
    try { el.volume = applyClipVolume(); } catch (e) {}
    return el;
  }

  function updateClipPreviewUi() {
    var btns = [$("bs-aud-preview"), $("bs-dec-preview")];
    var secInps = [$("bs-aud-preview-sec"), $("bs-dec-preview-sec")];
    var i;
    for (i = 0; i < btns.length; i++) {
      var btn = btns[i];
      if (!btn) continue;
      if (clipPreview.running) {
        btn.textContent = "Stop play-all";
        btn.classList.add("bs-on");
        btn.title = "Stop walking through clip play-all.";
      } else {
        btn.textContent = "Play all";
        btn.classList.remove("bs-on");
        btn.title = "Play the first N seconds of each clip in order. Highlights the one playing, then advances.";
      }
      btn.disabled = !audioClips.length && !clipPreview.running;
    }
    for (i = 0; i < secInps.length; i++) {
      var secInp = secInps[i];
      if (!secInp) continue;
      secInp.disabled = !!clipPreview.running;
      if (!clipPreview.running && document.activeElement !== secInp) {
        secInp.value = clipPreviewSec();
      }
    }
  }

  function scrollClipRowIntoView(id) {
    var hosts = [$("bs-audiolist"), $("bs-decodelist")];
    var hi;
    for (hi = 0; hi < hosts.length; hi++) {
      var host = hosts[hi];
      if (!host) continue;
      var row = host.querySelector('.bs-audio-row[data-clip-id="' + id + '"]');
      if (!row || typeof row.scrollIntoView !== "function") continue;
      try {
        row.scrollIntoView({ block: "nearest", behavior: "smooth" });
      } catch (e) {
        try { row.scrollIntoView(false); } catch (e2) {}
      }
    }
  }

  function renderAudioClips() {
    var host = $("bs-audiolist");
    var head = $("bs-audiohead");
    if (head) {
      var label = audioClips.length ? ("Audio clips (" + audioClips.length + ")") : "Audio clips";
      if (clipPreview.running && audioClips.length) {
        label += " · preview " + (clipPreview.index + 1) + "/" + audioClips.length;
      }
      head.textContent = label;
    }
    updateClipPreviewUi();
    if (!host) {
      updateTabLabels();
      renderDecodeQueue();
      return;
    }
    if (!audioClips.length) {
      host.innerHTML = '<p class="bs-empty">None yet. Tick Record busy, then Scan bookmarks — clips are saved while parked on a busy/held channel, not during the survey walk. Clips persist in this browser until you remove them (×). Load audio adds files from disk.</p>';
      updateTabLabels();
      renderDecodeQueue();
      return;
    }
    host.innerHTML = audioClips.map(function (c, idx) {
      var when = new Date(c.at || Date.now()).toLocaleTimeString();
      var playing = clipPlaying && clipPlaying.id === c.id;
      var previewing = clipPreview.running && clipPreview.index === idx && playing;
      return '<div class="bs-audio-row' + (playing ? " bs-audio-on" : "") +
        (previewing ? " bs-audio-preview" : "") +
        '" data-clip-id="' + c.id + '">' +
        '<button type="button" class="bs-tiny ' + (playing ? "bs-stop" : "bs-btn-play") + '" data-clip-play="' + c.id + '" title="' +
        (playing ? "Stop this clip." : "Play this clip in the panel.") + '">' +
        (playing ? "Stop" : "Play") + "</button>" +
        (c.freq
          ? ('<button type="button" class="bs-tune bs-bm-mhz" data-clip-tune="' + c.id + '" title="Tune the receiver to ' + fmtMhz(c.freq) + '.">' + fmtMhz(c.freq) + "</button>")
          : '<span class="bs-bm-mhz">—</span>') +
        '<span class="bs-bm-name" title="' + escapeHtml(clipLabel(c)) + '">' + escapeHtml(clipLabel(c)) + "</span>" +
        '<span class="bs-hint">' + when + (c.loaded ? " · loaded" : "") +
        (previewing ? " · preview" : "") +
        (extraOn("clipMeta") ? (
          (c.durationMs ? (" · " + (c.durationMs / 1000).toFixed(1) + "s") : (c.blob && c.blob.size ? (" · " + Math.round(c.blob.size / 1024) + " KB") : "")) +
          (c.activeMs && c.durationMs ? (" · voice " + Math.round(100 * c.activeMs / c.durationMs) + "%") : "") +
          (c.transcript ? (" · “" + escapeHtml(String(c.transcript).slice(0, 40)) + "”") : "")
        ) : "") + "</span>" +
        '<button type="button" class="bs-tiny bs-btn-export" data-clip-save="' + c.id + '" title="Download this clip.">Save</button>' +
        (extraOn("speechToText") ? '<button type="button" class="bs-tiny bs-btn-info" data-clip-xscript="' + c.id + '" title="Try browser speech-to-text while playing (Chrome).">TXT</button>' : "") +
        '<button type="button" class="bs-tiny bs-btn-clear" data-clip-del="' + c.id + '" title="Remove this clip from the list (does not delete a file you already saved).">×</button>' +
        "</div>";
    }).join("");
    if (clipPlaying && clipPlaying.id) scrollClipRowIntoView(clipPlaying.id);
    updateTabLabels();
    renderDecodeQueue();
  }

  function renderDecodeQueue() {
    var host = $("bs-decodelist");
    updateDecodeRecordUi();
    updateDecodeExportUi();
    if (!host) return;
    if (!audioClips.length) {
      decodeSelectedIds = {};
      host.innerHTML = '<p class="bs-empty">No clips yet. Use <b>Record now</b> above, or tick <b>Record busy</b> on Bookmarks. Same list as Audio clips. Export WAV for external digi decode (WSJT-X, etc.).</p>';
      return;
    }
    var alive = {};
    audioClips.forEach(function (c) { alive[c.id] = true; });
    Object.keys(decodeSelectedIds).forEach(function (id) {
      if (!alive[id]) delete decodeSelectedIds[id];
    });
    host.innerHTML = audioClips.map(function (c) {
      var when = new Date(c.at || Date.now()).toLocaleString();
      var playing = clipPlaying && clipPlaying.id === c.id;
      var src = c.source || (c.loaded ? "loaded" : "busy");
      var mode = c.mode ? String(c.mode).toUpperCase() : "—";
      var dur = c.durationMs ? ((c.durationMs / 1000).toFixed(1) + "s") :
        (c.blob && c.blob.size ? (Math.round(c.blob.size / 1024) + " KB") : "");
      var checked = decodeSelectedIds[c.id] ? " checked" : "";
      return '<div class="bs-audio-row bs-decode-row' + (playing ? " bs-audio-on" : "") +
        '" data-clip-id="' + c.id + '">' +
        '<label class="bs-dec-sel" title="Select for Export selected.">' +
        '<input type="checkbox" class="bs-dec-sel-cb" data-clip-sel="' + c.id + '"' + checked + ">" +
        "</label>" +
        '<button type="button" class="bs-tiny ' + (playing ? "bs-stop" : "bs-btn-play") + '" data-clip-play="' + c.id + '" title="' +
        (playing ? "Stop this clip." : "Play this clip.") + '">' +
        (playing ? "Stop" : "Play") + "</button>" +
        (c.freq
          ? ('<button type="button" class="bs-tune bs-bm-mhz" data-clip-tune="' + c.id + '" title="Tune the receiver to ' + fmtMhz(c.freq) + '.">' + fmtMhz(c.freq) + "</button>")
          : '<span class="bs-bm-mhz">—</span>') +
        '<span class="bs-dec-mode" title="Demod mode when recorded">' + escapeHtml(mode) + "</span>" +
        '<span class="bs-hint">' + escapeHtml(src) +
        (dur ? (" · " + dur) : "") +
        " · " + when +
        (c.transcript ? (" · “" + escapeHtml(String(c.transcript).slice(0, 36)) + "”") : "") +
        "</span>" +
        '<button type="button" class="bs-tiny bs-btn-export" data-clip-wav="' + c.id + '" title="Download as WAV for external decode.">WAV</button>' +
        '<button type="button" class="bs-tiny bs-btn-info" data-clip-xscript="' + c.id + '" data-xscript-force="1" title="Browser speech-to-text while playing (Chrome; quality varies).">TXT</button>' +
        '<button type="button" class="bs-tiny bs-btn-export" data-clip-save="' + c.id + '" title="Download original clip file.">Save</button>' +
        '<button type="button" class="bs-tiny bs-btn-clear" data-clip-del="' + c.id + '" title="Remove this clip.">×</button>' +
        "</div>";
    }).join("");
    updateDecodeExportUi();
  }

  var decodeSelectedIds = {};

  function decodeSelectedClips() {
    return audioClips.filter(function (c) { return c && decodeSelectedIds[c.id]; });
  }

  function updateDecodeExportUi() {
    var nSel = decodeSelectedClips().length;
    var nAll = audioClips.length;
    var btnSel = $("bs-dec-export-sel");
    if (btnSel) {
      btnSel.disabled = nSel < 1;
      btnSel.textContent = nSel ? ("Export selected (" + nSel + ")") : "Export selected";
    }
    var btnAll = $("bs-dec-wav-zip");
    if (btnAll) {
      btnAll.disabled = nAll < 1;
      btnAll.textContent = nAll ? ("Export all (" + nAll + ")") : "Export all";
    }
    var lab = $("bs-dec-sel-lab");
    if (lab) {
      lab.textContent = nAll
        ? (nSel + " selected · " + nAll + " clip" + (nAll === 1 ? "" : "s"))
        : "";
    }
  }

  function setDecodeSelection(ids, on) {
    (ids || []).forEach(function (id) {
      if (on) decodeSelectedIds[id] = true;
      else delete decodeSelectedIds[id];
    });
    updateDecodeExportUi();
  }

  function decodeSelectAll(on) {
    if (on) {
      audioClips.forEach(function (c) { decodeSelectedIds[c.id] = true; });
    } else {
      decodeSelectedIds = {};
    }
    var host = $("bs-decodelist");
    if (host) {
      host.querySelectorAll(".bs-dec-sel-cb").forEach(function (cb) {
        cb.checked = !!on;
      });
    }
    updateDecodeExportUi();
  }

  function stopClipPlayback() {
    if (clipPlaying && clipPlaying.el) {
      try { clipPlaying.el.pause(); } catch (e) {}
      try { clipPlaying.el.src = ""; } catch (e2) {}
    }
    clipPlaying = null;
  }

  function stopClipPreview(opts) {
    opts = opts || {};
    clipPreview.gen++;
    if (clipPreview.timer) {
      clearTimeout(clipPreview.timer);
      clipPreview.timer = null;
    }
    var was = clipPreview.running;
    clipPreview.running = false;
    clipPreview.index = 0;
    if (!opts.keepAudio) stopClipPlayback();
    updateClipPreviewUi();
    if (!opts.silent) renderAudioClips();
    return was;
  }

  function playPreviewAt(idx, gen) {
    if (gen !== clipPreview.gen || !clipPreview.running) return;
    if (idx >= audioClips.length) {
      stopClipPreview({ silent: true });
      renderAudioClips();
      setStatus("Play-all done — heard first " + clipPreviewSec() + "s of " + audioClips.length + " clip(s).");
      return;
    }
    var clip = audioClips[idx];
    if (!clip || !clip.url) {
      playPreviewAt(idx + 1, gen);
      return;
    }
    clipPreview.index = idx;
    stopClipPlayback();
    var el = makeClipAudio(clip.url);
    var advanced = false;
    function advance() {
      if (advanced || gen !== clipPreview.gen) return;
      advanced = true;
      if (clipPreview.timer) {
        clearTimeout(clipPreview.timer);
        clipPreview.timer = null;
      }
      try { el.pause(); } catch (e) {}
      if (clipPlaying && clipPlaying.el === el) clipPlaying = null;
      playPreviewAt(idx + 1, gen);
    }
    clipPlaying = { id: clip.id, el: el, preview: true };
    el.onended = advance;
    el.onerror = function () { advance(); };
    var ms = Math.round(clipPreviewSec() * 1000);
    clipPreview.timer = setTimeout(advance, ms);
    renderAudioClips();
    var go = el.play();
    if (go && typeof go.catch === "function") {
      go.catch(function () {
        if (gen !== clipPreview.gen) return;
        stopClipPreview({ silent: true });
        renderAudioClips();
        setStatus("Playback blocked — click Play all again after interacting with the page.");
      });
    }
    setStatus("Play-all " + (idx + 1) + "/" + audioClips.length + " · first " + clipPreviewSec() + "s · " +
      (clip.freq ? fmtMhz(clip.freq) : clipLabel(clip)));
  }

  function toggleClipPreview() {
    if (clipPreview.running) {
      stopClipPreview();
      setStatus("Play-all stopped.");
      return;
    }
    if (!audioClips.length) {
      setStatus("No clips to play.");
      return;
    }
    if ($("bs-aud-preview-sec") || $("bs-dec-preview-sec")) {
      S.clipPreviewSec = clipPreviewSec();
      try { saveSettings(); } catch (e) {}
    }
    clipPreview.running = true;
    clipPreview.index = 0;
    clipPreview.gen++;
    var gen = clipPreview.gen;
    updateClipPreviewUi();
    setStatus("Playing first " + clipPreviewSec() + "s of " + audioClips.length + " clip(s)…");
    playPreviewAt(0, gen);
  }

  function playAudioClip(id) {
    var clip = null;
    for (var i = 0; i < audioClips.length; i++) {
      if (audioClips[i].id === id) clip = audioClips[i];
    }
    if (!clip || !clip.url) return;
    if (clipPreview.running) stopClipPreview({ keepAudio: true, silent: true });
    if (clipPlaying && clipPlaying.id === id && !clipPlaying.preview) {
      stopClipPlayback();
      renderAudioClips();
      return;
    }
    stopClipPlayback();
    var el = makeClipAudio(clip.url);
    clipPlaying = { id: id, el: el };
    el.onended = function () {
      if (clipPlaying && clipPlaying.el === el) clipPlaying = null;
      renderAudioClips();
    };
    el.onerror = function () {
      setStatus("Could not play that clip in this browser.");
      if (clipPlaying && clipPlaying.el === el) clipPlaying = null;
      renderAudioClips();
    };
    var go = el.play();
    if (go && typeof go.catch === "function") {
      go.catch(function () {
        setStatus("Playback blocked — click Play again after interacting with the page.");
        if (clipPlaying && clipPlaying.el === el) clipPlaying = null;
        renderAudioClips();
      });
    }
    renderAudioClips();
  }

  function downloadBlob(name, blob) {
    var a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { try { URL.revokeObjectURL(a.href); } catch (e) {} }, 1500);
  }

  function writeWavString(view, offset, str) {
    for (var i = 0; i < str.length; i++) view.setUint8(offset + i, str.charCodeAt(i));
  }

  function audioBufferToWavBlob(buffer) {
    var numCh = buffer.numberOfChannels;
    var sampleRate = buffer.sampleRate;
    var numFrames = buffer.length;
    var bytesPerSample = 2;
    var blockAlign = numCh * bytesPerSample;
    var dataSize = numFrames * blockAlign;
    var ab = new ArrayBuffer(44 + dataSize);
    var view = new DataView(ab);
    writeWavString(view, 0, "RIFF");
    view.setUint32(4, 36 + dataSize, true);
    writeWavString(view, 8, "WAVE");
    writeWavString(view, 12, "fmt ");
    view.setUint32(16, 16, true);
    view.setUint16(20, 1, true);
    view.setUint16(22, numCh, true);
    view.setUint32(24, sampleRate, true);
    view.setUint32(28, sampleRate * blockAlign, true);
    view.setUint16(32, blockAlign, true);
    view.setUint16(34, 16, true);
    writeWavString(view, 36, "data");
    view.setUint32(40, dataSize, true);
    var offset = 44;
    var chans = [];
    for (var c = 0; c < numCh; c++) chans.push(buffer.getChannelData(c));
    for (var i = 0; i < numFrames; i++) {
      for (var ch = 0; ch < numCh; ch++) {
        var s = Math.max(-1, Math.min(1, chans[ch][i]));
        view.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7fff, true);
        offset += 2;
      }
    }
    return new Blob([ab], { type: "audio/wav" });
  }

  function clipToWavBlob(clip) {
    if (!clip || !clip.blob) return Promise.reject(new Error("No clip"));
    var AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return Promise.resolve(clip.blob);
    return clip.blob.arrayBuffer().then(function (raw) {
      var ctx = new AC();
      return ctx.decodeAudioData(raw.slice(0)).then(function (buf) {
        try { ctx.close(); } catch (e) {}
        return audioBufferToWavBlob(buf);
      }).catch(function (err) {
        try { ctx.close(); } catch (e2) {}
        throw err;
      });
    });
  }

  function clipWavFileName(clip) {
    var base = String(clip.file || clipFileName(clip)).replace(/\.[^.]+$/, "");
    return base + ".wav";
  }

  function clipManifestEntry(clip) {
    return {
      id: clip.id,
      freq_hz: clip.freq || 0,
      freq_mhz: clip.freq ? (clip.freq / 1e6) : null,
      mode: clip.mode || "",
      source: clip.source || "",
      name: clip.name || "",
      pid: clip.pid || "",
      when: clip.at || null,
      when_iso: clip.at ? new Date(clip.at).toISOString() : null,
      mime: clip.mime || "",
      duration_ms: clip.durationMs || 0,
      transcript: clip.transcript || "",
      note: clip.note || ""
    };
  }

  function saveAudioClipWav(id) {
    var clip = null;
    for (var i = 0; i < audioClips.length; i++) {
      if (audioClips[i].id === id) clip = audioClips[i];
    }
    if (!clip || !clip.blob) {
      setStatus("That clip is gone.");
      return;
    }
    setStatus("Converting to WAV…");
    clipToWavBlob(clip).then(function (wav) {
      downloadBlob(clipWavFileName(clip), wav);
      setStatus("Saved WAV · " + clipWavFileName(clip));
    }).catch(function () {
      downloadBlob(clip.file || clipFileName(clip), clip.blob);
      setStatus("WAV convert failed — saved original " + (clip.ext || "audio") + " instead.");
    });
  }

  function saveDecodeWavZip(clips, label) {
    clips = (clips || []).filter(function (c) { return c && c.blob; });
    if (!clips.length) {
      setStatus(label === "selected" ? "No clips selected." : "No clips to export.");
      return;
    }
    setStatus("Building WAV ZIP (" + clips.length + ")…");
    loadJSZip().then(function (JSZip) {
      var zip = new JSZip();
      var manifest = [];
      var chain = Promise.resolve();
      clips.forEach(function (clip, idx) {
        chain = chain.then(function () {
          return clipToWavBlob(clip).then(function (wav) {
            var name = clipWavFileName(clip);
            if (zip.file(name)) name = idx + "-" + name;
            zip.file(name, wav);
            var ent = clipManifestEntry(clip);
            ent.file = name;
            manifest.push(ent);
          }).catch(function () {
            var name = clip.file || clipFileName(clip);
            if (zip.file(name)) name = idx + "-" + name;
            zip.file(name, clip.blob);
            var ent = clipManifestEntry(clip);
            ent.file = name;
            ent.wav_failed = true;
            manifest.push(ent);
          });
        });
      });
      return chain.then(function () {
        zip.file("manifest.json", JSON.stringify({
          plugin: "toolbox",
          version: Plugins.toolbox._version || 0,
          exported: new Date().toISOString(),
          scope: label || "all",
          clips: manifest
        }, null, 2));
        return zip.generateAsync({ type: "blob" });
      }).then(function (blob) {
        var prefix = label === "selected" ? "owrx-decode-selected-" : "owrx-decode-all-";
        downloadBlob(prefix + zipStamp() + ".zip", blob);
        setStatus("Saved WAV ZIP · " + clips.length + " clip(s)" +
          (label === "selected" ? " (selected)" : "") + ".");
      });
    }).catch(function (e) {
      setStatus("WAV ZIP failed — " + friendlyError(e, "Export"));
    });
  }

  function saveAllDecodeWavZip() {
    saveDecodeWavZip(audioClips.slice(), "all");
  }

  function saveSelectedDecodeWavZip() {
    saveDecodeWavZip(decodeSelectedClips(), "selected");
  }

  function saveAudioClip(id) {
    var clip = null;
    for (var i = 0; i < audioClips.length; i++) {
      if (audioClips[i].id === id) clip = audioClips[i];
    }
    if (!clip || !clip.blob) {
      setStatus("That clip is gone.");
      return;
    }
    downloadBlob(clip.file || clipFileName(clip), clip.blob);
  }

  var jsZipLoadPromise = null;

  function loadJSZip() {
    if (window.JSZip) return Promise.resolve(window.JSZip);
    if (jsZipLoadPromise) return jsZipLoadPromise;
    jsZipLoadPromise = new Promise(function (resolve, reject) {
      var s = document.createElement("script");
      s.src = "https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js";
      s.async = true;
      s.onload = function () {
        if (window.JSZip) resolve(window.JSZip);
        else reject(new Error("JSZip did not load"));
      };
      s.onerror = function () { reject(new Error("Could not load JSZip from CDN")); };
      document.head.appendChild(s);
    });
    return jsZipLoadPromise;
  }

  var TOOLBOX_DIST = {
    repo: "G4EA5/openwebrx-toolbox",
    cdn: "https://cdn.jsdelivr.net/gh/G4EA5/openwebrx-toolbox@main/",
    raw: "https://raw.githubusercontent.com/G4EA5/openwebrx-toolbox/main/",
    local: "static/plugins/receiver/toolbox/"
  };

  function parsePluginVersionText(text) {
    var m = String(text || "").match(/_version\s*=\s*(\d+)/);
    return m ? Number(m[1]) : 0;
  }

  function fetchTextUrl(url) {
    return fetch(url, { cache: "no-store" }).then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status + " for " + url);
      return r.text().then(function (text) {
        return { url: url, text: text };
      });
    });
  }

  function fetchFirstUrl(urls) {
    var i = 0;
    function next() {
      if (i >= urls.length) return Promise.reject(new Error("Could not fetch plugin files"));
      return fetchTextUrl(urls[i++]).catch(function () { return next(); });
    }
    return next();
  }

  /** Probe GitHub (+ radio copy) so Install check can show latest vs running. */
  function probeLatestToolboxVersion() {
    var remoteJsUrls = [
      TOOLBOX_DIST.cdn + "toolbox.js",
      TOOLBOX_DIST.raw + "toolbox.js"
    ];
    var localJs = TOOLBOX_DIST.local + "toolbox.js";
    return Promise.all([
      fetchFirstUrl(remoteJsUrls).catch(function () { return null; }),
      fetchTextUrl(localJs).catch(function () { return null; })
    ]).then(function (pair) {
      var remote = pair[0];
      var local = pair[1];
      var remoteVer = remote ? parsePluginVersionText(remote.text) : 0;
      var localVer = local ? parsePluginVersionText(local.text) : 0;
      var latestVer = Math.max(remoteVer, localVer);
      var source = "";
      if (latestVer > 0) {
        if (remoteVer >= localVer && remoteVer > 0) source = "GitHub";
        else if (localVer > 0) source = "this radio";
        else source = "GitHub";
      }
      return {
        remoteVer: remoteVer,
        localVer: localVer,
        latestVer: latestVer,
        source: source
      };
    });
  }

  function updateInstallVersionUi(info) {
    var el = $("bs-install-ver");
    var btn = $("bs-dl-latest");
    var mine = Number(Plugins.toolbox._version) || 0;
    var mineLab = mine ? ("v" + mine) : "v?";
    if (!el) return;
    var latest = info && info.latestVer ? Number(info.latestVer) : 0;
    var src = (info && info.source) || "";
    var html = "This install: <b>" + mineLab + "</b>";
    if (latest > 0) {
      html += ' · Latest available: <b id="bs-latest-ver">v' + latest + "</b>";
      if (src) html += " <span class=\"bs-install-src\">(" + src + ")</span>";
      if (latest > mine) {
        html += ' <span class="bs-install-outdated">— update available</span>';
      } else if (latest === mine) {
        html += ' <span class="bs-install-current">— up to date</span>';
      } else {
        html += ' <span class="bs-install-ahead">— newer than published</span>';
      }
    } else if (info && info.failed) {
      html += ' · Latest available: <span class="bs-install-unknown">could not check</span>';
    } else {
      html += ' · Latest available: <span class="bs-install-unknown">checking…</span>';
    }
    el.innerHTML = html;
    if (btn) {
      if (latest > 0) {
        btn.textContent = "Download latest (v" + latest + ")";
        btn.title =
          "Download Toolbox v" + latest +
          " zip from " + (src || "GitHub / this radio") +
          ". This page is running " + mineLab + ".";
      } else {
        btn.textContent = "Download latest version";
        btn.title =
          "Download the newest Toolbox zip (toolbox.js, toolbox.css, install.sh) from GitHub, or from this radio if GitHub is behind. This page is " +
          mineLab + ".";
      }
    }
  }

  function refreshInstallVersionCompare() {
    updateInstallVersionUi(null);
    return probeLatestToolboxVersion()
      .then(function (info) {
        updateInstallVersionUi(info);
        return info;
      })
      .catch(function () {
        updateInstallVersionUi({ failed: true, latestVer: 0 });
        return null;
      });
  }

  /** Pick newest Toolbox package: GitHub (toolbox or legacy band_survey) vs this radio's copy. */
  function resolveLatestToolboxSources() {
    var localJs = TOOLBOX_DIST.local + "toolbox.js";
    var remoteJsUrls = [
      TOOLBOX_DIST.cdn + "toolbox.js",
      TOOLBOX_DIST.raw + "toolbox.js",
      TOOLBOX_DIST.cdn + "legacy/band_survey/band_survey.js",
      TOOLBOX_DIST.raw + "legacy/band_survey/band_survey.js"
    ];
    return Promise.all([
      fetchTextUrl(localJs).catch(function () { return null; }),
      fetchFirstUrl(remoteJsUrls).catch(function () { return null; })
    ]).then(function (pair) {
      var local = pair[0];
      var remote = pair[1];
      if (!local && !remote) throw new Error("No Toolbox files on this radio or GitHub");
      var localVer = local ? parsePluginVersionText(local.text) : 0;
      var remoteVer = remote ? parsePluginVersionText(remote.text) : 0;
      var useLocal = !remote || (local && localVer >= remoteVer);
      var js = useLocal ? local : remote;
      var base;
      if (useLocal) {
        base = TOOLBOX_DIST.local;
      } else if (/band_survey\.js(\?|$)/.test(js.url)) {
        base = js.url.replace(/band_survey\.js(\?.*)?$/, "");
      } else {
        base = js.url.replace(/toolbox\.js(\?.*)?$/, "");
      }
      var cssName = useLocal || !/band_survey\.js/.test(js.url) ? "toolbox.css" : "band_survey.css";
      return Promise.all([
        Promise.resolve(js),
        fetchFirstUrl([base + cssName, TOOLBOX_DIST.local + "toolbox.css", TOOLBOX_DIST.cdn + "toolbox.css", TOOLBOX_DIST.cdn + "legacy/band_survey/band_survey.css"]),
        fetchFirstUrl([base + "install.sh", TOOLBOX_DIST.local + "install.sh", TOOLBOX_DIST.cdn + "install.sh", TOOLBOX_DIST.raw + "install.sh"]),
        fetchFirstUrl([base + "LICENSE", TOOLBOX_DIST.local + "LICENSE", TOOLBOX_DIST.cdn + "LICENSE"]).catch(function () { return null; }),
        fetchFirstUrl([base + "README.md", TOOLBOX_DIST.local + "README.md", TOOLBOX_DIST.cdn + "README.md"]).catch(function () { return null; })
      ]).then(function (files) {
        return {
          js: files[0],
          css: files[1],
          install: files[2],
          license: files[3],
          readme: files[4],
          source: useLocal ? "this radio" : "GitHub",
          version: parsePluginVersionText(files[0].text) || (useLocal ? localVer : remoteVer)
        };
      });
    });
  }

  function downloadLatestToolboxZip() {
    var btn = $("bs-dl-latest");
    if (btn) btn.disabled = true;
    setStatus("Fetching latest Toolbox…");
    resolveLatestToolboxSources().then(function (pack) {
      return loadJSZip().then(function (JSZip) {
        var zip = new JSZip();
        zip.file("toolbox.js", pack.js.text);
        zip.file("toolbox.css", pack.css.text);
        zip.file("install.sh", pack.install.text);
        if (pack.license) zip.file("LICENSE", pack.license.text);
        if (pack.readme) zip.file("README.md", pack.readme.text);
        var ver = pack.version || "latest";
        return zip.generateAsync({ type: "blob" }).then(function (blob) {
          downloadBlob("owrx-toolbox-v" + ver + ".zip", blob);
          var mine = Plugins.toolbox._version || "?";
          var note = "Downloaded Toolbox v" + ver + " (from " + pack.source + ").";
          if (pack.version && mine && Number(pack.version) <= Number(mine) && pack.source === "GitHub") {
            note += " You already have v" + mine + " — GitHub may be behind.";
          } else if (mine && String(mine) !== String(ver)) {
            note += " This page is v" + mine + ".";
          }
          note += " Unzip on the radio host and run ./install.sh, then hard-refresh.";
          setStatus(note);
        });
      });
    }).catch(function (err) {
      setStatus(friendlyError(err, "Download latest"));
    }).then(function () {
      if (btn) btn.disabled = false;
      try { refreshInstallVersionCompare(); } catch (eVer) {}
    });
  }

  function zipStamp() {
    var s = new Date().toISOString().slice(0, 19).replace(/[-:T]/g, "");
    return s.slice(0, 8) + "-" + s.slice(8);
  }

  function uniqueZipEntry(name, used) {
    var base = String(name || "clip.webm");
    if (!used[base]) {
      used[base] = 1;
      return base;
    }
    used[base]++;
    var dot = base.lastIndexOf(".");
    if (dot > 0) return base.slice(0, dot) + "-" + used[base] + base.slice(dot);
    return base + "-" + used[base];
  }

  function saveAllAudioClips() {
    if (!audioClips.length) {
      setStatus("No clips to save. Tick Record busy and scan a busy channel, or Load audio first.");
      toast("No audio clips yet.");
      return;
    }
    var n = 0;
    audioClips.forEach(function (c, i) {
      if (!c || !c.blob) return;
      n++;
      setTimeout(function () { saveAudioClip(c.id); }, i * 250);
    });
    if (!n) {
      setStatus("No clip data to download.");
      return;
    }
    setStatus("Downloading " + n + " audio clip" + (n === 1 ? "" : "s") + " as separate files.");
  }

  function saveAllAudioClipsZip() {
    if (!audioClips.length) {
      setStatus("No clips to save. Tick Record busy and scan a busy channel, or Load audio first.");
      toast("No audio clips yet.");
      return;
    }
    var clips = audioClips.filter(function (c) { return c && c.blob; });
    if (!clips.length) {
      setStatus("No clip data to pack.");
      return;
    }
    setStatus("Building ZIP (" + clips.length + " clip" + (clips.length === 1 ? "" : "s") + ")…");
    loadJSZip().then(function (JSZip) {
      var zip = new JSZip();
      var used = {};
      clips.forEach(function (c) {
        zip.file(uniqueZipEntry(c.file || clipFileName(c), used), c.blob);
      });
      return zip.generateAsync({ type: "blob", compression: "DEFLATE", compressionOptions: { level: 6 } });
    }).then(function (blob) {
      downloadBlob("sv-audio-clips-" + zipStamp() + ".zip", blob);
      setStatus("Downloaded ZIP with " + clips.length + " audio clip" + (clips.length === 1 ? "" : "s") + ".");
    }).catch(function (err) {
      setStatus(friendlyError(err, "Save all · ZIP"));
      toast("ZIP failed — try Save all for individual files.");
    });
  }

  function removeAudioClip(id) {
    if (clipPreview.running && clipPlaying && clipPlaying.id === id) {
      // skip this clip and continue preview from next
      var nextIdx = clipPreview.index;
      audioClips = audioClips.filter(function (c) {
        if (c.id !== id) return true;
        if (c.url) {
          try { URL.revokeObjectURL(c.url); } catch (e) {}
        }
        deletePersistedClip(id);
        return false;
      });
      clipPreview.gen++;
      if (clipPreview.timer) {
        clearTimeout(clipPreview.timer);
        clipPreview.timer = null;
      }
      stopClipPlayback();
      var gen = clipPreview.gen;
      renderAudioClips();
      if (clipPreview.running) playPreviewAt(Math.min(nextIdx, audioClips.length), gen);
      return;
    }
    audioClips = audioClips.filter(function (c) {
      if (c.id !== id) return true;
      if (clipPlaying && clipPlaying.id === id) stopClipPlayback();
      if (c.url) {
        try { URL.revokeObjectURL(c.url); } catch (e) {}
      }
      deletePersistedClip(id);
      return false;
    });
    renderAudioClips();
  }

  function clearAllAudioClips() {
    if (!audioClips.length) {
      setStatus("No audio clips to clear.");
      return;
    }
    if (!window.confirm("Remove all " + audioClips.length + " audio clip(s) from this browser? Files you already saved to disk are not deleted.")) return;
    var n = audioClips.length;
    stopClipPreview({ silent: true });
    stopClipPlayback();
    audioClips.forEach(function (c) {
      if (c.url) {
        try { URL.revokeObjectURL(c.url); } catch (e) {}
      }
    });
    audioClips = [];
    decodeSelectedIds = {};
    renderAudioClips();
    renderDecodeQueue();
    clearAllPersistedAudioClips().then(function () {
      setStatus("Cleared " + n + " audio clip" + (n === 1 ? "" : "s") + ".");
    });
  }

  function parseFreqFromAudioName(name) {
    var s = String(name || "");
    var m = /(?:^|[^\d])(\d{2,4}(?:[p.]\d{1,3})?)MHz/i.exec(s);
    if (m) return Math.round(parseFloat(m[1].replace("p", ".")) * 1e6);
    m = /REC-[^-]+-(\d{4,7})\.mp3/i.exec(s);
    if (m) return Number(m[1]) * 1000;
    return 0;
  }

  function loadAudioFiles(files) {
    var list = Array.prototype.slice.call(files || []);
    if (!list.length) return;
    var n = 0;
    list.forEach(function (file) {
      if (!file) return;
      var url = URL.createObjectURL(file);
      addAudioClip({
        id: clipSeq++,
        freq: parseFreqFromAudioName(file.name),
        name: file.name.replace(/\.[^.]+$/, ""),
        file: file.name,
        at: (file.lastModified) || Date.now(),
        blob: file,
        url: url,
        mime: file.type || "audio/*",
        ext: (file.name.split(".").pop() || "webm").toLowerCase(),
        loaded: true,
        source: "loaded",
        mode: ""
      });
      n++;
    });
    if (n) {
      setStatus("Imported " + n + " audio file" + (n === 1 ? "" : "s") + " — Play on Audio list / Record.");
      renderAudioClips();
      renderDecodeQueue();
    }
  }

  function onAudioPaneClick(ev) {
    var t = ev.target;
    if (!t || !t.getAttribute) return;
    var sel = t.getAttribute("data-clip-sel");
    if (sel != null || (t.classList && t.classList.contains("bs-dec-sel-cb"))) {
      var id = Number(sel || t.getAttribute("data-clip-sel"));
      if (isFinite(id)) {
        if (t.checked) decodeSelectedIds[id] = true;
        else delete decodeSelectedIds[id];
        updateDecodeExportUi();
      }
      return;
    }
    var play = t.getAttribute("data-clip-play");
    if (play) {
      ev.preventDefault();
      playAudioClip(Number(play));
      return;
    }
    var tuneId = t.getAttribute("data-clip-tune");
    if (tuneId) {
      ev.preventDefault();
      tuneFromAudioClip(Number(tuneId));
      return;
    }
    var wav = t.getAttribute("data-clip-wav");
    if (wav) {
      ev.preventDefault();
      saveAudioClipWav(Number(wav));
      return;
    }
    var save = t.getAttribute("data-clip-save");
    if (save) {
      ev.preventDefault();
      saveAudioClip(Number(save));
      return;
    }
    var del = t.getAttribute("data-clip-del");
    if (del) {
      ev.preventDefault();
      removeAudioClip(Number(del));
      return;
    }
    var xs = t.getAttribute("data-clip-xscript");
    if (xs) {
      ev.preventDefault();
      tryTranscribeClip(Number(xs), { force: t.getAttribute("data-xscript-force") === "1" });
    }
  }

  function tuneFromAudioClip(id) {
    var clip = null;
    var i;
    for (i = 0; i < audioClips.length; i++) {
      if (audioClips[i].id === id) {
        clip = audioClips[i];
        break;
      }
    }
    if (!clip || !clip.freq) {
      setStatus("No frequency on this clip.");
      return;
    }
    if (clip.pid) tuneTo(clip.freq, clip.pid);
    else tuneBookmark(clip.freq, clip.mode || "");
    if (clip.mode && window.UI && typeof UI.setModulation === "function") {
      try { UI.setModulation(clip.mode, ""); } catch (eMod) {}
    }
    setStatus("Tuned to " + fmtMhz(clip.freq) +
      (clip.mode ? (" · " + String(clip.mode).toUpperCase()) : "") + ".");
  }

  function onBookmarkPaneClick(ev) {
    var t = ev.target;
    if (!t) return;
    var clearLock = t.getAttribute && t.getAttribute("data-clear-lock");
    if (clearLock) {
      ev.preventDefault();
      ev.stopPropagation();
      var cf = Number(clearLock);
      saveLockouts(pruneLockouts().filter(function (l) { return Math.abs(l.freq - cf) >= 4000; }));
      renderBookmarkPane();
      setStatus("Cleared lockout for " + fmtMhz(cf) + ".");
      return;
    }
    var ren = t.getAttribute && t.getAttribute("data-bm-ren");
    if (ren) {
      ev.preventDefault();
      ev.stopPropagation();
      askRenameBookmark(Number(ren), t.getAttribute("data-bm-kind") || "local");
      return;
    }
    var ign = t.getAttribute && t.getAttribute("data-bm-ign");
    if (ign) {
      ev.preventDefault();
      ev.stopPropagation();
      var f = Number(ign);
      if (isIgnoredFreq(f)) {
        unignoreFreq(f);
        setStatus("Will land on " + fmtMhz(f) + " again.");
      } else {
        ignoreFreq(f);
        if (continueIfPausedOn(f)) {
          setStatus("Always skip " + fmtMhz(f) + " — continuing scan.");
        } else {
          setStatus("Always skip " + fmtMhz(f) + " (saved in this browser).");
        }
      }
      renderBookmarkPane();
      return;
    }
    var skipTune = t.getAttribute && t.getAttribute("data-skip-tune");
    if (skipTune) {
      tuneBookmark(Number(skipTune), "");
      return;
    }
    var logTune = t.getAttribute && t.getAttribute("data-log-tune");
    if (logTune) {
      tuneBookmark(Number(logTune), "");
      return;
    }
    var row = t.closest && t.closest("[data-bm-tune]");
    if (row) {
      tuneBookmark(Number(row.getAttribute("data-bm-tune")), row.getAttribute("data-bm-mode") || "");
      return;
    }
    row = t.closest && t.closest("[data-loaded-tune]");
    if (row) {
      tuneBookmark(Number(row.getAttribute("data-loaded-tune")), row.getAttribute("data-bm-mode") || "");
    }
  }

  function bandMetaMap() {
    if (!S.bandMeta || typeof S.bandMeta !== "object" || Array.isArray(S.bandMeta)) S.bandMeta = {};
    return S.bandMeta;
  }

  function bandMetaFor(value) {
    var m = bandMetaMap()[value];
    return m && typeof m === "object" ? m : null;
  }

  function bandDisplayName(p) {
    if (!p) return "";
    var meta = bandMetaFor(p.value);
    var alias = meta && String(meta.alias || "").trim();
    return alias || p.label || p.id || p.value || "";
  }

  function bandIsHidden(value) {
    var meta = bandMetaFor(value);
    return !!(meta && meta.hidden);
  }

  function orderedProfiles(includeHidden) {
    var list = profiles().slice();
    if (!includeHidden) {
      list = list.filter(function (p) { return !bandIsHidden(p.value); });
    }
    var order = Array.isArray(S.bandOrder) ? S.bandOrder : [];
    if (!order.length) return list;
    var rank = {};
    order.forEach(function (v, i) { rank[String(v)] = i; });
    list.sort(function (a, b) {
      var ra = Object.prototype.hasOwnProperty.call(rank, a.value) ? rank[a.value] : 1e9;
      var rb = Object.prototype.hasOwnProperty.call(rank, b.value) ? rank[b.value] : 1e9;
      if (ra !== rb) return ra - rb;
      return String(a.label || a.id).localeCompare(String(b.label || b.id));
    });
    return list;
  }

  function orderSelectedForScan(values) {
    values = (values || []).slice();
    var order = Array.isArray(S.bandOrder) ? S.bandOrder : [];
    if (!order.length || values.length < 2) return values;
    var rank = {};
    order.forEach(function (v, i) { rank[String(v)] = i; });
    values.sort(function (a, b) {
      var ra = Object.prototype.hasOwnProperty.call(rank, a) ? rank[a] : 1e9;
      var rb = Object.prototype.hasOwnProperty.call(rank, b) ? rank[b] : 1e9;
      if (ra !== rb) return ra - rb;
      return 0;
    });
    return values;
  }

  function ensureBandOrderComplete() {
    var list = profiles();
    var cur = Array.isArray(S.bandOrder) ? S.bandOrder.slice() : [];
    var seen = {};
    var out = [];
    cur.forEach(function (v) {
      v = String(v);
      if (seen[v]) return;
      if (!list.some(function (p) { return p.value === v; })) return;
      seen[v] = true;
      out.push(v);
    });
    list.forEach(function (p) {
      if (seen[p.value]) return;
      seen[p.value] = true;
      out.push(p.value);
    });
    S.bandOrder = out;
    return out;
  }

  function moveBandOrder(value, dir) {
    var order = ensureBandOrderComplete();
    var i = order.indexOf(value);
    if (i < 0) return;
    var j = i + (dir < 0 ? -1 : 1);
    if (j < 0 || j >= order.length) return;
    var tmp = order[i];
    order[i] = order[j];
    order[j] = tmp;
    S.bandOrder = order;
    saveSettings();
    fillBandsEdit();
    fillBands();
  }

  function setBandAlias(value, alias, opts) {
    opts = opts || {};
    writeBandMeta(value, { alias: alias });
    if (opts.refreshList !== false) fillBands();
    if (opts.refreshEdit !== false) fillBandsEdit();
  }

  function setBandHidden(value, hidden) {
    writeBandMeta(value, { hidden: hidden });
    fillBands();
    fillBandsEdit();
  }

  function writeBandMeta(value, patch) {
    if (!value) return;
    var map = bandMetaMap();
    var cur = map[value] && typeof map[value] === "object" ? {
      alias: String(map[value].alias || "").trim(),
      hidden: !!map[value].hidden,
      note: String(map[value].note || "").trim()
    } : { alias: "", hidden: false, note: "" };
    if (patch && Object.prototype.hasOwnProperty.call(patch, "alias")) {
      cur.alias = String(patch.alias || "").trim();
    }
    if (patch && Object.prototype.hasOwnProperty.call(patch, "hidden")) {
      cur.hidden = !!patch.hidden;
    }
    if (patch && Object.prototype.hasOwnProperty.call(patch, "note")) {
      cur.note = String(patch.note || "").trim();
    }
    if (!cur.alias && !cur.hidden && !cur.note) {
      delete map[value];
    } else {
      map[value] = { alias: cur.alias, hidden: cur.hidden, note: cur.note };
    }
    S.bandMeta = map;
    saveSettings();
  }

  function clearOneBandEdit(value) {
    if (!value) return;
    var map = bandMetaMap();
    delete map[value];
    S.bandMeta = map;
    saveSettings();
    fillBands();
    fillBandsEdit();
  }

  function clearBandEdits() {
    S.bandMeta = {};
    S.bandOrder = [];
    saveSettings();
    fillBandsEdit();
    fillBands();
    setStatus("Band edits cleared (aliases, hide, notes, and custom order).");
  }

  function setBandEditorStatus(msg) {
    var el = $("bs-bd-edit-status");
    if (el) el.textContent = msg || "";
  }

  function applyBdEditPopMinimalView() {
    var on = !!S.bdEditPopMinimal;
    var pop = $("bs-bd-edit-pop");
    if (pop) pop.classList.toggle("bs-bd-edit-pop-min", on);
    var btn = $("bs-bd-edit-pop-mini");
    if (btn) {
      btn.classList.toggle("bs-on", on);
      btn.setAttribute("aria-pressed", on ? "true" : "false");
      btn.textContent = on ? "Full" : "Mini";
      btn.title = on
        ? "Show the full band editor (alias, order, admin fields, delete)."
        : "Minimal popup: Name, Centre, Mode, Save, Done.";
    }
  }

  function toggleBdEditPopMinimalView() {
    S.bdEditPopMinimal = !S.bdEditPopMinimal;
    try { saveSettings(); } catch (eS) {}
    applyBdEditPopMinimalView();
    try { syncBandEditAdvancedUi(); } catch (eAdv) {}
    setStatus(S.bdEditPopMinimal
      ? "Band edit popup · mini (name / centre / mode)."
      : "Band edit popup · full.");
  }

  function closeBandEditPopup() {
    var pop = $("bs-bd-edit-pop");
    if (!pop) return;
    pop.hidden = true;
    pop.classList.remove("bs-bd-edit-pop-on");
    highlightBandEditorRow();
  }

  function openBandEditPopup(title) {
    var pop = $("bs-bd-edit-pop");
    if (!pop) return;
    try { closeBookmarkEditPopup(); } catch (eBm) {}
    /* Keep popup on document.body so overflow:auto panes cannot clip it. */
    try {
      if (pop.parentNode !== document.body) document.body.appendChild(pop);
    } catch (eMove) {}
    var t = $("bs-bd-edit-pop-title");
    if (t) t.textContent = title || "Edit band";
    pop.hidden = false;
    pop.classList.add("bs-bd-edit-pop-on");
    try { applyBdEditPopMinimalView(); } catch (eMin) {}
    try { syncBandEditAdvancedUi(); } catch (eAdv) {}
    try { prepareEditPopup(pop, "owrx_toolbox_bd_edit_pop_layout_v1"); } catch (eLay) {}
    try {
      stripNativeTitles(pop);
      pop._bs_tips_stripped = true;
    } catch (eTip) {}
    try {
      if (typeof closeBoxHelpPopup === "function") closeBoxHelpPopup();
    } catch (eH) {}
    try {
      if (typeof closeBtnShadeMenu === "function") closeBtnShadeMenu();
    } catch (eS) {}
    try {
      stampBtnShadeAttrs();
      applyBtnShades();
    } catch (eSh) {}
  }

  function highlightBandEditorRow(value) {
    var host = $("bs-bd-edit");
    if (!host) return;
    Array.prototype.forEach.call(host.querySelectorAll(".bs-bd-edit-row"), function (row) {
      row.classList.remove("bs-bm-editing");
    });
    if (!value) return;
    Array.prototype.forEach.call(host.querySelectorAll('.bs-bd-edit-row[data-band-value]'), function (row) {
      if (row.getAttribute("data-band-value") === value) {
        row.classList.add("bs-bm-editing");
      }
    });
  }

  function bandEditorModeList() {
    var out = [];
    var seen = {};
    try {
      if (window.Modes && Array.isArray(Modes.modes)) {
        Modes.modes.forEach(function (m) {
          if (!m || !m.modulation || seen[m.modulation]) return;
          seen[m.modulation] = true;
          out.push({ id: m.modulation, label: m.name || m.modulation });
        });
      }
    } catch (eM) {}
    if (!out.length) {
      (BM_EDIT_MODES || ["am", "nfm", "wfm", "usb", "lsb", "cw"]).forEach(function (m) {
        out.push({ id: m, label: String(m).toUpperCase() });
      });
    }
    return out;
  }

  function fillBandEditorModeSelect(selected) {
    var sel = $("bs-bd-edit-mode");
    if (!sel) return;
    var modes = bandEditorModeList();
    var want = String(selected || "nfm").toLowerCase();
    var html = "";
    var found = false;
    modes.forEach(function (m) {
      if (m.id === want) found = true;
      html += '<option value="' + escapeHtml(m.id) + '"' +
        (m.id === want ? " selected" : "") + ">" + escapeHtml(m.label) + "</option>";
    });
    if (!found && want) {
      html = '<option value="' + escapeHtml(want) + '" selected>' + escapeHtml(want.toUpperCase()) +
        "</option>" + html;
    }
    sel.innerHTML = html;
  }

  function profileEditorMhz(p) {
    var det = lookupProfileDetail(p);
    if (det && det.center_freq > 0) return det.center_freq / 1e6;
    var r = profileFreqRange(p);
    if (!r) return "";
    return (Number(r.lo) + Number(r.hi)) / 2;
  }

  function fillBandEditor(value) {
    ensureProfileFreqCache(function () {
      fillBandEditorDom(value);
    });
  }


  var bandEditBaselineParams = null;
  var bandEditBaselineValue = "";
  var BD_TUNING_STEPS = [1, 10, 20, 50, 100, 500, 1000, 2500, 3000, 5000, 6000, 6250, 8330, 9000, 10000, 12000, 12500, 25000, 50000];

  function syncBandEditAdvancedUi() {
    var on = extraOn("bandEditAdvanced");
    var adv = $("bs-bd-edit-advanced");
    var pop = $("bs-bd-edit-pop");
    var hint = $("bs-bd-edit-adv-hint");
    if (adv) adv.hidden = !on;
    if (pop) pop.classList.toggle("bs-bd-edit-pop-wide", !!on);
    if (hint) hint.hidden = !!on;
  }

  function enableBandEditAdvancedFromPopup() {
    if (!S.extras) S.extras = extrasDefaults();
    S.extras.bandEditAdvanced = true;
    try { saveSettings(); } catch (eS) {}
    var el = $("bs-extra-bandEditAdvanced");
    if (el) el.checked = true;
    try { applyExtrasUi(); } catch (eA) {}
    syncBandEditAdvancedUi();
    var value = $("bs-bd-edit-value") ? String($("bs-bd-edit-value").value || "") : "";
    if (value) {
      try { fillBandEditorDom(value); } catch (eF) {}
    }
    setBandEditorStatus("Full admin fields on — stays on for other band edits (Settings → Extras).");
    try { setStatus("Bands edit · full admin fields enabled."); } catch (eSt) {}
  }

  function readExpHzFromParams(params, id) {
    if (!params) return null;
    var v = params.get(id);
    if (v == null || v === "") return null;
    var n = parseFloat(v);
    var e = parseInt(params.get(id + "-exponent") || "0", 10);
    if (!isFinite(n)) return null;
    if (!isFinite(e)) e = 0;
    return Math.round(n * Math.pow(10, e));
  }

  function setExpParam(params, id, hz) {
    params.set(id, String(Math.round(Number(hz))));
    params.set(id + "-exponent", "0");
  }

  function setOwrxCheckboxParam(params, id, on) {
    params.delete(id);
    params.append(id, "0");
    if (on) params.append(id, "1");
  }

  function collectAdminFormParams(form) {
    var params = new URLSearchParams();
    if (!form) return params;
    var handled = {};
    Array.prototype.forEach.call(form.querySelectorAll("input, select, textarea"), function (el) {
      if (!el.name || el.disabled) return;
      var name = el.name;
      var type = String(el.type || "").toLowerCase();
      if (type === "submit" || type === "button" || type === "file" || type === "image" || type === "reset") return;
      if (handled[name]) return;
      var esc = name.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
      if (type === "checkbox" || (type === "hidden" && form.querySelector('input[type="checkbox"][name="' + esc + '"]'))) {
        var cb = form.querySelector('input[type="checkbox"][name="' + esc + '"]');
        if (cb) {
          handled[name] = true;
          setOwrxCheckboxParam(params, name, !!cb.checked);
          return;
        }
      }
      if (type === "radio") {
        if (!el.checked) return;
        params.append(name, el.value);
        return;
      }
      if (el.tagName === "SELECT" && el.multiple) {
        handled[name] = true;
        Array.prototype.forEach.call(el.selectedOptions || [], function (o) {
          params.append(name, o.value);
        });
        return;
      }
      if (type === "hidden" || type === "text" || type === "number" || el.tagName === "TEXTAREA" || el.tagName === "SELECT") {
        var all = form.querySelectorAll('[name="' + esc + '"]');
        if (all.length > 1) {
          handled[name] = true;
          Array.prototype.forEach.call(all, function (node) {
            if (node.disabled) return;
            var t = String(node.type || "").toLowerCase();
            if (t === "checkbox" || t === "radio") return;
            params.append(name, node.value);
          });
          return;
        }
        params.append(name, el.value);
        return;
      }
      params.append(name, el.value);
    });
    return params;
  }

  function fetchProfileAdminForm(value, done) {
    var parts = splitProfileValue(value);
    if (!parts.device || !parts.profileId) {
      done(new Error("missing"));
      return;
    }
    var url = settingsSdrUrl(parts.device, "profile/" + encodeURIComponent(parts.profileId));
    fetch(url, { credentials: "same-origin", redirect: "follow" }).then(function (res) {
      if (res.status === 401 || res.status === 403) throw new Error("admin");
      if (res.status === 404) throw new Error("notfound");
      if (!res.ok) throw new Error("http-" + res.status);
      return res.text();
    }).then(function (html) {
      var doc = new DOMParser().parseFromString(html, "text/html");
      var form = doc.querySelector("form.settings-body") || doc.querySelector("form");
      if (!form) throw new Error("noform");
      var params = collectAdminFormParams(form);
      if (!params.get("name") && !params.get("center_freq")) throw new Error("empty");
      done(null, { params: params, form: form });
    }).catch(function (err) {
      done(err || new Error("fail"));
    });
  }

  var BD_DS_OPTIONS = [
    { value: "DIRECT_SAMPLING_OFF", label: "Off" },
    { value: "DIRECT_SAMPLING_I", label: "Direct Sampling (I branch)" },
    { value: "DIRECT_SAMPLING_Q", label: "Direct Sampling (Q branch)" }
  ];
  var BD_DS_ALIASES = {
    "0": "DIRECT_SAMPLING_OFF",
    "1": "DIRECT_SAMPLING_I",
    "2": "DIRECT_SAMPLING_Q",
    off: "DIRECT_SAMPLING_OFF",
    i: "DIRECT_SAMPLING_I",
    q: "DIRECT_SAMPLING_Q"
  };
  var BD_GAIN_OPTIONS = [
    { value: "auto", label: "Enable hardware AGC" },
    { value: "manual", label: "Specify manual gain" }
  ];
  /* Same optional keys as stock OptionalSection for rtl_sdr (+ antenna for Soapy). */
  var BD_OPTIONAL_DEFS = [
    { id: "rf_gain", label: "Gain", keys: ["rf_gain-select", "rf_gain-manual"] },
    { id: "ppm", label: "Frequency correction", keys: ["ppm"] },
    { id: "lfo_offset", label: "Oscillator offset", keys: ["lfo_offset", "lfo_offset-exponent"] },
    { id: "initial_squelch_level", label: "Initial squelch level", keys: ["initial_squelch_level"] },
    { id: "initial_nr_level", label: "Initial noise reduction level", keys: ["initial_nr_level"] },
    { id: "waterfall_levels", label: "Waterfall levels", keys: ["waterfall_levels-min", "waterfall_levels-max"] },
    { id: "waterfall_auto_level_default_mode", label: "Automatically adjust waterfall level by default", keys: ["waterfall_auto_level_default_mode"] },
    { id: "bias_tee", label: "Enable Bias-Tee power supply", keys: ["bias_tee"] },
    { id: "iqswap", label: "IQ swap", keys: ["iqswap"] },
    { id: "direct_sampling", label: "Direct Sampling", keys: ["direct_sampling"] },
    { id: "key_locked", label: "Require magic key to switch profile", keys: ["key_locked"] },
    { id: "rig_enabled", label: "Enable sending changes to a standalone transceiver", keys: ["rig_enabled"] },
    { id: "eibi_bookmarks_range", label: "Shortwave bookmarks range", keys: ["eibi_bookmarks_range"] },
    { id: "repeater_range", label: "Repeater bookmarks range", keys: ["repeater_range"] },
    { id: "antenna", label: "Antenna", keys: ["antenna"] }
  ];

  function bdOptionalDef(id) {
    for (var i = 0; i < BD_OPTIONAL_DEFS.length; i++) {
      if (BD_OPTIONAL_DEFS[i].id === id) return BD_OPTIONAL_DEFS[i];
    }
    return null;
  }

  function bdOptionalKeyPresent(params, def) {
    if (!params || !def || !def.keys) return false;
    for (var i = 0; i < def.keys.length; i++) {
      if (params.has(def.keys[i])) return true;
    }
    return false;
  }

  function clearBdOptionalKeys(params, def) {
    if (!params || !def || !def.keys) return;
    def.keys.forEach(function (k) { params.delete(k); });
  }

  function bdOptionalGroupEl(id) {
    var pool = $("bs-bd-edit-opt-pool");
    var active = $("bs-bd-edit-opt-active");
    var sel = '[data-bd-opt="' + String(id).replace(/"/g, "") + '"]';
    return (active && active.querySelector(sel)) || (pool && pool.querySelector(sel)) || null;
  }

  function isBdOptionalActive(id) {
    var g = bdOptionalGroupEl(id);
    var active = $("bs-bd-edit-opt-active");
    return !!(g && active && g.parentNode === active);
  }

  function rebuildBdOptionalSelect() {
    var sel = $("bs-bd-edit-opt-select");
    var pool = $("bs-bd-edit-opt-pool");
    if (!sel || !pool) return;
    var html = "";
    BD_OPTIONAL_DEFS.forEach(function (def) {
      var g = pool.querySelector('[data-bd-opt="' + def.id + '"]');
      if (!g) return;
      html += '<option value="' + escapeHtml(def.id) + '">' + escapeHtml(def.label) + "</option>";
    });
    sel.innerHTML = html || '<option value="">(none left)</option>';
    sel.disabled = !html;
    var addBtn = $("bs-bd-edit-opt-add");
    if (addBtn) addBtn.disabled = !html;
  }

  function syncBandEditOptionalGroups(params) {
    var activeBox = $("bs-bd-edit-opt-active");
    var pool = $("bs-bd-edit-opt-pool");
    if (!activeBox || !pool) return;
    BD_OPTIONAL_DEFS.forEach(function (def) {
      var g = bdOptionalGroupEl(def.id);
      if (!g) return;
      var want = bdOptionalKeyPresent(params, def);
      if (want) {
        if (g.parentNode !== activeBox) activeBox.appendChild(g);
      } else if (g.parentNode !== pool) {
        pool.appendChild(g);
      }
    });
    rebuildBdOptionalSelect();
  }

  function addBandEditOptionalField(id) {
    var def = bdOptionalDef(id);
    var activeBox = $("bs-bd-edit-opt-active");
    var pool = $("bs-bd-edit-opt-pool");
    if (!def || !activeBox || !pool) return;
    var g = pool.querySelector('[data-bd-opt="' + def.id + '"]');
    if (!g) return;
    activeBox.appendChild(g);
    if (def.id === "rf_gain" && $("bs-bd-edit-gain-mode") && !$("bs-bd-edit-gain-mode").value) {
      $("bs-bd-edit-gain-mode").value = "auto";
    }
    if (def.id === "direct_sampling" && $("bs-bd-edit-ds") && !$("bs-bd-edit-ds").value) {
      $("bs-bd-edit-ds").value = "DIRECT_SAMPLING_OFF";
    }
    rebuildBdOptionalSelect();
    setBandEditorStatus("Added optional setting: " + def.label);
  }

  function removeBandEditOptionalField(id) {
    var def = bdOptionalDef(id);
    var activeBox = $("bs-bd-edit-opt-active");
    var pool = $("bs-bd-edit-opt-pool");
    if (!def || !activeBox || !pool) return;
    var g = activeBox.querySelector('[data-bd-opt="' + def.id + '"]');
    if (!g) return;
    Array.prototype.forEach.call(g.querySelectorAll("input, select, textarea"), function (el) {
      var t = String(el.type || "").toLowerCase();
      if (t === "checkbox" || t === "radio") el.checked = false;
      else if (el.tagName === "SELECT") {
        if (el.options && el.options.length) el.selectedIndex = 0;
        else el.value = "";
      } else el.value = "";
    });
    pool.appendChild(g);
    rebuildBdOptionalSelect();
    setBandEditorStatus("Removed optional setting: " + def.label + " (Save to apply).");
  }

  function adminFormSelectInfo(form, name) {
    if (!form || !name) return null;
    var nodes = form.querySelectorAll('select[name="' + name.replace(/\\/g, "\\\\").replace(/"/g, '\\"') + '"]');
    var sel = null;
    Array.prototype.forEach.call(nodes, function (node) {
      if (!sel && !node.disabled) sel = node;
    });
    if (!sel && nodes.length) sel = nodes[0];
    if (!sel || sel.disabled) return null;
    return {
      value: sel.value,
      options: Array.prototype.map.call(sel.options || [], function (o) {
        return { value: o.value, label: String(o.textContent || "").replace(/\s+/g, " ").trim() };
      })
    };
  }

  function adminFormInputValue(form, name) {
    if (!form || !name) return null;
    var esc = name.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
    var el = form.querySelector('input[name="' + esc + '"]:not([disabled]):not([type="hidden"])') ||
      form.querySelector('input[name="' + esc + '"]:not([disabled])') ||
      form.querySelector('textarea[name="' + esc + '"]:not([disabled])');
    if (!el || el.disabled) return null;
    return el.value;
  }

  function adminFormCheckboxOn(form, name) {
    if (!form || !name) return null;
    var esc = name.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
    var cb = form.querySelector('input[type="checkbox"][name="' + esc + '"]:not([disabled])');
    if (!cb) return null;
    return !!cb.checked;
  }

  function fillToolboxSelect(sel, options, want, opts) {
    if (!sel) return;
    opts = opts || {};
    var list = options ? options.slice() : [];
    var v = want == null ? "" : String(want);
    if (opts.aliasMap) {
      if (opts.aliasMap[v] != null) v = String(opts.aliasMap[v]);
      else if (opts.aliasMap[v.toLowerCase()] != null) v = String(opts.aliasMap[v.toLowerCase()]);
    }
    var html = "";
    if (opts.includeUnset !== false) {
      html += '<option value="">' + escapeHtml(opts.unsetLabel || "(unset)") + "</option>";
    }
    var found = !v;
    list.forEach(function (o) {
      if (!o) return;
      var ov = String(o.value);
      if (ov === v) found = true;
      html += '<option value="' + escapeHtml(ov) + '"' +
        (ov === v ? " selected" : "") + ">" + escapeHtml(o.label || ov) + "</option>";
    });
    if (v && !found) {
      html += '<option value="' + escapeHtml(v) + '" selected>' + escapeHtml(v) + "</option>";
    }
    sel.innerHTML = html;
    if (v) sel.value = v;
  }

  function fillBandEditorTuningStep(selected, form) {
    var sel = $("bs-bd-edit-step");
    if (!sel) return;
    var info = adminFormSelectInfo(form, "tuning_step");
    if (info && info.options && info.options.length) {
      fillToolboxSelect(sel, info.options, info.value, { includeUnset: false });
      return;
    }
    var want = String(selected == null || selected === "" ? 1000 : selected);
    fillToolboxSelect(sel, BD_TUNING_STEPS.map(function (n) {
      return { value: String(n), label: n + " Hz" };
    }), want, { includeUnset: false });
  }

  function mhzFromHz(hz) {
    if (!(hz > 0) || !isFinite(hz)) return "";
    return Math.round((hz / 1e6) * 1e6) / 1e6;
  }

  function fillBandEditorAdvancedFromParams(params, form) {
    if (!params) return;
    var startHz = readExpHzFromParams(params, "start_freq");
    var samp = readExpHzFromParams(params, "samp_rate");
    var lfo = readExpHzFromParams(params, "lfo_offset");
    if ($("bs-bd-edit-start-mhz")) {
      $("bs-bd-edit-start-mhz").value = startHz ? mhzFromHz(startHz) : "";
    }
    if ($("bs-bd-edit-samp")) {
      $("bs-bd-edit-samp").value = samp > 0 ? samp : "";
    }
    fillBandEditorTuningStep(params.get("tuning_step"), form);
    if ($("bs-bd-edit-ppm")) {
      var ppm = adminFormInputValue(form, "ppm");
      $("bs-bd-edit-ppm").value = ppm != null ? ppm : (params.has("ppm") ? (params.get("ppm") || "") : "");
    }
    if ($("bs-bd-edit-lfo")) {
      $("bs-bd-edit-lfo").value = lfo != null && isFinite(lfo) ? lfo : "";
    }
    if ($("bs-bd-edit-squelch")) {
      var sq = adminFormInputValue(form, "initial_squelch_level");
      $("bs-bd-edit-squelch").value = sq != null ? sq :
        (params.has("initial_squelch_level") ? (params.get("initial_squelch_level") || "") : "");
    }
    if ($("bs-bd-edit-nr")) {
      var nr = adminFormInputValue(form, "initial_nr_level");
      $("bs-bd-edit-nr").value = nr != null ? nr :
        (params.has("initial_nr_level") ? (params.get("initial_nr_level") || "") : "");
    }
    if ($("bs-bd-edit-wf-min")) {
      var wfMin = adminFormInputValue(form, "waterfall_levels-min");
      $("bs-bd-edit-wf-min").value = wfMin != null ? wfMin :
        (params.has("waterfall_levels-min") ? (params.get("waterfall_levels-min") || "") : "");
    }
    if ($("bs-bd-edit-wf-max")) {
      var wfMax = adminFormInputValue(form, "waterfall_levels-max");
      $("bs-bd-edit-wf-max").value = wfMax != null ? wfMax :
        (params.has("waterfall_levels-max") ? (params.get("waterfall_levels-max") || "") : "");
    }
    if ($("bs-bd-edit-wf-auto")) {
      var wfAuto = adminFormCheckboxOn(form, "waterfall_auto_level_default_mode");
      $("bs-bd-edit-wf-auto").checked = wfAuto != null ? wfAuto :
        params.getAll("waterfall_auto_level_default_mode").indexOf("1") >= 0;
    }
    if ($("bs-bd-edit-eibi")) {
      var eibi = adminFormInputValue(form, "eibi_bookmarks_range");
      $("bs-bd-edit-eibi").value = eibi != null ? eibi :
        (params.has("eibi_bookmarks_range") ? (params.get("eibi_bookmarks_range") || "") : "");
    }
    if ($("bs-bd-edit-repeater")) {
      var rptr = adminFormInputValue(form, "repeater_range");
      $("bs-bd-edit-repeater").value = rptr != null ? rptr :
        (params.has("repeater_range") ? (params.get("repeater_range") || "") : "");
    }
    if ($("bs-bd-edit-bias")) {
      var bias = adminFormCheckboxOn(form, "bias_tee");
      $("bs-bd-edit-bias").checked = bias != null ? bias : params.getAll("bias_tee").indexOf("1") >= 0;
    }
    if ($("bs-bd-edit-iqswap")) {
      var iq = adminFormCheckboxOn(form, "iqswap");
      $("bs-bd-edit-iqswap").checked = iq != null ? iq : params.getAll("iqswap").indexOf("1") >= 0;
    }
    if ($("bs-bd-edit-keylock")) {
      var kl = adminFormCheckboxOn(form, "key_locked");
      $("bs-bd-edit-keylock").checked = kl != null ? kl : params.getAll("key_locked").indexOf("1") >= 0;
    }
    if ($("bs-bd-edit-rig")) {
      var rig = adminFormCheckboxOn(form, "rig_enabled");
      $("bs-bd-edit-rig").checked = rig != null ? rig : params.getAll("rig_enabled").indexOf("1") >= 0;
    }
    if ($("bs-bd-edit-antenna")) {
      var ant = adminFormInputValue(form, "antenna");
      $("bs-bd-edit-antenna").value = ant != null ? ant :
        (params.has("antenna") ? (params.get("antenna") || "") : "");
    }
    var dsInfo = adminFormSelectInfo(form, "direct_sampling");
    fillToolboxSelect(
      $("bs-bd-edit-ds"),
      (dsInfo && dsInfo.options.length) ? dsInfo.options : BD_DS_OPTIONS,
      dsInfo ? dsInfo.value : (params.get("direct_sampling") || "DIRECT_SAMPLING_OFF"),
      { includeUnset: false, aliasMap: BD_DS_ALIASES }
    );
    var gainInfo = adminFormSelectInfo(form, "rf_gain-select");
    fillToolboxSelect(
      $("bs-bd-edit-gain-mode"),
      (gainInfo && gainInfo.options.length) ? gainInfo.options : BD_GAIN_OPTIONS,
      gainInfo ? gainInfo.value : (params.get("rf_gain-select") || "auto"),
      { includeUnset: false }
    );
    if ($("bs-bd-edit-gain")) {
      var gainManual = adminFormInputValue(form, "rf_gain-manual");
      $("bs-bd-edit-gain").value = gainManual != null ? gainManual :
        (params.get("rf_gain-manual") != null ? params.get("rf_gain-manual") : "");
    }
    var modeInfo = adminFormSelectInfo(form, "start_mod");
    if (modeInfo && modeInfo.options && modeInfo.options.length && $("bs-bd-edit-mode")) {
      fillToolboxSelect($("bs-bd-edit-mode"), modeInfo.options, modeInfo.value, { includeUnset: false });
    }
    try { syncBandEditOptionalGroups(params); } catch (eOpt) {}
  }

  function overlayAdvancedFieldsOntoParams(params, baseline) {
    if (!extraOn("bandEditAdvanced")) return;
    var startRaw = $("bs-bd-edit-start-mhz") ? $("bs-bd-edit-start-mhz").value : "";
    var startMhz = parseFloat(startRaw);
    if (startMhz > 0 && isFinite(startMhz)) {
      setExpParam(params, "start_freq", Math.round(startMhz * 1e6));
    }
    var sampRaw = $("bs-bd-edit-samp") ? $("bs-bd-edit-samp").value : "";
    var samp = parseInt(sampRaw, 10);
    if (samp > 0 && isFinite(samp)) {
      setExpParam(params, "samp_rate", samp);
    }
    if ($("bs-bd-edit-step") && $("bs-bd-edit-step").value) {
      params.set("tuning_step", String($("bs-bd-edit-step").value));
    }
    function optNum(id, elId) {
      var el = $(elId);
      if (!el) return;
      var raw = String(el.value || "").trim();
      if (!raw) {
        params.delete(id);
        params.delete(id + "-exponent");
        return;
      }
      var n = parseFloat(raw);
      if (!isFinite(n)) return;
      params.set(id, String(n));
    }
    function optExp(id, elId) {
      var el = $(elId);
      if (!el) return;
      var raw = String(el.value || "").trim();
      if (!raw) {
        params.delete(id);
        params.delete(id + "-exponent");
        return;
      }
      var n = parseFloat(raw);
      if (!isFinite(n)) return;
      setExpParam(params, id, n);
    }
    function optCheck(id, elId) {
      var el = $(elId);
      if (!el) return;
      setOwrxCheckboxParam(params, id, !!el.checked);
    }

    BD_OPTIONAL_DEFS.forEach(function (def) {
      if (!isBdOptionalActive(def.id)) {
        clearBdOptionalKeys(params, def);
        return;
      }
      if (def.id === "ppm") optNum("ppm", "bs-bd-edit-ppm");
      else if (def.id === "lfo_offset") optExp("lfo_offset", "bs-bd-edit-lfo");
      else if (def.id === "initial_squelch_level") optNum("initial_squelch_level", "bs-bd-edit-squelch");
      else if (def.id === "initial_nr_level") optNum("initial_nr_level", "bs-bd-edit-nr");
      else if (def.id === "eibi_bookmarks_range") optNum("eibi_bookmarks_range", "bs-bd-edit-eibi");
      else if (def.id === "repeater_range") optNum("repeater_range", "bs-bd-edit-repeater");
      else if (def.id === "waterfall_auto_level_default_mode") {
        optCheck("waterfall_auto_level_default_mode", "bs-bd-edit-wf-auto");
      } else if (def.id === "bias_tee") optCheck("bias_tee", "bs-bd-edit-bias");
      else if (def.id === "iqswap") optCheck("iqswap", "bs-bd-edit-iqswap");
      else if (def.id === "key_locked") optCheck("key_locked", "bs-bd-edit-keylock");
      else if (def.id === "rig_enabled") optCheck("rig_enabled", "bs-bd-edit-rig");
      else if (def.id === "waterfall_levels") {
        var wfMin = $("bs-bd-edit-wf-min") ? String($("bs-bd-edit-wf-min").value || "").trim() : "";
        var wfMax = $("bs-bd-edit-wf-max") ? String($("bs-bd-edit-wf-max").value || "").trim() : "";
        params.set("waterfall_levels-min", wfMin !== "" ? wfMin : "0");
        params.set("waterfall_levels-max", wfMax !== "" ? wfMax : "0");
      } else if (def.id === "antenna") {
        var ant = $("bs-bd-edit-antenna") ? String($("bs-bd-edit-antenna").value || "").trim() : "";
        if (ant) params.set("antenna", ant);
        else params.delete("antenna");
      } else if (def.id === "direct_sampling") {
        var ds = $("bs-bd-edit-ds") ? String($("bs-bd-edit-ds").value || "") : "";
        if (ds) params.set("direct_sampling", ds);
        else params.set("direct_sampling", "DIRECT_SAMPLING_OFF");
      } else if (def.id === "rf_gain") {
        var mode = $("bs-bd-edit-gain-mode") ? String($("bs-bd-edit-gain-mode").value || "") : "auto";
        if (mode === "manual") {
          params.set("rf_gain-select", "manual");
          var g = $("bs-bd-edit-gain") ? String($("bs-bd-edit-gain").value || "").trim() : "";
          if (g !== "") params.set("rf_gain-manual", g);
          else if (baseline && baseline.get("rf_gain-manual") != null) {
            params.set("rf_gain-manual", baseline.get("rf_gain-manual"));
          } else {
            params.set("rf_gain-manual", "0");
          }
        } else {
          params.set("rf_gain-select", "auto");
          params.delete("rf_gain-manual");
        }
      }
    });
  }

  function updateOpenwebrxProfile(value, body, done) {
    var parts = splitProfileValue(value);
    if (!parts.device || !parts.profileId) {
      done(new Error("missing"));
      return;
    }
    var url = settingsSdrUrl(parts.device, "profile/" + encodeURIComponent(parts.profileId));
    fetch(url, {
      method: "POST",
      credentials: "same-origin",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        "X-Requested-With": "XMLHttpRequest"
      },
      body: typeof body === "string" ? body : String(body || ""),
      redirect: "manual"
    }).then(function (res) {
      if (res.status === 403) throw new Error("admin");
      if (res.status === 404) throw new Error("notfound");
      if (res.type === "opaqueredirect" || (res.status >= 300 && res.status < 400) || res.ok) {
        done(null);
        return;
      }
      throw new Error("http-" + res.status);
    }).catch(function (err) {
      done(err || new Error("fail"));
    });
  }

  function fillBandEditorDom(value) {
    var list = profiles();
    var p = null;
    for (var i = 0; i < list.length; i++) {
      if (list[i].value === value) { p = list[i]; break; }
    }
    if (!p) {
      setBandEditorStatus("Band not found.");
      return;
    }
    var meta = bandMetaFor(value) || {};
    var det = lookupProfileDetail(p);
    var mhz = profileEditorMhz(p);
    if ($("bs-bd-edit-value")) $("bs-bd-edit-value").value = value;
    if ($("bs-bd-edit-name")) $("bs-bd-edit-name").value = p.label || "";
    if ($("bs-bd-edit-id")) {
      $("bs-bd-edit-id").textContent = profileIdDisplay(p);
      $("bs-bd-edit-id").title = p.id || "";
    }
    if ($("bs-bd-edit-mhz")) {
      $("bs-bd-edit-mhz").value = mhz === "" || !isFinite(mhz) ? "" :
        (Math.round(mhz * 1e6) / 1e6);
    }
    fillBandEditorModeSelect(guessMode(p.id));
    if ($("bs-bd-edit-span")) {
      if (det && det.sample_rate > 0) {
        $("bs-bd-edit-span").textContent = "±" +
          (Math.round((det.sample_rate / 2 / 1e3) * 10) / 10) + " kHz span";
      } else {
        $("bs-bd-edit-span").textContent = profileFreqLabel(p);
      }
    }
    if ($("bs-bd-edit-alias")) $("bs-bd-edit-alias").value = meta.alias || "";
    if ($("bs-bd-edit-note")) $("bs-bd-edit-note").value = meta.note || "";
    if ($("bs-bd-edit-hide")) $("bs-bd-edit-hide").checked = !!meta.hidden;
    var order = ensureBandOrderComplete();
    var idx = order.indexOf(value);
    bandEditBaselineParams = null;
    bandEditBaselineValue = value;
    syncBandEditAdvancedUi();
    try { syncBandEditOptionalGroups(null); } catch (eOpt0) {}
    setBandEditorStatus(
      (idx >= 0 ? ("Order " + (idx + 1) + "/" + order.length + " · ") : "") +
      "Loading OpenWebRX profile fields…"
    );
    highlightBandEditorRow(value);
    openBandEditPopup("Edit band");
    try {
      if ($("bs-bd-edit-name")) {
        $("bs-bd-edit-name").focus();
        $("bs-bd-edit-name").select();
      }
    } catch (eF) {}
    fetchProfileAdminForm(value, function (err, result) {
      if ($("bs-bd-edit-value") && String($("bs-bd-edit-value").value || "") !== value) return;
      if (err && err.message === "admin") {
        setBandEditorStatus(
          (idx >= 0 ? ("Order " + (idx + 1) + "/" + order.length + " · ") : "") +
          "Admin login required to load/save OpenWebRX fields. Alias / hide / note still work."
        );
        return;
      }
      if (err) {
        setBandEditorStatus(
          (idx >= 0 ? ("Order " + (idx + 1) + "/" + order.length + " · ") : "") +
          "Could not load admin form — Save may not preserve optional fields. " +
          (err.message || "")
        );
        return;
      }
      var params = result && result.params;
      var form = result && result.form;
      if (!params) {
        setBandEditorStatus("Could not load admin form fields.");
        return;
      }
      bandEditBaselineParams = params;
      bandEditBaselineValue = value;
      var cHz = readExpHzFromParams(params, "center_freq");
      var sHz = readExpHzFromParams(params, "start_freq");
      var samp = readExpHzFromParams(params, "samp_rate");
      if (cHz > 0 && $("bs-bd-edit-mhz")) $("bs-bd-edit-mhz").value = mhzFromHz(cHz);
      if (params.get("name") && $("bs-bd-edit-name")) $("bs-bd-edit-name").value = params.get("name");
      if (params.get("start_mod")) fillBandEditorModeSelect(params.get("start_mod"));
      if (samp > 0 && $("bs-bd-edit-span")) {
        $("bs-bd-edit-span").textContent = "±" +
          (Math.round((samp / 2 / 1e3) * 10) / 10) + " kHz span";
      }
      fillBandEditorAdvancedFromParams(params, form);
      setBandEditorStatus(
        (idx >= 0 ? ("Order " + (idx + 1) + "/" + order.length + " · ") : "") +
        "Name / centre / mode → OpenWebRX (admin). Alias / hide / note → this browser." +
        (extraOn("bandEditAdvanced")
          ? " Full admin fields + Additional optional settings."
          : "") +
        (sHz > 0 && cHz > 0 && Math.abs(sHz - cHz) > 1
          ? (" Initial tune " + mhzFromHz(sHz) + " MHz.")
          : "")
      );
      try {
        stripNativeTitles($("bs-bd-edit-pop"));
        if ($("bs-bd-edit-pop")) $("bs-bd-edit-pop")._bs_tips_stripped = true;
      } catch (eTip) {}
    });
  }

  function renameListboxProfile(value, newName) {
    var sel = $("openwebrx-sdr-profiles-listbox");
    if (!sel) return;
    Array.prototype.forEach.call(sel.options || [], function (opt) {
      if (opt && opt.value === value) opt.text = newName;
    });
  }

  function saveBandFromEditor() {
    var value = $("bs-bd-edit-value") ? String($("bs-bd-edit-value").value || "") : "";
    if (!value) {
      setBandEditorStatus("No band selected — click edit on a row.");
      return;
    }
    var list = profiles();
    var p = null;
    for (var i = 0; i < list.length; i++) {
      if (list[i].value === value) { p = list[i]; break; }
    }
    if (!p) {
      setBandEditorStatus("Band not found.");
      return;
    }
    var alias = $("bs-bd-edit-alias") ? String($("bs-bd-edit-alias").value || "").trim() : "";
    var note = $("bs-bd-edit-note") ? String($("bs-bd-edit-note").value || "").trim() : "";
    var hidden = $("bs-bd-edit-hide") ? !!$("bs-bd-edit-hide").checked : false;
    var newName = $("bs-bd-edit-name") ? String($("bs-bd-edit-name").value || "").trim() : "";
    var mhzRaw = $("bs-bd-edit-mhz") ? $("bs-bd-edit-mhz").value : "";
    var newMode = $("bs-bd-edit-mode") ? String($("bs-bd-edit-mode").value || "").trim() : "";
    if (!newName) {
      setBandEditorStatus("Name is required.");
      return;
    }
    var mhz = parseFloat(mhzRaw);
    if (!(mhz > 0) || !isFinite(mhz)) {
      setBandEditorStatus("Enter a valid centre frequency in MHz.");
      return;
    }
    if (!newMode) newMode = guessMode(p.id);

    writeBandMeta(value, { alias: alias, note: note, hidden: hidden });

    function finishLocalOnly(msg) {
      fillBands();
      fillBandsEdit();
      highlightBandEditorRow(value);
      setBandEditorStatus(msg);
      setStatus("Band local edits saved.");
    }

    var detQuick = lookupProfileDetail(p) || {};
    var oldMhzQuick = detQuick.center_freq > 0 ? detQuick.center_freq / 1e6 : profileEditorMhz(p);
    var oldNameQuick = String(p.label || "");
    var oldModeQuick = guessMode(p.id);
    var needServerQuick = extraOn("bandEditAdvanced") ||
      newName !== oldNameQuick ||
      newMode !== oldModeQuick ||
      !(isFinite(oldMhzQuick)) ||
      Math.abs(mhz - oldMhzQuick) > 1e-7;
    if (!needServerQuick) {
      finishLocalOnly("Saved local edits" + (alias ? (" · alias “" + alias + "”") : "") +
        (hidden ? " · hidden" : "") + ".");
      return;
    }

    function doServerSave(baseline) {
      var params = new URLSearchParams(baseline ? baseline.toString() : "");
      var oldCenter = readExpHzFromParams(baseline, "center_freq");
      var oldStart = readExpHzFromParams(baseline, "start_freq");
      var oldName = baseline && baseline.get("name") != null ? String(baseline.get("name")) : String(p.label || "");
      var oldMode = baseline && baseline.get("start_mod") ? String(baseline.get("start_mod")) : guessMode(p.id);
      var centerHz = Math.round(mhz * 1e6);
      params.set("name", newName);
      setExpParam(params, "center_freq", centerHz);
      params.set("start_mod", newMode);
      if (extraOn("bandEditAdvanced")) {
        overlayAdvancedFieldsOntoParams(params, baseline);
      } else if (oldStart == null || (oldCenter != null && Math.abs(oldStart - oldCenter) < 1)) {
        setExpParam(params, "start_freq", centerHz);
      }
      if (!params.get("tuning_step")) {
        params.set("tuning_step", (baseline && baseline.get("tuning_step")) || "1000");
      }
      if (!params.get("samp_rate")) {
        var det = lookupProfileDetail(p) || {};
        var samp = det.sample_rate > 0 ? det.sample_rate : 2400000;
        setExpParam(params, "samp_rate", samp);
      }
      if (!params.get("start_freq")) {
        setExpParam(params, "start_freq", centerHz);
      }

      var sampOut = readExpHzFromParams(params, "samp_rate") || 2400000;
      var nameChanged = newName !== oldName;
      var mhzChanged = !(oldCenter > 0) || Math.abs(centerHz - oldCenter) > 0;
      var modeChanged = newMode !== oldMode;
      var advancedTouched = extraOn("bandEditAdvanced");
      if (!nameChanged && !mhzChanged && !modeChanged && !advancedTouched) {
        finishLocalOnly("Saved local edits" + (alias ? (" · alias “" + alias + "”") : "") +
          (hidden ? " · hidden" : "") + ".");
        return;
      }

      setBandEditorStatus("Saving OpenWebRX profile…");
      setStatus("Saving profile “" + newName + "”…");
      updateOpenwebrxProfile(value, params.toString(), function (err) {
        if (err && err.message === "admin") {
          setBandEditorStatus("Admin login required to change OpenWebRX profile fields.");
          setStatus("Log in as admin (OpenWebRX Settings), then Save again. Local alias/hide/note were still saved.");
          try { toast("Admin login required to edit SDR profiles."); } catch (eT) {}
          fillBands();
          fillBandsEdit();
          return;
        }
        if (err) {
          setBandEditorStatus("OpenWebRX save failed — local alias/hide/note kept.");
          setStatus("Could not update profile (" + (err.message || err) + ").");
          fillBands();
          fillBandsEdit();
          return;
        }
        renameListboxProfile(value, newName);
        rememberProfileDetail(newName, {
          name: newName,
          center_freq: centerHz,
          sample_rate: sampOut
        });
        rememberProfileDetail(p.id, {
          name: newName,
          center_freq: centerHz,
          sample_rate: sampOut
        });
        rememberProfileFreqName(newName, profileFreqFromCenter(centerHz, sampOut));
        rememberProfileFreqName(p.id, profileFreqFromCenter(centerHz, sampOut));
        profileFreqCacheAt = 0;
        bandEditBaselineParams = null;
        fillBands();
        fillBandsEdit();
        highlightBandEditorRow(value);
        fillBandEditorDom(value);
        setBandEditorStatus("Saved OpenWebRX profile" +
          (alias ? " · local alias set" : "") +
          (hidden ? " · hidden" : "") +
          ". Hard-refresh if the radio’s own list looks stale.");
        setStatus("Updated profile “" + newName + "”.");
        try { toast("Profile updated."); } catch (eT2) {}
      });
    }

    if (bandEditBaselineParams && bandEditBaselineValue === value) {
      doServerSave(bandEditBaselineParams);
      return;
    }
    setBandEditorStatus("Loading OpenWebRX profile before save…");
    fetchProfileAdminForm(value, function (err, result) {
      if (err && err.message === "admin") {
        setBandEditorStatus("Admin login required to change name / freq / mode.");
        setStatus("Log in as admin (OpenWebRX Settings), then Save again. Local alias/hide/note were still saved.");
        try { toast("Admin login required to edit SDR profiles."); } catch (eT) {}
        fillBands();
        fillBandsEdit();
        return;
      }
      var params = result && result.params;
      if (err || !params) {
        setBandEditorStatus("Could not load admin form — refusing to save (would risk wiping optional fields). Local alias/hide/note kept.");
        setStatus("Band profile save blocked — open OpenWebRX Settings while logged in as admin, then retry.");
        fillBands();
        fillBandsEdit();
        return;
      }
      bandEditBaselineParams = params;
      bandEditBaselineValue = value;
      doServerSave(params);
    });
  }

  function clearBandFromEditor() {
    var value = $("bs-bd-edit-value") ? String($("bs-bd-edit-value").value || "") : "";
    if (!value) return;
    clearOneBandEdit(value);
    if ($("bs-bd-edit-alias")) $("bs-bd-edit-alias").value = "";
    if ($("bs-bd-edit-note")) $("bs-bd-edit-note").value = "";
    if ($("bs-bd-edit-hide")) $("bs-bd-edit-hide").checked = false;
    highlightBandEditorRow(value);
    setBandEditorStatus("Cleared alias, note, and hide for this band.");
    setStatus("Cleared edits for this band.");
  }

  function splitProfileValue(value) {
    var s = String(value || "");
    var i = s.indexOf("|");
    if (i < 0) {
      return { device: currentSdrDeviceId() || "", profileId: s };
    }
    return { device: s.slice(0, i), profileId: s.slice(i + 1) };
  }

  function settingsSdrUrl(device, suffix) {
    var path = "settings/sdr/" + encodeURIComponent(device) + "/" + suffix;
    try {
      var base = (document.querySelector("base") && document.querySelector("base").href) || (location.origin + "/");
      var a = document.querySelector('a[href*="settings/sdr/"]');
      if (a && a.href) {
        var m = a.href.match(/^(.*\/settings\/sdr\/)[^/]+/);
        if (m) return m[1] + encodeURIComponent(device) + "/" + suffix;
      }
      return new URL(path, base).pathname;
    } catch (e0) {
      return "/" + path;
    }
  }

  function removeProfileOptionFromListbox(value) {
    var sel = $("openwebrx-sdr-profiles-listbox");
    if (!sel) return;
    var opts = sel.options ? Array.prototype.slice.call(sel.options) : [];
    opts.forEach(function (opt) {
      if (opt && opt.value === value && opt.parentNode) {
        try { opt.parentNode.removeChild(opt); } catch (eRm) {}
      }
    });
  }

  function forgetBandLocalState(value) {
    var map = bandMetaMap();
    if (map[value]) {
      delete map[value];
      S.bandMeta = map;
    }
    if (Array.isArray(S.bandOrder)) {
      S.bandOrder = S.bandOrder.filter(function (v) { return v !== value; });
    }
    if (Array.isArray(S.selected)) {
      S.selected = S.selected.filter(function (v) { return v !== value; });
    }
    saveSettings();
  }

  /** Permanently delete an OpenWebRX SDR profile (admin). Same endpoint as Settings → Remove profile. */
  function deleteOpenwebrxProfile(value, done) {
    var parts = splitProfileValue(value);
    if (!parts.device || !parts.profileId) {
      done(new Error("missing"));
      return;
    }
    var url = settingsSdrUrl(parts.device, "deleteprofile/" + encodeURIComponent(parts.profileId));
    fetch(url, {
      method: "GET",
      credentials: "same-origin",
      headers: { "X-Requested-With": "XMLHttpRequest" },
      redirect: "manual"
    }).then(function (res) {
      if (res.status === 403) throw new Error("admin");
      if (res.status === 404) throw new Error("notfound");
      if (res.type === "opaqueredirect" || (res.status >= 300 && res.status < 400) || res.ok) {
        done(null);
        return;
      }
      throw new Error("http-" + res.status);
    }).catch(function (err) {
      done(err || new Error("fail"));
    });
  }

  function deleteBandProfile(value, opts) {
    opts = opts || {};
    if (!value) return;
    if (typeof isPublicReceiver === "function" && isPublicReceiver() &&
        typeof publicAllowsFeature === "function" && !publicAllowsFeature("clearData")) {
      setStatus("Deleting SDR profiles is blocked on this public receiver.");
      setBandEditorStatus("Delete blocked (public allowlist).");
      return;
    }
    var list = profiles();
    var p = null;
    for (var i = 0; i < list.length; i++) {
      if (list[i].value === value) { p = list[i]; break; }
    }
    var label = (p && (p.label || p.id)) || value;
    if (!window.confirm(
      "Permanently delete OpenWebRX profile?\n\n" +
      "Name: " + label + "\n" +
      "Id: " + (p ? profileIdDisplay(p) : value) + "\n\n" +
      "This removes it from the radio’s settings (admin login required).\n" +
      "Cannot undo from Toolbox.\n\n" +
      "Tip: use Hide from list to keep the profile but hide it in Toolbox only."
    )) return;

    setBandEditorStatus("Deleting…");
    setStatus("Deleting profile “" + label + "”…");
    deleteOpenwebrxProfile(value, function (err) {
      if (err && err.message === "admin") {
        setBandEditorStatus("Admin login required to delete profiles.");
        setStatus("Log in as admin (OpenWebRX Settings), then try Delete again.");
        try { toast("Admin login required to delete SDR profiles."); } catch (eT) {}
        return;
      }
      if (err && err.message === "notfound") {
        setBandEditorStatus("Profile not found on server — refreshing list.");
      } else if (err) {
        setBandEditorStatus("Delete failed — try OpenWebRX Settings → SDR.");
        setStatus("Could not delete profile (" + (err.message || err) + ").");
        return;
      }
      forgetBandLocalState(value);
      removeProfileOptionFromListbox(value);
      closeBandEditPopup();
      fillBands();
      fillBandsEdit();
      setStatus("Deleted profile “" + label + "”. If it still appears, hard-refresh (Ctrl+Shift+R).");
      try { toast("Profile deleted."); } catch (eT2) {}
    });
  }

  function deleteBandFromEditor() {
    var value = $("bs-bd-edit-value") ? String($("bs-bd-edit-value").value || "") : "";
    if (!value) {
      setBandEditorStatus("No band selected — click edit on a row.");
      return;
    }
    deleteBandProfile(value);
  }

  function moveBandFromEditor(dir) {
    var value = $("bs-bd-edit-value") ? String($("bs-bd-edit-value").value || "") : "";
    if (!value) return;
    if (dir === "top" || dir === "bottom") {
      var order = ensureBandOrderComplete();
      var i = order.indexOf(value);
      if (i < 0) return;
      order.splice(i, 1);
      if (dir === "top") order.unshift(value);
      else order.push(value);
      S.bandOrder = order;
      saveSettings();
      fillBandsEdit();
      fillBands();
    } else {
      moveBandOrder(value, dir < 0 ? -1 : 1);
    }
    fillBandEditor(value);
  }

  function fillBandsEdit() {
    var host = $("bs-bd-edit");
    if (!host) return;
    ensureProfileFreqCache(function () {
      fillBandsEditDom();
    });
  }

  function fillBandsEditDom() {
    var host = $("bs-bd-edit");
    if (!host) return;
    var list = orderedProfiles(true);
    if (!list.length) {
      host.innerHTML = '<p class="bs-empty">No band profiles yet. Wait for the radio to connect, or use <b>Bands packs</b> to create them.</p>';
      return;
    }
    ensureBandOrderComplete();
    var editing = $("bs-bd-edit-value") ? String($("bs-bd-edit-value").value || "") : "";
    var html = '<ul class="bs-bm-ul bs-bd-edit-ul">';
    list.forEach(function (p, idx) {
      var meta = bandMetaFor(p.value) || {};
      var alias = String(meta.alias || "").trim();
      var shown = alias || p.label || p.id || p.value;
      var note = String(meta.note || "").trim();
      html += '<li class="bs-bm-row bs-bd-edit-row' +
        (meta.hidden ? " bs-band-edit-hidden" : "") +
        (editing && editing === p.value ? " bs-bm-editing" : "") +
        '" data-band-value="' + escapeHtml(p.value) +
        '" title="Click edit (or the row) to change OpenWebRX name, centre MHz, mode (admin), plus local alias / hide / note / order. Del removes the profile.">' +
        '<span class="bs-bd-edit-ord bs-bd-edit-extra">' +
        '<button type="button" class="bs-tiny bs-btn-util" data-band-move="' + escapeHtml(p.value) +
        '" data-dir="-1" title="Move earlier in Scan bands order (this browser).">↑</button>' +
        '<button type="button" class="bs-tiny bs-btn-util" data-band-move="' + escapeHtml(p.value) +
        '" data-dir="1" title="Move later in Scan bands order (this browser).">↓</button>' +
        '<span class="bs-hint" title="Position in scan / list order.">' + (idx + 1) + "</span>" +
        "</span>" +
        '<span class="bs-bm-name" title="Display name (alias if set, else OpenWebRX name).">' + escapeHtml(shown) + "</span>" +
        (alias ? '<span class="bs-bm-auto bs-bd-edit-extra" title="Toolbox-only alias — OpenWebRX name is unchanged until you edit Name in the popup.">alias</span>' : "") +
        (meta.hidden ? '<span class="bs-bm-load bs-bd-edit-extra" title="Hidden from Band list and presets in this browser.">hidden</span>' : "") +
        (note ? '<span class="bs-hint bs-bd-edit-extra" title="' + escapeHtml(note) + '">note</span>' : "") +
        '<span class="bs-bm-mhz bs-bd-edit-extra" title="OpenWebRX profile id (not editable).">' + escapeHtml(profileIdDisplay(p)) + "</span>" +
        '<span class="bs-hint bs-bd-edit-freq" title="Centre / coverage and mode (from status or profile).">' +
        escapeHtml(profileFreqLabel(p)) + " · " +
        escapeHtml(profileModeLabel(p)) + "</span>" +
        '<button type="button" class="bs-tiny bs-btn-util" data-band-edit="' + escapeHtml(p.value) +
        '" title="Open editor: Name / Centre MHz / Mode (admin), Alias / Hide / Note (this browser), order, or Delete.">edit</button>' +
        '<button type="button" class="bs-tiny bs-btn-clear bs-bd-edit-extra" data-band-del="' + escapeHtml(p.value) +
        '" title="Permanently delete this OpenWebRX SDR profile (admin login required). Cannot undo from Toolbox — use Hide to keep it off the list only.">del</button>' +
        "</li>";
    });
    html += "</ul>";
    host.innerHTML = html;
    try { stripNativeTitles(host); } catch (eSt) {}
    try { applyBdEditMinimalView(); } catch (eMin) {}
  }

  function applyBdEditMinimalView() {
    var on = !!S.bdEditMinimal;
    var box = $("bs-bd-edit-box");
    var wrap = $("bs-bd-edit-wrap");
    var host = $("bs-bd-edit");
    var pane = document.querySelector('.bs-bd-subpane[data-bd-sub="edit"]');
    if (box) box.classList.toggle("bs-bd-edit-min", on);
    if (wrap) wrap.classList.toggle("bs-bd-edit-min", on);
    if (host) host.classList.toggle("bs-bd-edit-min", on);
    if (pane) pane.classList.toggle("bs-bd-edit-min", on);
    var btn = $("bs-bd-edit-minimal");
    if (btn) {
      btn.classList.toggle("bs-on", on);
      btn.setAttribute("aria-pressed", on ? "true" : "false");
      btn.textContent = on ? "Full view" : "Minimal";
      btn.title = on
        ? "Show the full Edit bands list (order, id, badges, clear, del)."
        : "Minimal list: name, freq, and edit only.";
    }
  }

  function toggleBdEditMinimalView() {
    S.bdEditMinimal = !S.bdEditMinimal;
    try { saveSettings(); } catch (eS) {}
    applyBdEditMinimalView();
    setStatus(S.bdEditMinimal
      ? "Edit bands · minimal list (name / freq / edit)."
      : "Edit bands · full list.");
  }

  function bandFilterQuery() {
    return (($("bs-filter") && $("bs-filter").value) || "").trim().toLowerCase();
  }

  function bandRowVisible(el) {
    if (!el) return false;
    var row = el.closest ? el.closest("tr") : null;
    if (!row) return true;
    if (row.style.display === "none") return false;
    try {
      if (window.getComputedStyle && window.getComputedStyle(row).display === "none") return false;
    } catch (e) {}
    return true;
  }

  function selectedValues(opts) {
    opts = opts || {};
    var box = $("bs-bands");
    if (!box) return [];
    var out = [];
    Array.prototype.forEach.call(box.querySelectorAll("input[type=checkbox]"), function (el) {
      if (!el.checked) return;
      if (opts.visibleOnly && !bandRowVisible(el)) return;
      out.push(el.value);
    });
    return out;
  }

  /** Untick checkboxes on rows hidden by the band filter (keeps scan aligned with what you see). */
  function untickFilteredOutBands() {
    var box = $("bs-bands");
    if (!box || !bandFilterQuery()) return 0;
    var n = 0;
    Array.prototype.forEach.call(box.querySelectorAll("input[type=checkbox]:checked"), function (el) {
      if (bandRowVisible(el)) return;
      el.checked = false;
      n++;
    });
    if (n) {
      S.selected = selectedValues();
      saveSettings();
      updateCount();
    }
    return n;
  }

  function profileFreqRange(p) {
    if (!p) return null;
    return parseMhzRange(p.label) || parseMhzRange(p.id) ||
      lookupCachedProfileFreq(p) || profileFreqFromPackId(p.id) ||
      profileFreqFromPackId(p.label) || profileFreqFromWellKnownId(p.id) ||
      profileFreqFromWellKnownId(p.value);
  }

  function profileMatchesAirPreset(el) {
    var id = String((el && el.dataset && el.dataset.id) || "");
    var lab = String((el && el.dataset && el.dataset.label) || "");
    var blob = id + " " + lab;
    if (/^air_/i.test(id) || /^tb_air_/i.test(id) || /^vor$/i.test(id)) return true;
    if (/\bairband\b|air.?band|\bvor\b/i.test(blob)) return true;
    var p = findProfileForEl(el);
    var r = profileFreqRange(p);
    if (!r) return false;
    var lo = Math.min(r.lo, r.hi);
    var hi = Math.max(r.lo, r.hi);
    /* Civil VHF air 118–137; include VOR 108–118. Exclude 2m (144+) and NOAA APT (~137.5+).
       Require a real overlap with 108–137 and a sane profile span (rejects UUID false parses). */
    var oLo = Math.max(lo, 108);
    var oHi = Math.min(hi, 137.0);
    if (!(oHi > oLo)) return false;
    if ((hi - lo) > 40) return false;
    return true;
  }

  function profileMatchesPreset(kind, el) {
    var id = (el && el.dataset && el.dataset.id) || "";
    var lab = (el && el.dataset && el.dataset.label) || "";
    if (kind === "air") return profileMatchesAirPreset(el);
    if (kind === "fm") {
      if (/^fm_/i.test(id) || /^tb_fm_/i.test(id)) return true;
      if (/fm.?broadcast|broadcast.?fm|\bwfm\b/i.test(id + " " + lab)) return true;
      var pFm = findProfileForEl(el);
      var rFm = profileFreqRange(pFm);
      if (rFm) {
        var lo = Math.min(rFm.lo, rFm.hi);
        var hi = Math.max(rFm.lo, rFm.hi);
        if (hi > 87.0 && lo < 108.5) return true;
      }
      return false;
    }
    if (kind === "vhf") {
      return /^(air_|marine_|2m_|pmr|tb_air_|tb_marine_|tb_ham_2m_|tb_pmr)/i.test(id) ||
        profileMatchesAirPreset(el) ||
        /\bmarine\b|\b2m\b|pmr446/i.test(id + " " + lab);
    }
    if (kind === "allvhf") return profileInAllVhf(findProfileForEl(el));
    if (kind === "alluhf") return profileInAllUhf(findProfileForEl(el));
    if (kind === "ham") {
      return /^(80m|40m|30m|20m|17m|15m|12m|10m|6m|4m|2m_|70c_|tb_ham_)/i.test(id) ||
        /\bham\b/i.test(lab);
    }
    if (kind === "digi") {
      return isDigiProfile(id, lab) || /(ft8|ft4|wspr|jt65|jt9|fst4|q65|js8)/i.test(id + " " + lab);
    }
    if (kind === "hfday") return /^(20m|17m|15m|12m|10m|6m|tb_ham_20m|tb_ham_17m|tb_ham_15m|tb_ham_12m|tb_ham_10m|tb_ham_6m)/i.test(id);
    if (kind === "hfnight") return /^(160m|80m|60m|40m|30m|tb_ham_160m|tb_ham_80m|tb_ham_60m|tb_ham_40m|tb_ham_30m)/i.test(id);
    return false;
  }

  function applyPreset(kind) {
    var box = $("bs-bands");
    if (!box) return;
    var exclusive = { air: 1, fm: 1, ham: 1, digi: 1, hfday: 1, hfnight: 1 };
    var filterOn = !!bandFilterQuery();
    if (kind === "none") {
      Array.prototype.forEach.call(box.querySelectorAll("input[type=checkbox]"), function (el) {
        el.checked = false;
      });
    } else if (kind === "all") {
      /* With a filter: select only the visible rows (replace ticks) so hidden Air/2m are not kept. */
      if (filterOn) {
        Array.prototype.forEach.call(box.querySelectorAll("input[type=checkbox]"), function (el) {
          el.checked = bandRowVisible(el);
        });
      } else {
        Array.prototype.forEach.call(box.querySelectorAll("input[type=checkbox]"), function (el) {
          el.checked = true;
        });
      }
    } else {
      if (exclusive[kind] || (filterOn && (kind === "vhf" || kind === "allvhf" || kind === "alluhf"))) {
        Array.prototype.forEach.call(box.querySelectorAll("input[type=checkbox]"), function (el) {
          el.checked = false;
        });
      }
      var n = 0;
      Array.prototype.forEach.call(box.querySelectorAll("input[type=checkbox]"), function (el) {
        if (filterOn && !bandRowVisible(el)) return;
        if (profileMatchesPreset(kind, el)) {
          el.checked = true;
          n++;
        }
      });
      if (kind === "air") {
        setStatus(n
          ? ("Air preset · " + n + " airband profile(s) only (other bands unticked).")
          : "Air preset · no airband profiles found (need air_1… or 118–137 MHz).");
      } else if (kind === "fm") {
        setStatus(n
          ? ("FM preset · " + n + " FM broadcast profile(s) only (other bands unticked).")
          : "FM preset · no FM broadcast profiles found (need fm_* or ~88–108 MHz).");
      } else if (exclusive[kind] && n) {
        setStatus(kind.toUpperCase() + " preset · " + n + " band(s) selected (replaced previous ticks).");
      } else if (filterOn && n) {
        setStatus("Preset · " + n + " visible band(s) selected (filter active; hidden ticks cleared).");
      }
    }
    S.selected = selectedValues();
    saveSettings();
    updateCount();
    updateRangeEstimate();
  }

  function updateCount() {
    var el = $("bs-selcount");
    if (!el) return;
    var n = selectedValues().length;
    var vis = selectedValues({ visibleOnly: true }).length;
    var tot = profiles().length;
    var filt = bandFilterQuery();
    var txt = n + " / " + tot + " bands";
    if (filt && n > vis) {
      txt += " · " + (n - vis) + " hidden by filter (still ticked)";
    } else if (filt) {
      txt += " · filter on";
    }
    el.textContent = txt;
    el.title = (filt && n > vis)
      ? "Some ticked bands are hidden by the filter — Scan bands would still include them unless you clear the filter or click None / FM / Air."
      : (n + " of " + tot + " band profiles ticked for Scan bands.");
  }

  function filterBands() {
    var q = bandFilterQuery();
    var box = $("bs-bands");
    if (!box) return;
    Array.prototype.forEach.call(box.querySelectorAll("tbody tr"), function (row) {
      var t = (row.textContent || "").toLowerCase();
      row.style.display = !q || t.indexOf(q) >= 0 ? "" : "none";
    });
    updateCount();
  }

  function fillBands() {
    var box = $("bs-bands");
    if (!box) return;
    ensureProfileFreqCache(function () {
      fillBandsDom();
    });
  }

  function fillBandsDom() {
    var box = $("bs-bands");
    if (!box) return;
    var list = orderedProfiles(false);
    if (!list.length) {
      var all = profiles();
      if (!all.length) {
        box.innerHTML = '<p class="bs-empty">No band profiles yet. Wait a few seconds for the radio to connect, then click Settings → Check install. If this stays empty, use <b>Bands packs</b> (admin) or add SDR profiles in OpenWebRX settings.</p>';
      } else {
        box.innerHTML = '<p class="bs-empty">All bands are hidden. Open <b>Bands edit</b> to unhide them.</p>';
      }
      updateCount();
      fillLoadUserBmBandSelect();
      try { renderBandPacks(); } catch (ePack0) {}
      try {
        if ($("bs-bd-edit") && currentPanelTab() === "bands") fillBandsEdit();
      } catch (eEd0) {}
      return;
    }
    var chosen = S.selected && S.selected.length ? S.selected : defaultSelected();
    var chosenSet = {};
    chosen.forEach(function (v) { chosenSet[v] = true; });
    var table = document.createElement("table");
    table.className = "bs-bands-table";
    table.innerHTML =
      "<thead><tr>" +
      '<th class="bs-bands-check" title="Include in Scan bands / Fresh scan"></th>' +
      '<th title="SDR profile id">Id</th>' +
      '<th title="Display name (alias from Bands edit, or OpenWebRX name)">Name</th>' +
      '<th title="Frequency coverage (from profile name or center ± sample rate / 2)">Freq</th>' +
      '<th title="Demodulation mode guessed from the profile id">Mode</th>' +
      (extraOn("bandEdit") ? '<th title="Edit alias, hide, note, order">Edit</th>' : "") +
      "</tr></thead>";
    var tbody = document.createElement("tbody");
    list.forEach(function (p) {
      var tr = document.createElement("tr");
      tr.title = "Include this band when Scan bands or Fresh scan runs.";
      var tdCheck = document.createElement("td");
      tdCheck.className = "bs-bands-check";
      var cb = document.createElement("input");
      cb.type = "checkbox";
      cb.value = p.value;
      cb.dataset.id = p.id;
      cb.dataset.label = p.label;
      cb.checked = !!chosenSet[p.value];
      var shown = bandDisplayName(p);
      cb.setAttribute("aria-label", "Include " + shown);
      tdCheck.appendChild(cb);
      var tdId = document.createElement("td");
      tdId.className = "bs-id";
      tdId.textContent = profileIdDisplay(p);
      tdId.title = isUuidProfileId(p.id)
        ? ("OpenWebRX UUID id (one-click pack). Full: " + p.id)
        : (p.id || "");
      var tdName = document.createElement("td");
      tdName.className = "bs-bands-name";
      tdName.textContent = shown;
      if (bandMetaFor(p.value) && String(bandMetaFor(p.value).alias || "").trim()) {
        tdName.title = "Alias · OpenWebRX: " + p.label;
        tdName.classList.add("bs-band-aliased");
      } else {
        tdName.title = p.label;
      }
      var tdFreq = document.createElement("td");
      tdFreq.className = "bs-bands-freq";
      var freqTxt = profileFreqLabel(p);
      tdFreq.textContent = freqTxt;
      tdFreq.title = freqTxt === "—"
        ? "No frequency in the profile name, and status.json coverage was not available."
        : ("Coverage · " + freqTxt + " MHz (or as shown)");
      var tdMode = document.createElement("td");
      tdMode.className = "bs-bands-mode";
      tdMode.textContent = profileModeLabel(p);
      tr.appendChild(tdCheck);
      tr.appendChild(tdId);
      tr.appendChild(tdName);
      tr.appendChild(tdFreq);
      tr.appendChild(tdMode);
      if (extraOn("bandEdit")) {
        var tdEdit = document.createElement("td");
        tdEdit.className = "bs-bands-check";
        var editBtn = document.createElement("button");
        editBtn.type = "button";
        editBtn.className = "bs-tiny bs-btn-util";
        editBtn.textContent = "edit";
        editBtn.title = "Edit alias, hide, note, and scan order (popup).";
        editBtn.setAttribute("data-band-edit", p.value);
        tdEdit.appendChild(editBtn);
        tr.appendChild(tdEdit);
      }
      tr.addEventListener("click", function (ev) {
        if (ev.target === cb || (ev.target.closest && ev.target.closest("input, button"))) return;
        cb.checked = !cb.checked;
        cb.dispatchEvent(new Event("change", { bubbles: true }));
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    box.innerHTML = "";
    box.appendChild(table);
    updateCount();
    fillLoadUserBmBandSelect();
    filterBands();
    try { renderBandPacks(); } catch (ePack) {}
    try {
      if ($("bs-bd-edit") && $("bs-tab-bands") &&
          $("bs-tab-bands").querySelector('.bs-bd-subpane.bs-bd-sub-on[data-bd-sub="edit"]')) {
        fillBandsEdit();
      }
    } catch (eEd) {}
  }

  function visibleHits() {
    if (!S.hideSpurs) return hits.slice();
    return hits.filter(function (h) { return !isSpur(h); });
  }

  function spurCount() {
    return hits.filter(isSpur).length;
  }

  function sortedHits() {
    var copy = visibleHits();
    copy.sort(function (a, b) {
      if (sortKey === "freq") return a.freq - b.freq;
      if (sortKey === "db") return b.maxDb - a.maxDb;
      if (a.seen !== b.seen) return b.seen - a.seen;
      return b.maxDb - a.maxDb;
    });
    return copy;
  }

  function updateClearSkipBtn() {
    var skipN = (S.ignoredFreqs || []).length;
    var label = skipN ? ("Clear always-skip (" + skipN + ")") : "Clear always-skip";
    ["bs-clearskip", "bs-clearskip-tab"].forEach(function (id) {
      var clr = $(id);
      if (!clr) return;
      clr.hidden = !skipN;
      clr.textContent = label;
    });
    var skipGrp = $("bs-peaks-skip-group");
    if (skipGrp) skipGrp.hidden = !skipN;
  }

  function renderHits() {
    updateClearSkipBtn();
    var host = $("bs-hitwrap");
    if (!host) {
      updateTabLabels();
      return;
    }
    if (extraOn("occHeatmap") && S.peaksView === "heatmap") {
      renderOccHeatmap();
      renderBookmarkPane();
      updateTabLabels();
      return;
    }
    if (!hits.length) {
      host.innerHTML = '<p class="bs-empty">No peaks yet. Pick bands and press Scan bands or Fresh scan.</p>';
      updateTabLabels();
      renderBookmarkPane();
      return;
    }
    var shown = sortedHits();
    if (extraOn("whatsNew") && S.showNewOnly) {
      shown = shown.filter(function (h) { return h.isNew && !isSpur(h); });
    }
    if (extraOn("surveyDiff") && S.showDiffOnly && surveySnapPeaks) {
      shown = shown.filter(function (h) { return !isSpur(h) && peakChangedVsSnap(h); });
    }
    var totalShown = shown.length;
    if (shown.length > RENDER_HITS_CAP) shown = shown.slice(0, RENDER_HITS_CAP);
    if (!shown.length) {
      var why = "";
      if (extraOn("whatsNew") && S.showNewOnly) why = "No “new” peaks — untick New only, or run a scan.";
      else if (extraOn("surveyDiff") && S.showDiffOnly) why = "No changed peaks vs snapshot — untick Changed only.";
      else if (S.hideSpurs && spurCount()) why = spurCount() + " birdies hidden. Untick “Hide birdies” on Bands / Range, or Clear always-skip.";
      else why = "No peaks to show.";
      host.innerHTML = '<p class="bs-empty">' + why + "</p>";
      updateTabLabels();
      renderBookmarkPane();
      return;
    }
    var rows = shown.map(function (h) {
      var known = existingName(h.freq);
      var spur = isSpur(h);
      var tag = spur ? '<span class="bs-spur-tag" title="' + escapeHtml(h.spurWhy || "birdie") + '">birdie</span>' : "";
      var icao = icao833(h.freq);
      var ch = icao && icao !== fmtMhzNum(h.freq) ? '<span class="bs-icao">' + icao + "</span> " : "";
      var newb = h.isNew && !spur ? '<span class="bs-new">new</span> ' : "";
      if (!spur && extraOn("surveyDiff") && peakChangedVsSnap(h)) newb += '<span class="bs-new" title="Not in saved survey snapshot">Δ</span> ';
      var pri = isPriority(h.freq) && !spur ? '<span class="bs-pri">pri</span> ' : "";
      var traffic = nearbyTrafficHint(h.freq);
      var nm = h.name || known || "";
      var alwaysOn = isIgnoredFreq(h.freq) || !!h.ignored;
      var acts = "";
      if (!spur) {
        if (known) {
          acts += '<span class="bs-hit-bm" title="' + escapeHtml(known) + '">bm</span>';
        } else {
          acts += '<button type="button" class="bs-tiny bs-btn-bm" data-bm="' + h.freq + '" title="Save this peak as a blue bookmark in this browser.">+</button>';
        }
        if (extraOn("peakNativeBm")) {
          acts += '<button type="button" class="bs-tiny bs-btn-bm" data-named-bm="' + h.freq + '" title="Save as a named blue bookmark (not [auto]).">nm</button>';
        }
        if (extraOn("copyTuneLink")) {
          acts += '<button type="button" class="bs-tiny bs-btn-util" data-copy-tune="' + h.freq + '" data-copy-mode="' +
            escapeHtml(h.mode || "") + '" title="Copy MHz (+ mode) to clipboard.">cp</button>';
        }
        if (extraOn("freqNotes")) {
          var note = noteForFreq(h.freq);
          acts += '<button type="button" class="bs-tiny bs-btn-util' + (note ? " bs-on" : "") + '" data-freq-note="' + h.freq +
            '" title="' + (note ? escapeHtml(note) : "Add a note for this MHz.") + '">nt</button>';
        }
      }
      acts += alwaysOn
        ? '<button type="button" class="bs-tiny bs-on" data-ignore="' + h.freq + '" title="Stop always-skipping this MHz">un</button>'
        : '<button type="button" class="bs-tiny bs-btn-lock" data-ignore="' + h.freq + '" title="Skip this MHz forever and continue the scan.">ign</button>';
      if (!(typeof publicAllowsFeature === "function") || publicAllowsFeature("clearData")) {
        acts += '<button type="button" class="bs-tiny bs-btn-clear" data-del-peak="' + h.freq +
          '" title="Remove this peak from the list. Bookmarks and always-skip are not changed.">×</button>';
      }
      return '<tr class="' + (spur ? "bs-spur" : "") + '">' +
        '<td class="bs-n">' + h.seen + "</td>" +
        '<td class="bs-hit-mhz">' + pri + newb + traffic + ch +
        '<button type="button" class="bs-tune" data-tune="' + h.freq + '" data-pid="' + escapeHtml(h.pid) + '" title="Tune the receiver to this frequency.">' +
        fmtMhz(h.freq) + "</button> " + tag + "</td>" +
        '<td class="bs-hit-name"><button type="button" class="bs-tune" data-rename="' + h.freq + '" title="Rename this peak / bookmark">' +
        (nm ? escapeHtml(nm) : "name") + "</button></td>" +
        '<td class="bs-hit-db">' + Math.round(h.maxDb) + "</td>" +
        '<td class="bs-hit-acts"><div class="bs-hit-acts-wrap">' + acts + "</div></td>" +
        "</tr>";
    }).join("");
    updateClearSkipBtn();
    var extra = S.hideSpurs && spurCount()
      ? '<p class="bs-empty">' + spurCount() + " birdies hidden. Untick Hide birdies to un-ign, or Clear always-skip.</p>"
      : "";
    if (totalShown > RENDER_HITS_CAP) {
      extra += '<p class="bs-empty">Showing top ' + RENDER_HITS_CAP + " of " + totalShown +
        " peaks (" + hits.length + " stored). Export CSV for the full list.</p>";
    }
    host.innerHTML = extra +
      '<table class="bs-hits"><thead><tr>' +
      '<th data-sort="seen"' + (sortKey === "seen" ? ' class="bs-sort"' : "") + ' title="Sort by how many times this peak was counted.">Seen</th>' +
      '<th data-sort="freq"' + (sortKey === "freq" ? ' class="bs-sort"' : "") + ' title="Sort by frequency.">MHz</th>' +
      "<th>Name</th>" +
      '<th data-sort="db"' + (sortKey === "db" ? ' class="bs-sort"' : "") + ' title="Sort by strongest reading.">dB</th>' +
      '<th class="bs-hit-acts" title="Bookmark, ignore, delete">Acts</th></tr></thead><tbody>' + rows + "</tbody></table>";
    updateTabLabels();
    renderBookmarkPane();
  }

  function escapeHtml(s) {
    return String(s || "").replace(/[&<>"']/g, function (c) {
      return ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c];
    });
  }

  function setStatus(msg) {
    var el = $("bs-status");
    if (el) el.textContent = msg || "";
  }

  function setProgress(frac) {
    var el = $("bs-bar");
    if (el) el.style.width = Math.max(0, Math.min(100, frac * 100)) + "%";
  }

  /** Bookmark-scan progress: within-pass index, or overall when Passes > 0. */
  function setListenProgress(itemIndex, itemCount, passNum, maxPasses) {
    itemCount = Math.max(1, Number(itemCount) || 1);
    itemIndex = Math.max(0, Math.min(itemCount, Number(itemIndex) || 0));
    passNum = Math.max(1, Number(passNum) || 1);
    maxPasses = Math.max(0, Number(maxPasses) || 0);
    var within = itemIndex / itemCount;
    if (maxPasses > 0) {
      setProgress(Math.min(1, ((passNum - 1) + within) / maxPasses));
    } else {
      setProgress(within);
    }
  }

  function sleep(ms) {
    return new Promise(function (resolve) { setTimeout(resolve, ms); });
  }

  function switchProfile(value) {
    var sel = $("openwebrx-sdr-profiles-listbox");
    if (!sel) return Promise.resolve(false);
    var prevCenter = window.center_freq;
    var already = sel.value === value;
    if (!already) {
      sel.value = value;
      var toggle = $("owrx-band-toggle");
      if (toggle) {
        var opt = sel.options[sel.selectedIndex];
        toggle.textContent = opt ? opt.text : "Bands";
      }
      if (typeof sdr_profile_changed === "function") sdr_profile_changed();
      else sel.dispatchEvent(new Event("change", { bubbles: true }));
    }
    var t0 = Date.now();
    return new Promise(function (resolve) {
      (function tick() {
        var nowSel = $("openwebrx-sdr-profiles-listbox");
        var ok = nowSel && nowSel.value === value;
        var data = wf();
        var moved = already || window.center_freq !== prevCenter;
        if (ok && moved && data && data.length > 32 && Date.now() - t0 > 600) {
          resolve(true);
          return;
        }
        if (Date.now() - t0 > 10000) {
          resolve(ok);
          return;
        }
        setTimeout(tick, 200);
      })();
    });
  }

  function muteOn() {
    if (!S.mute || mutedHold) return;
    mutedHold = true;
    try {
      if (window.UI && typeof UI.volume === "number") savedVol = UI.volume;
      if (window.audioEngine && typeof audioEngine.setVolume === "function") {
        audioEngine.setVolume(0);
      } else if (window.UI && typeof UI.setVolume === "function") {
        UI.setVolume(0);
      }
    } catch (e) {}
  }

  function muteOff() {
    if (!mutedHold) return;
    mutedHold = false;
    try {
      if (window.UI && UI.volumeMuted >= 0) return;
      if (savedVol != null && window.UI && typeof UI.setVolume === "function") {
        UI.setVolume(savedVol);
      }
    } catch (e) {}
    savedVol = null;
  }

  function profileByValue(value) {
    var list = profiles();
    for (var i = 0; i < list.length; i++) {
      if (list[i].value === value) return list[i];
    }
    return null;
  }

  function hitNearFreq(freq, tolHz) {
    freq = Number(freq);
    if (!freq) return null;
    tolHz = isFinite(tolHz) ? tolHz : 4000;
    var best = null;
    var bestD = Infinity;
    var i, h, d;
    for (i = 0; i < hits.length; i++) {
      h = hits[i];
      if (!h || !isFinite(h.freq)) continue;
      d = Math.abs(h.freq - freq);
      if (d < tolHz && d < bestD) {
        best = h;
        bestD = d;
      }
    }
    return best;
  }

  function bookmarkNearFreq(freq, tolHz) {
    freq = Number(freq);
    if (!freq) return null;
    tolHz = isFinite(tolHz) ? tolHz : 2500;
    var list = [];
    try {
      if (typeof BookmarkLocalStorage === "function") {
        list = list.concat(new BookmarkLocalStorage().getBookmarks() || []);
      }
    } catch (e) {}
    try { list = list.concat(allBookmarks() || []); } catch (e2) {}
    try { list = list.concat(loadedBookmarks || []); } catch (e3) {}
    var best = null;
    var bestD = Infinity;
    var i, b, d;
    for (i = 0; i < list.length; i++) {
      b = list[i];
      if (!b || !isFinite(b.frequency)) continue;
      d = Math.abs(b.frequency - freq);
      if (d < tolHz && d < bestD) {
        best = b;
        bestD = d;
      }
    }
    return best;
  }

  /** Extra column text for Always skip rows (band / mode / peak / bookmark / note). */
  function skipDetailForFreq(freq) {
    freq = Number(freq);
    if (!freq) return { name: "", info: "—" };
    var hit = hitNearFreq(freq);
    var bm = bookmarkNearFreq(freq);
    var name = "";
    if (hit && hit.name && String(hit.name).trim()) name = String(hit.name).trim();
    if (!name && bm && bm.name) name = String(bm.name);
    if (!name) {
      var known = existingName(freq);
      if (known) name = known;
    }
    if (!name) {
      var icao = icao833(freq);
      if (icao) name = icao;
    }
    var bits = [];
    var band = (hit && (hit.label || profileLabelForPid(hit.pid))) ||
      (bm && bm.pid ? profileLabelForPid(bm.pid) : "");
    if (!band && hit && hit.pid) band = String(hit.pid);
    if (band) bits.push(String(band));
    var mode = (hit && hit.mode) || (bm && (bm.modulation || bm.mode)) || "";
    if (mode) bits.push(String(mode).toUpperCase());
    if (hit) {
      if (isFinite(hit.seen) && hit.seen > 0) bits.push("seen " + hit.seen + "×");
      var db = hit.maxDb != null ? hit.maxDb : hit.lastDb;
      if (isFinite(db)) bits.push(Math.round(db) + " dB");
      if (hit.spurWhy && hit.spurWhy !== "ignored") bits.push(String(hit.spurWhy));
    }
    var icaoCh = icao833(freq);
    if (icaoCh && name !== icaoCh) bits.push("ch " + icaoCh);
    try {
      var note = typeof noteForFreq === "function" ? noteForFreq(freq) : "";
      if (note) bits.push("note: " + String(note).slice(0, 48));
    } catch (eN) {}
    if (!bits.length) {
      if (bm) bits.push("bookmark");
      else bits.push("manual skip");
    }
    return { name: name, info: bits.join(" · ") };
  }

  function ignoreFreq(freq) {
    freq = Number(freq);
    if (!freq) return;
    S.ignoredFreqs = S.ignoredFreqs || [];
    if (!isIgnoredFreq(freq)) S.ignoredFreqs.push(Math.round(freq));
    hits.forEach(function (h) {
      if (Math.abs(h.freq - freq) < 4000) {
        h.ignored = true;
        h.spur = true;
        h.spurWhy = "ignored";
      }
    });
    saveSettings();
    saveHits();
    renderHits();
  }

  /** Remove one peak from the list (does not touch bookmarks or always-skip). */
  function removePeak(freq) {
    freq = Number(freq);
    if (!freq) return false;
    var before = hits.length;
    hits = hits.filter(function (h) {
      return Math.abs(Number(h.freq) - freq) >= 1;
    });
    if (hits.length === before) return false;
    _hitsClassified = false;
    saveHits();
    renderHits();
    updateTabLabels();
    return true;
  }

  function unignoreFreq(freq) {
    freq = Number(freq);
    S.ignoredFreqs = (S.ignoredFreqs || []).filter(function (f) {
      return Math.abs(f - freq) >= 4000;
    });
    hits.forEach(function (h) {
      if (Math.abs(h.freq - freq) < 4000) {
        h.ignored = false;
        if (h.spurWhy === "ignored") {
          h.spur = false;
          h.spurWhy = "";
        }
      }
    });
    classifyAll();
    saveSettings();
    saveHits();
    renderHits();
  }

  function clearAlwaysSkips() {
    var n = (S.ignoredFreqs || []).length;
    S.ignoredFreqs = [];
    hits.forEach(function (h) {
      if (h.ignored) {
        h.ignored = false;
        if (h.spurWhy === "ignored") {
          h.spur = false;
          h.spurWhy = "";
        }
      }
    });
    classifyAll();
    saveSettings();
    saveHits();
    renderHits();
    setStatus(n ? ("Cleared " + n + " always-skip frequenc" + (n === 1 ? "y." : "ies.")) : "No always-skip frequencies.");
  }

  function currentTuneHz() {
    if (listenFreq) return listenFreq;
    try {
      if (window.UI && typeof UI.getFrequency === "function") {
        var u = UI.getFrequency();
        if (u) return u;
      }
    } catch (e) {}
    try {
      if (window.dems) {
        var ids = Object.keys(window.dems);
        if (ids.length && window.dems[ids[0]] && typeof window.dems[ids[0]].get_offset_frequency === "function") {
          return window.center_freq + window.dems[ids[0]].get_offset_frequency();
        }
      }
    } catch (e2) {}
    return 0;
  }

  function finalizeSurveyScan(snapBefore, scanKind) {
    classifyAll();
    markNewFlags(snapBefore);
    saveHits();
    saveSnap();
    var wantBm = !!S.autoBm;
    if (scanKind === "range" && extraOn("rangeAutoBm") && S.rangeAutoBmOn !== false) wantBm = true;
    var created = wantBm ? autoBookmarkQualified() : [];
    var freshBm = created.filter(function (r) { return !r.already; });
    lastCreated = freshBm;
    var liveN = hits.filter(function (h) { return !isSpur(h); }).length;
    var newN = hits.filter(function (h) { return h.isNew && !isSpur(h); }).length;
    var bmN = freshBm.length;
    var extra = hits.length ? "" : (scanKind === "range"
      ? " Nothing sat above the threshold — lower “dB over noise” or widen dwell."
      : " Nothing sat above the threshold — lower “dB over noise” or pick a busier band.");
    var detail = liveN + " signals (" + newN + " new), " + spurCount() + " birdies ignored";
    var bmPart = wantBm
      ? (bmN === 1 ? "1 bookmarked" : bmN + " bookmarked")
      : "auto-bookmark off";
    var prefix = scanKind === "range" ? "Range " : "";
    return {
      freshBm: freshBm,
      doneStatus: prefix + "Done — " + bmPart + " · " + detail + extra,
      stopStatus: prefix + "Stopped — " + bmPart + " · " + detail + extra
    };
  }

  async function runRangeSurvey(fresh) {
    if (running) return;
    if (!publicAllowsFeature("scanRange")) {
      setStatus("Range scan is not allowed for visitors on this public receiver.");
      return;
    }
    hookWaterfall();
    readForm();
    readRangeForm();
    S.passes = passesFromUi();
    S.dwell = dwellFromUi();
    S.minHits = minHitsFromUi();
    S.threshDb = threshFromUi();
    S.widebandPeaks = widebandFromUi();
    S.hideSpurs = hideSpursFromUi();
    if ($("bs-autobm")) S.autoBm = $("bs-autobm").checked;
    S.mute = muteFromUi();
    S.ownRadio = ownRadioFromUi();
    saveSettings();
    var startHz = (Number(S.rangeStartMhz) || 0) * 1e6;
    var endHz = (Number(S.rangeEndMhz) || 0) * 1e6;
    if (!startHz || !endHz || startHz >= endHz) {
      var bad = "Range needs start MHz < end MHz (e.g. 109 and 200).";
      setStatus(bad);
      toast(bad);
      switchTab("range");
      return;
    }
    if (rangeUsesChannelGrid() && !(Number(S.rangeStepKhz) > 0)) {
      var badGrid = "Channel grid needs Step kHz > 0 — pick a Grid preset or enter spacing.";
      setStatus(badGrid);
      toast(badGrid);
      switchTab("range");
      return;
    }
    if (rangeUsesChannelGrid()) {
      var gridCenters = buildChannelGridCenters(startHz, endHz, rangeStepHz(), rangeOffsetHz());
      if (!gridCenters.length) {
        var badEmpty = "Channel grid produced no tune points — check Start, End, Step, and Offset.";
        setStatus(badEmpty);
        toast(badEmpty);
        switchTab("range");
        return;
      }
    }
    if (!profiles().length) {
      setStatus("No band profiles yet — wait for the radio, then try again. See Help.");
      toast("No band profiles yet.");
      renderHealth({ ok: true });
      return;
    }
    var blocked = blockingIssue();
    if (blocked) {
      setStatus(blocked.title + " — " + blocked.fix);
      renderHealth();
      openHelp();
      return;
    }
    if (courtesyBlocked("range survey")) return;
    if (!window.UI || typeof UI.setFrequency !== "function") {
      setStatus("Tune API is missing (UI.setFrequency). Range scan needs direct frequency tuning.");
      return;
    }
    if (!confirmRangeCoverageOrAbort(startHz, endHz)) {
      setStatus("Range scan cancelled — coverage gaps.");
      return;
    }
    if (window.fs_scanner_state && fs_scanner_state.running && typeof fs_stop_scanner === "function") {
      try { fs_stop_scanner(); } catch (e) {}
    }
    cancelRangeRepeat();
    running = true;
    stopFlag = false;
    hideRangeSpectrum();
    var rangeScanLo = Number(S.rangeStartMhz);
    var rangeScanHi = Number(S.rangeEndMhz);
    var snapBefore = loadSnap();
    if (fresh) {
      hits = [];
      tileLooks = {};
      _hitsClassified = false;
    } else {
      await ensureHitsLoadedPromise();
      ensureHitsClassified();
    }
    renderHits();
    setSurveyRunning(true);
    var btn = $("bs-toggle-btn");
    if (btn) btn.classList.add("bs-running");
    muteOn();
    var rangeLab = rangeLabel();
    var p0 = profileForFreq(startHz);
    if (!p0) {
      setStatus("No profile covers " + fmtMhz(startHz) + ". Add a band that includes this MHz.");
      running = false;
      setSurveyRunning(false);
      if (btn) btn.classList.remove("bs-running");
      muteOff();
      restoreRangeSpectrumView();
      return;
    }
    try {
      setStatus("Range · preparing " + rangeLab + " · switching to " + p0.label);
      if (!(await tuneToCenter(startHz, p0, "Range · prepare"))) {
        if (stopFlag) {
          var finPrep = finalizeSurveyScan(snapBefore, "range");
          setStatus(finPrep.stopStatus);
          showRangeSpectrum(rangeScanLo, rangeScanHi);
          muteOff();
        }
        running = false;
        setSurveyRunning(false);
        if (btn) btn.classList.remove("bs-running");
        if (!stopFlag) muteOff();
        renderHits();
        return;
      }
      var stepHz = rangeStepHz();
      var centers = buildRangeCenters(startHz, endHz, stepHz);
      var bandSteps = null;
      if (S.rangeMode === "bands") {
        bandSteps = buildRangeBandSteps(startHz, endHz);
        if (!bandSteps.length) {
          var ticked = selectedValues().length;
          var msg = ticked
            ? "No ticked bands overlap " + rangeLabel() + ". Tick overlapping bands or use Full range mode."
            : "No bands ticked — tick bands on the Bands tab or use Full range mode.";
          setStatus(msg);
          toast(msg);
          running = false;
          setSurveyRunning(false);
          if (btn) btn.classList.remove("bs-running");
          muteOff();
          switchTab("range");
          restoreRangeSpectrumView();
          return;
        }
      }
      var total = S.rangeMode === "bands"
        ? bandSteps.length * S.passes
        : centers.length * S.passes;
      var step = 0;
      var hopCount = 0;
      var rangeStartedAt = Date.now();
      var lastProfile = p0;
      for (var pass = 1; pass <= S.passes && !stopFlag; pass++) {
        var loopN = S.rangeMode === "bands" ? bandSteps.length : centers.length;
        for (var ci = 0; ci < loopN && !stopFlag; ci++) {
          if (extraOn("rangeHopCap")) {
            if (S.rangeMaxHops > 0 && hopCount >= S.rangeMaxHops) {
              setStatus("Range stopped — max hops (" + S.rangeMaxHops + ").");
              stopFlag = true;
              break;
            }
            if (S.rangeMaxMin > 0 && (Date.now() - rangeStartedAt) >= S.rangeMaxMin * 60000) {
              setStatus("Range stopped — max time (" + S.rangeMaxMin + " min).");
              stopFlag = true;
              break;
            }
          }
          var freqHz;
          var prof;
          if (S.rangeMode === "bands") {
            freqHz = bandSteps[ci].freqHz;
            prof = bandSteps[ci].profile;
          } else {
            freqHz = centers[ci];
            prof = profileForFreq(freqHz) || lastProfile;
          }
          lastProfile = prof;
          var ptLabel = "Range " + rangeLab + " · " + fmtMhz(freqHz);
          var modeTag = S.rangeMode === "bands" ? "bands" : "full";
          setStatus("Pass " + pass + "/" + S.passes + " · " + (ci + 1) + "/" + loopN +
            " · " + fmtMhz(freqHz) + (prof && prof.label ? " · " + prof.label : ""));
          setProgress(step / total);
          if (!(await tuneToCenter(freqHz, prof, "Pass " + pass + "/" + S.passes + " · " + fmtMhz(freqHz)))) break;
          hopCount++;
          var until = Date.now() + S.dwell * 1000;
          var lastNoise = "";
          while (Date.now() < until && !stopFlag) {
            recordLook(prof.id, ptLabel);
            saveHits();
            var data = wf();
            if (data && data.length) {
              lastNoise = " · noise " + Math.round(noiseFloor(data)) + " dB · " + hits.length + " peaks";
            }
            setStatus("Pass " + pass + "/" + S.passes + " · " + (ci + 1) + "/" + loopN +
              " · " + fmtMhz(freqHz) + (modeTag === "bands" && prof ? " · " + prof.label : "") + lastNoise);
            renderHits();
            await sleep(SAMPLE_MS);
          }
          step++;
          setProgress(step / total);
        }
      }
      var finRange = finalizeSurveyScan(snapBefore, "range");
      var freshBm = finRange.freshBm;
      showRangeSpectrum(rangeScanLo, rangeScanHi);
      if (stopFlag) setStatus(finRange.stopStatus);
      else {
        setStatus(finRange.doneStatus);
        onSurveyComplete(finRange, false);
      }
      muteOff();
      setSurveyRunning(false);
      if (!stopFlag && S.scanAfter && freshBm.length) {
        setStatus(finRange.doneStatus + " Listening to new bookmarks…");
        await listenBookmarks(freshBm);
      } else if (!stopFlag && S.scanAfter && !freshBm.length && qualifiedHits().length) {
        setStatus("No new bookmarks — listening to qualified peaks…");
        await listenBookmarks(qualifiedHits().map(function (h) { return { hit: h, freq: h.freq, pid: h.pid, mode: h.mode, name: bookmarkNameFor(h) }; }));
      }
      if (!stopFlag) {
        try { scheduleRangeRepeat(); } catch (eRep) {}
      }
    } catch (err) {
      setStatus(friendlyError(err, "Range scan"));
      toast(friendlyError(err, "Range scan"));
      renderHealth({ all: true, toast: false });
    }
    running = false;
    setSurveyRunning(false);
    if (btn) btn.classList.remove("bs-running");
    if (!S.scanAfter) muteOff();
    renderHits();
  }

  async function runSurvey(fresh) {
    if (running) return;
    if (!publicAllowsFeature("scanBands")) {
      setStatus("Scan bands is not allowed for visitors on this public receiver.");
      return;
    }
    hookWaterfall();
    readForm();
    S.passes = passesFromUi();
    S.dwell = dwellFromUi();
    S.minHits = minHitsFromUi();
    S.threshDb = threshFromUi();
    S.widebandPeaks = widebandFromUi();
    S.hideSpurs = hideSpursFromUi();
    if ($("bs-autobm")) S.autoBm = $("bs-autobm").checked;
    S.mute = muteFromUi();
    S.ownRadio = ownRadioFromUi();
    var box = $("bs-bands");
    if (box && !box.querySelector("input")) fillBands();
    var hiddenTicks = untickFilteredOutBands();
    S.selected = orderSelectedForScan(selectedValues());
    saveSettings();
    if (!S.selected.length) {
      var noProfiles = !profiles().length;
      var msg = noProfiles
        ? "No bands to pick yet. Wait for the radio to finish loading, then click Settings → Check install. See Help if this stays empty."
        : "Pick at least one band (or tap Air / FM / VHF voice / All VHF / All UHF / Ham).";
      setStatus(msg);
      toast(msg);
      renderHealth({ ok: true });
      return;
    }
    if (hiddenTicks) {
      setStatus("Cleared " + hiddenTicks + " ticked band(s) hidden by filter — scanning " +
        S.selected.length + " visible band(s).");
    }
    var blocked = blockingIssue();
    if (blocked) {
      setStatus(blocked.title + " — " + blocked.fix);
      renderHealth();
      openHelp();
      return;
    }
    if (courtesyBlocked("surveying")) return;
    if (window.fs_scanner_state && fs_scanner_state.running && typeof fs_stop_scanner === "function") {
      try { fs_stop_scanner(); } catch (e) {}
    }
    running = true;
    stopFlag = false;
    var snapBefore = loadSnap();
    if (fresh) {
      hits = [];
      tileLooks = {};
      _hitsClassified = false;
    } else {
      await ensureHitsLoadedPromise();
      ensureHitsClassified();
    }
    renderHits();
    setSurveyRunning(true);
    var btn = $("bs-toggle-btn");
    if (btn) btn.classList.add("bs-running");
    muteOn();
    var total = S.selected.length * S.passes;
    var step = 0;
    try {
      for (var pass = 1; pass <= S.passes && !stopFlag; pass++) {
        for (var i = 0; i < S.selected.length && !stopFlag; i++) {
          var value = S.selected[i];
          var p = profileByValue(value) || { id: value, label: value };
          setStatus("Pass " + pass + "/" + S.passes + " · " + p.label);
          setProgress(step / total);
          var needSwitch = currentProfileValue() !== value;
          if (needSwitch) {
            await waitProfileGap("Pass " + pass + "/" + S.passes + " · " + p.label + " · waiting");
            if (stopFlag) break;
            await switchProfile(value);
            lastProfileSwitchAt = Date.now();
          } else {
            await switchProfile(value);
          }
          applyDigiModeIfNeeded(p.id, p.label);
          var peaksBefore = hits.length;
          var digiBefore = countDigiSpotsOnPage();
          var dwellSec = digiDwellForProfile(p.id, p.label, S.dwell);
          var until = Date.now() + dwellSec * 1000;
          var lastNoise = "";
          while (Date.now() < until && !stopFlag) {
            recordLook(p.id, p.label);
            saveHits();
            var data = wf();
            if (data && data.length) {
              lastNoise = " · noise " + Math.round(noiseFloor(data)) + " dB · " + hits.length + " peaks";
              if (extraOn("digiSurvey") && isDigiProfile(p.id, p.label)) {
                lastNoise += " · dwell " + Math.round(dwellSec) + "s";
              }
            }
            setStatus("Pass " + pass + "/" + S.passes + " · " + p.label + lastNoise);
            renderHits();
            await sleep(SAMPLE_MS);
          }
          var digiDelta = Math.max(0, countDigiSpotsOnPage() - digiBefore);
          var peakDelta = Math.max(0, hits.length - peaksBefore);
          recordOccupancy(p.id, p.label, peakDelta, digiDelta);
          step++;
          setProgress(step / total);
        }
      }
      var finBand = finalizeSurveyScan(snapBefore, "band");
      var freshBm = finBand.freshBm;
      if (stopFlag) setStatus(finBand.stopStatus);
      else {
        setStatus(finBand.doneStatus);
        onSurveyComplete(finBand, false);
      }
      muteOff();
      setSurveyRunning(false);
      if (!stopFlag && S.scanAfter && freshBm.length) {
        setStatus(finBand.doneStatus + " Listening to new bookmarks…");
        await listenBookmarks(freshBm);
      } else if (!stopFlag && S.scanAfter && !freshBm.length && qualifiedHits().length) {
        setStatus("No new bookmarks — listening to qualified peaks…");
        await listenBookmarks(qualifiedHits().map(function (h) { return { hit: h, freq: h.freq, pid: h.pid, mode: h.mode, name: bookmarkNameFor(h) }; }));
      }
    } catch (err) {
      setStatus(friendlyError(err, "Toolbox"));
      toast(friendlyError(err, "Toolbox"));
      renderHealth({ all: true, toast: false });
    }
    running = false;
    setSurveyRunning(false);
    if (btn) btn.classList.remove("bs-running");
    if (!S.scanAfter) muteOff();
    renderHits();
  }

  function stopSurvey() {
    stopFlag = true;
    try { cancelRangeRepeat(); } catch (eStopRep) {}
    setStatus("Stopping…");
  }

  function tuneTo(freq, pid) {
    var list = profiles();
    var want = null;
    for (var i = 0; i < list.length; i++) {
      if (list[i].id === pid) {
        want = list[i].value;
        break;
      }
    }
    var go = want ? switchProfile(want) : Promise.resolve(true);
    go.then(function () {
      pluginSetFrequency(freq);
      var hit = null;
      for (var j = 0; j < hits.length; j++) {
        if (hits[j].freq === freq) hit = hits[j];
      }
      if (hit && window.UI && typeof UI.setModulation === "function") {
        try { UI.setModulation(hit.mode, ""); } catch (e) {}
      }
    });
  }

  function copyResults() {
    try {
    var lines = sortedHits().map(function (h) {
      return h.seen + "\t" + fmtMhzNum(h.freq) + "\t" + (icao833(h.freq) || "") + "\t" +
        Math.round(h.maxDb) + "\t" + (h.label || h.pid) + "\t" + (h.name || "") + "\t" + (h.isNew ? "new" : "");
    });
    lines.unshift("seen\tMHz\tch833\tdB\tband\tname\tnew");
    var text = lines.join("\n");
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text);
      setStatus("Copied " + hits.length + " peaks.");
    } else {
      setStatus("Clipboard blocked — use Export CSV instead.");
    }
    } catch (err) {
      setStatus(friendlyError(err, "Copy"));
    }
  }

  function downloadFile(name, text, mime) {
    var a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([text], { type: mime || "text/plain" }));
    a.download = name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { try { URL.revokeObjectURL(a.href); } catch (e) {} }, 1500);
  }

  function hitForExport(h) {
    return {
      freq: h.freq,
      raw: h.raw,
      seen: h.seen,
      looks: h.looks,
      maxDb: h.maxDb,
      lastDb: h.lastDb,
      pid: h.pid,
      label: h.label,
      first: h.first,
      last: h.last,
      mode: h.mode,
      samples: (h.samples || []).slice(-48),
      width: h.width,
      offset: h.offset,
      spur: !!h.spur,
      spurWhy: h.spurWhy || "",
      ignored: !!h.ignored,
      dongle: !!h.dongle,
      name: h.name || "",
      isNew: !!h.isNew
    };
  }

  function exportCsv() {
    try {
    var lines = ["seen,MHz,ch833,dB,band,name,new,birdie,last,pid,looks,mode"];
    hits.slice().sort(function (a, b) {
      if (a.seen !== b.seen) return b.seen - a.seen;
      return (b.maxDb || 0) - (a.maxDb || 0);
    }).forEach(function (h) {
      lines.push([
        h.seen,
        fmtMhzNum(h.freq),
        icao833(h.freq),
        Math.round(h.maxDb),
        JSON.stringify(h.label || h.pid),
        JSON.stringify(h.name || existingName(h.freq) || ""),
        h.isNew ? "yes" : "",
        isSpur(h) ? (h.spurWhy || "yes") : "",
        h.last ? new Date(h.last).toISOString() : "",
        JSON.stringify(h.pid || ""),
        h.looks || "",
        JSON.stringify(h.mode || "")
      ].join(","));
    });
    downloadFile("toolbox.csv", lines.join("\n"), "text/csv");
    setStatus("Exported CSV (" + hits.length + " peaks).");
    } catch (err) {
      setStatus(friendlyError(err, "Export CSV"));
      toast(friendlyError(err, "Export CSV"));
    }
  }

  function bookmarkRowsForExport() {
    return qualifiedHits().map(function (h) {
      return {
        name: bookmarkNameFor(h),
        frequency: Math.round(h.freq),
        modulation: h.mode || "am",
        description: "survey seen " + h.seen + (h.isNew ? " (new)" : "")
      };
    });
  }

  function exportServerJson() {
    try {
    var bookmarks = bookmarkRowsForExport();
    var payload = {
      kind: "owrx-toolbox",
      version: 1,
      exported: new Date().toISOString(),
      bookmarks: bookmarks,
      hits: hits.map(hitForExport),
      tileLooks: tileLooks
    };
    downloadFile("bookmarks-survey.json", JSON.stringify(payload, null, 2), "application/json");
    setStatus("Exported " + bookmarks.length + " bookmark rows plus " + hits.length + " peaks. For yellow server bookmarks, merge the bookmarks array on the radio host.");
    } catch (err) {
      setStatus(friendlyError(err, "Export JSON"));
      toast(friendlyError(err, "Export JSON"));
    }
  }

  function parseCsvLine(line) {
    var out = [];
    var cur = "";
    var i = 0;
    var inQ = false;
    while (i < line.length) {
      var c = line.charAt(i);
      if (inQ) {
        if (c === "\\" && line.charAt(i + 1) === '"') {
          cur += '"';
          i += 2;
          continue;
        }
        if (c === '"') {
          if (line.charAt(i + 1) === '"') {
            cur += '"';
            i += 2;
            continue;
          }
          inQ = false;
          i++;
          continue;
        }
        cur += c;
        i++;
        continue;
      }
      if (c === '"') {
        inQ = true;
        i++;
        continue;
      }
      if (c === ",") {
        out.push(cur);
        cur = "";
        i++;
        continue;
      }
      cur += c;
      i++;
    }
    out.push(cur);
    return out;
  }

  function hzFromCell(raw) {
    var n = Number(String(raw || "").replace(/[^\d.eE+-]/g, ""));
    if (!isFinite(n) || n <= 0) return 0;
    if (n < 1e5) return Math.round(n * 1e6);
    return Math.round(n);
  }

  function pidFromBand(band, pidCell) {
    var wantPid = String(pidCell || "").trim();
    var wantBand = String(band || "").trim();
    var list = profiles();
    var i;
    if (wantPid) {
      for (i = 0; i < list.length; i++) {
        if (list[i].id === wantPid || list[i].label === wantPid) return list[i].id;
      }
      return wantPid;
    }
    if (wantBand) {
      for (i = 0; i < list.length; i++) {
        if (list[i].id === wantBand || list[i].label === wantBand) return list[i].id;
      }
      return wantBand;
    }
    return "imported";
  }

  function normalizeHit(h) {
    if (!h || typeof h !== "object") return null;
    var freq = Number(h.freq || h.frequency || 0);
    if (!isFinite(freq) || freq <= 0) return null;
    if (freq < 1e5) freq = Math.round(freq * 1e6);
    else freq = Math.round(freq);
    var pid = String(h.pid || "").trim() || "imported";
    var seen = Math.max(1, Math.round(Number(h.seen) || 1));
    var last = h.last;
    if (typeof last === "string" && last) {
      var t = Date.parse(last);
      last = isFinite(t) ? t : Date.now();
    }
    if (!last) last = Date.now();
    var first = h.first;
    if (typeof first === "string" && first) {
      var t2 = Date.parse(first);
      first = isFinite(t2) ? t2 : last;
    }
    if (!first) first = last;
    var maxDb = Number(h.maxDb != null ? h.maxDb : (h.db != null ? h.db : h.lastDb));
    if (!isFinite(maxDb)) maxDb = 0;
    var spurWhy = String(h.spurWhy || "");
    var spur = !!(h.spur || h.ignored);
    if (h.birdie && String(h.birdie) !== "no") {
      spur = true;
      if (!spurWhy) spurWhy = String(h.birdie) === "yes" ? "birdie" : String(h.birdie);
    }
    var isNew = h.isNew === true || h.isNew === "yes" || h.isNew === "true";
    return {
      freq: freq,
      raw: Number(h.raw) || freq,
      seen: seen,
      looks: Math.max(Number(h.looks) || 0, seen),
      maxDb: maxDb,
      lastDb: Number(h.lastDb) || maxDb,
      pid: pid,
      label: String(h.label || pid),
      first: first,
      last: last,
      mode: h.mode || guessMode(pid),
      samples: Array.isArray(h.samples) ? h.samples.slice(-48) : [],
      width: Number(h.width) || 1,
      offset: h.offset != null && h.offset !== "" ? Number(h.offset) : undefined,
      spur: spur,
      spurWhy: spurWhy,
      ignored: !!h.ignored,
      dongle: !!h.dongle,
      name: h.name != null ? String(h.name) : "",
      isNew: isNew
    };
  }

  function hitFromBookmarkRow(b) {
    if (!b || typeof b !== "object") return null;
    var freq = Number(b.frequency || b.freq || 0);
    if (!isFinite(freq) || freq <= 0) return null;
    var desc = String(b.description || "");
    var m = desc.match(/seen\s+(\d+)/i);
    var seen = Number(b.seen);
    if (!isFinite(seen) || seen < 1) seen = m ? Number(m[1]) : 1;
    return normalizeHit({
      freq: freq,
      seen: seen,
      looks: b.looks || seen,
      maxDb: b.maxDb,
      lastDb: b.lastDb,
      pid: b.pid || "",
      label: b.label || b.pid || "imported",
      mode: b.modulation || b.mode,
      name: String(b.name || "").replace(/^\[auto\]\s*/i, ""),
      isNew: b.isNew || /\(new\)/i.test(desc),
      last: b.last,
      first: b.first,
      spur: b.spur,
      spurWhy: b.spurWhy,
      ignored: b.ignored
    });
  }

  function parseImportCsv(text) {
    text = String(text || "").replace(/^\uFEFF/, "").replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
    if (!text) throw new Error("File is empty");
    var lines = text.split("\n").filter(function (l) { return l.trim(); });
    if (!lines.length) throw new Error("No rows");
    var delim = (lines[0].indexOf("\t") >= 0 && lines[0].split("\t").length >= 3) ? "\t" : ",";
    var header = delim === "\t" ? lines[0].split("\t") : parseCsvLine(lines[0]);
    var keys = header.map(function (k) { return String(k || "").trim().toLowerCase(); });
    function col() {
      var names = arguments;
      var i, j;
      for (i = 0; i < names.length; i++) {
        j = keys.indexOf(names[i]);
        if (j >= 0) return j;
      }
      return -1;
    }
    var iSeen = col("seen", "n", "count");
    var iMhz = col("mhz", "frequency", "freq", "hz");
    var iDb = col("db", "maxdb", "dB".toLowerCase());
    var iBand = col("band", "label", "profile");
    var iName = col("name");
    var iNew = col("new", "isnew");
    var iBird = col("birdie", "spur");
    var iLast = col("last", "lastseen");
    var iPid = col("pid");
    var iLooks = col("looks");
    var iMode = col("mode", "modulation");
    if (iMhz < 0 && iSeen < 0) throw new Error("CSV needs a header with MHz (and usually seen)");
    if (iMhz < 0) throw new Error("CSV has no MHz / frequency column");
    var out = [];
    for (var r = 1; r < lines.length; r++) {
      var cells = delim === "\t" ? lines[r].split("\t") : parseCsvLine(lines[r]);
      var freq = hzFromCell(cells[iMhz]);
      if (!freq) continue;
      var band = iBand >= 0 ? cells[iBand] : "";
      var pidCell = iPid >= 0 ? cells[iPid] : "";
      var pid = pidFromBand(band, pidCell);
      var hit = normalizeHit({
        freq: freq,
        seen: iSeen >= 0 ? cells[iSeen] : 1,
        maxDb: iDb >= 0 ? cells[iDb] : 0,
        pid: pid,
        label: band || pid,
        name: iName >= 0 ? cells[iName] : "",
        isNew: iNew >= 0 ? cells[iNew] : "",
        birdie: iBird >= 0 ? cells[iBird] : "",
        last: iLast >= 0 ? cells[iLast] : "",
        looks: iLooks >= 0 ? cells[iLooks] : "",
        mode: iMode >= 0 ? cells[iMode] : ""
      });
      if (hit) out.push(hit);
    }
    if (!out.length) throw new Error("No peak rows found in that CSV");
    return { hits: out, tileLooks: {} };
  }

  function parseImportJson(text) {
    var o;
    try {
      o = JSON.parse(text);
    } catch (e) {
      throw new Error("Not valid JSON");
    }
    var isBackup = o && Array.isArray(o.bookmarks) && o.when && (o.reason || o.when) &&
      !Array.isArray(o.hits) && o.kind !== "owrx-toolbox";
    if (isBackup) {
      throw new Error("This is a blue-bookmark backup. Restore it from Help, not Import");
    }
    if (o && Array.isArray(o.hits)) {
      var fromHits = o.hits.map(normalizeHit).filter(Boolean);
      if (!fromHits.length) throw new Error("JSON hits array had no usable peaks");
      return { hits: fromHits, tileLooks: (o.tileLooks && typeof o.tileLooks === "object") ? o.tileLooks : {} };
    }
    if (Array.isArray(o)) {
      if (!o.length) throw new Error("JSON array is empty");
      var mapped;
      if (o[0] && (o[0].freq || o[0].seen != null) && o[0].frequency == null) {
        mapped = o.map(normalizeHit).filter(Boolean);
      } else {
        mapped = o.map(hitFromBookmarkRow).filter(Boolean);
      }
      if (!mapped.length) throw new Error("JSON array had no frequencies");
      return { hits: mapped, tileLooks: {} };
    }
    if (o && Array.isArray(o.bookmarks)) {
      var fromBm = o.bookmarks.map(hitFromBookmarkRow).filter(Boolean);
      if (!fromBm.length) throw new Error("JSON bookmarks array had no frequencies");
      return { hits: fromBm, tileLooks: (o.tileLooks && typeof o.tileLooks === "object") ? o.tileLooks : {} };
    }
    throw new Error("JSON is not a Toolbox export (need hits, bookmarks, or a bookmark array)");
  }

  function mergeImportedHits(incoming) {
    incoming.forEach(function (h) {
      var exist = findHit(h.freq, h.pid);
      if (!exist) {
        hits.push(h);
        return;
      }
      exist.seen = Math.max(exist.seen || 0, h.seen || 0);
      exist.looks = Math.max(exist.looks || 0, h.looks || 0);
      exist.maxDb = Math.max(exist.maxDb || -999, h.maxDb || -999);
      if (h.name && !exist.name) exist.name = h.name;
      if (h.last && (!exist.last || h.last > exist.last)) exist.last = h.last;
      if (h.mode && !exist.mode) exist.mode = h.mode;
    });
  }

  function applyImportedPeaks(parsed, source) {
    var incoming = parsed.hits || [];
    if (!incoming.length) throw new Error("Nothing to import");
    if (!window.confirm("Import " + incoming.length + " peaks into Peaks/Seen? Bookmarks are not changed.")) return;
    var replace = true;
    if (hits.length) {
      replace = window.confirm("Replace the current list (" + hits.length + " peaks)? OK = replace. Cancel = merge.");
    }
    if (replace) {
      hits = incoming;
      tileLooks = parsed.tileLooks && typeof parsed.tileLooks === "object" ? parsed.tileLooks : {};
    } else {
      mergeImportedHits(incoming);
      if (parsed.tileLooks) {
        Object.keys(parsed.tileLooks).forEach(function (k) {
          tileLooks[k] = Math.max(tileLooks[k] || 0, parsed.tileLooks[k] || 0);
        });
      }
    }
    classifyAll();
    saveHits();
    renderHits();
    setStatus("Imported " + incoming.length + " peaks from " + (source || "file") +
      (replace ? " (replaced list)" : " (merged)") + ".");
  }

  function importError(err, action) {
    var msg = (err && err.message) ? err.message : String(err || "unknown error");
    msg = msg.replace(/\s+/g, " ").slice(0, 180);
    setStatus(action + " failed: " + msg);
    toast(action + " failed: " + msg);
  }

  function runImportText(kind, text, source) {
    try {
      var parsed = kind === "csv" ? parseImportCsv(text) : parseImportJson(text);
      applyImportedPeaks(parsed, source);
    } catch (err) {
      importError(err, kind === "csv" ? "Import CSV" : "Import JSON");
    }
  }

  function startImport(kind, ev) {
    if (ev && ev.shiftKey) {
      var pasted = window.prompt(kind === "csv" ? "Paste Export CSV:" : "Paste Export JSON:");
      if (pasted == null) return;
      if (!String(pasted).trim()) {
        setStatus("Nothing pasted.");
        return;
      }
      runImportText(kind, pasted, "paste");
      return;
    }
    var inp = $(kind === "csv" ? "bs-csv-file" : "bs-json-file");
    if (!inp) return;
    inp.value = "";
    inp.onchange = function () {
      var f = inp.files && inp.files[0];
      if (!f) return;
      var reader = new FileReader();
      reader.onload = function () {
        runImportText(kind, String(reader.result || ""), f.name);
      };
      reader.onerror = function () {
        importError(new Error("Could not read that file"), kind === "csv" ? "Import CSV" : "Import JSON");
      };
      reader.readAsText(f);
    };
    inp.click();
  }

  function dcGuardHz(bw, dataLen) {
    bw = Number(bw) || Number(window.bandwidth) || 0;
    dataLen = Math.max(8, Number(dataLen) || (wf() && wf().length) || 512);
    if (!(bw > 0)) return Math.max(CENTER_GUARD_HZ, 80000);
    var binHz = bw / dataLen;
    /* Jump / detect: DC lobes are often fat (tens–hundreds of kHz). Notch ±8 bins,
       3% of BW, or 80 kHz — whichever is widest (never tighter than 25 kHz). */
    return Math.max(CENTER_GUARD_HZ, 80000, bw * 0.03, binHz * 8);
  }

  /** True if this candidate is the tile-centre DC spike or a needle birdie. */
  function peakLooksLikeDcOrBirdie(p, pid, data) {
    if (!p || !isFinite(p.freq) || p.freq <= 0) return true;
    var center = Number(window.center_freq) || 0;
    var bw = Number(window.bandwidth) || 0;
    data = data || wf();
    var guard = dcGuardHz(bw, data && data.length);
    var raw = isFinite(p.raw) ? p.raw : p.freq;
    if (center > 0) {
      if (Math.abs(raw - center) < guard) return true;
      if (Math.abs(p.freq - center) < guard) return true;
      var off = isFinite(p.offset) ? Math.abs(p.offset) : Math.abs(raw - center);
      if (off < guard) return true;
    }
    if (isIgnoredFreq(p.freq) || isLocked(p.freq)) return true;
    try {
      var hit = findHit(p.freq, pid || "");
      if (hit && isSpur(hit)) return true;
    } catch (eHit) {}
    /* Measure real spectral width on the waterfall (ignore inflated FM widths). */
    if (data && data.length && center > 0 && bw > 0) {
      var idx = Math.round(((raw - (center - bw / 2)) / bw) * data.length);
      if (idx < 2 || idx >= data.length - 2) return true;
      var mid = (data.length - 1) / 2;
      var notchBins = Math.max(8, Math.ceil(data.length * 0.03));
      if (Math.abs(idx - mid) <= notchBins) return true;
      var peakDb = Number(data[idx]);
      if (!isFinite(peakDb)) return true;
      var thr3 = peakDb - 3;
      var widthBins = 1;
      var j;
      for (j = idx - 1; j >= 0 && Number(data[j]) >= thr3; j--) widthBins++;
      for (j = idx + 1; j < data.length && Number(data[j]) >= thr3; j++) widthBins++;
      var left = Number(data[idx - 1]);
      var right = Number(data[idx + 1]);
      var side = Math.max(
        isFinite(left) ? left : -999,
        isFinite(right) ? right : -999
      );
      var floor = noiseFloor(data);
      /* Needle birdie: 1–2 bins wide and much louder than immediate neighbours. */
      if (widthBins <= 2 && peakDb >= floor + 6 && peakDb >= side + 4) return true;
      /* One-bin spike even if slightly wider threshold — classic LO birdie. */
      if (widthBins <= 1) return true;
    } else if ((p.width || 9) <= 2) {
      return true;
    }
    return false;
  }

  function jumpLoudest() {
    try {
    hookWaterfall();
    var sel = $("openwebrx-sdr-profiles-listbox");
    var pid = "";
    if (sel && sel.value) {
      pid = sel.value.indexOf("|") >= 0 ? sel.value.split("|").slice(1).join("|") : sel.value;
    }
    var data = wf();
    var center = Number(window.center_freq) || 0;
    var bw = Number(window.bandwidth) || 0;
    var peaks = findPeaks(pid).filter(function (p) {
      return !peakLooksLikeDcOrBirdie(p, pid, data);
    });
    /* Prefer wider / less centre-adjacent real signals over leftover spikes. */
    peaks.sort(function (a, b) {
      var aw = Math.max(1, Number(a.width) || 1);
      var bwW = Math.max(1, Number(b.width) || 1);
      var aRaw = isFinite(a.raw) ? a.raw : a.freq;
      var bRaw = isFinite(b.raw) ? b.raw : b.freq;
      var aOff = center ? Math.abs(aRaw - center) / Math.max(1, bw) : 1;
      var bOff = center ? Math.abs(bRaw - center) / Math.max(1, bw) : 1;
      var aScore = (Number(a.db) || 0) + Math.min(6, aw) * 0.35 + Math.min(aOff, 0.25) * 8;
      var bScore = (Number(b.db) || 0) + Math.min(6, bwW) * 0.35 + Math.min(bOff, 0.25) * 8;
      return bScore - aScore;
    });
    if (!peaks.length) {
      var blocked = blockingIssue();
      setStatus(blocked
        ? blocked.title + " — " + blocked.fix
        : "No usable peak on this tile (DC spike / birdies skipped). Wait a few seconds after the radio connects, or check the SDR is started.");
      renderHealth();
      return;
    }
    var p = peaks[0];
    if (!window.UI || typeof UI.setFrequency !== "function") {
      setStatus("Tune API is missing (UI.setFrequency). Update OpenWebRX+ or open the full receiver UI.");
      renderHealth();
      return;
    }
    pluginSetFrequency(p.freq);
    if (window.UI && typeof UI.setModulation === "function") {
      try { UI.setModulation(guessMode(pid), ""); } catch (e) {}
    }
    setStatus("Jumped to " + (icao833(p.freq) || fmtMhz(p.freq)) + " (" + Math.round(p.db) + " dB) — this tile only (DC/birdies skipped).");
    } catch (err) {
      setStatus(friendlyError(err, "Jump loudest"));
      toast(friendlyError(err, "Jump loudest"));
      renderHealth();
    }
  }

