        min: num.min !== "" && isFinite(Number(num.min)) ? Number(num.min) : 0,
        max: num.max !== "" && isFinite(Number(num.max)) ? Number(num.max) : 100,
        step: num.step !== "" && isFinite(Number(num.step)) ? Number(num.step) : 1
